  ui_story_5053_50530101_2_dialog_content = "（あれ…鳥の鳴き声がする？）",
  ui_story_5053_50530101_3_dialog_content = "（天空ノ谷の小鳥たちもいつもこうやって僕を起してくれるんだよね。\n寝坊したくてもできないよ）",
