  ui_story_5053_50530101_6_dialog_content = "（いや、違う。ここは天空ノ谷じゃない…白夜城？）",
  ui_story_5053_50530101_7_dialog_content = "（そうだ、僕は白夜城にいたんだ！\nあの時ミヤと一緒に「記憶の鏡晶」の世界に入って、それから…）",
