  ui_story_5053_50530101_16_dialog_content = "<size=30>どうして小声で話す必要があるんですか？</size>",
  ui_story_5053_50530101_17_dialog_content = "<size=30>見ろ</size>",
  ui_story_5053_50530101_18_dialog_content = "殿下、すべて準備が整いました。\nパレードの馬車が外で待機しております。いつでもご出発になれます。",
  ui_story_5053_50530101_19_dialog_content = "うむ、分かった。カレン、先に乗りなさい。",
