  ui_story_5053_50530101_22_dialog_content = "…はい。分かりました。",
  ui_story_5053_50530101_23_dialog_content = "カレン、先に馬車でお父様をお待ちしています。",
  ui_story_5053_50530101_24_dialog_content = "カレン殿下は幼くていらっしゃいますが、大局を見据えることができます。\nカレン殿下はまさに白夜城の幸福そのものです。",
  ui_story_5053_50530101_25_dialog_content = "…",
  ui_story_5053_50530101_26_dialog_content = "奥様のことが気がかりですか？",
  ui_story_5053_50530101_27_dialog_content = "ヨシュアはこれまで健康で、身体の不調を訴えることなど稀だった。\n特に今日のような特別な日はそうだった。",
  ui_story_5053_50530101_28_dialog_content = "ここのところ、奥様は貴族のご夫人方に城主様の政策を広めようと、\nそれは努力していらっしゃいました。",
  ui_story_5053_50530101_29_dialog_content = "…仕方ない。",
  ui_story_5053_50530101_30_dialog_content = "Ms.ロト、お主は残って夫人の世話を頼む。\n何かあれば、すぐに報告せよ。",
  ui_story_5053_50530101_31_dialog_content = "承知いたしました、殿下。",
  ui_story_5053_50530101_32_dialog_content = "あれは…若い頃のソルラドさんですよね？\nどういうことですか！？僕たちまさか…",
  ui_story_5053_50530101_33_dialog_content = "水晶の中から出られてはおらぬ。",
  ui_story_5053_50530101_34_dialog_content = "お父様…",
  ui_story_5053_50530101_35_dialog_content = "…お父様。それから…PlayerName。",
  ui_story_5053_50530101_36_dialog_content = "私たち…げ、現実の世界に戻れたの？",
  ui_story_5053_50530101_37_dialog_content = "ここは元の世界ではない。",
  ui_story_5053_50530101_38_dialog_content = "え？元の世界ではないのですか？\nでも、記録された一日が終わるまでに出られなかった場合…",
  ui_story_5053_50530101_39_dialog_content = "私たち…永遠に「記憶の鏡晶」の中に\n閉じ込められてしまったの？",
  ui_story_5053_50530101_40_dialog_content = "僕にもよく分からない…\nジャキーニに聞くしかないね。",
  ui_story_5053_50530101_41_dialog_content = "すぅ…すぅ…すぅ…",
  ui_story_5053_50530101_42_dialog_content = "ジャキーニ！",
  ui_story_5053_50530101_43_dialog_content = "ウィスパー…起こさないでくださいよ。\nもう少し寝させてください…",
  ui_story_5053_50530101_44_dialog_content = "ジャキーニ、PlayerNameだよ！\n緊急事態なんだ、早く起きて！",
  ui_story_5053_50530101_45_dialog_content = "ん？な～んだ、PlayerNameでしたか。\nふわぁ～っ――",
  ui_story_5053_50530101_46_dialog_content = "あれ？ここは…",
  ui_story_5053_50530101_47_dialog_content = "シーッ！",
  ui_story_5053_50530101_48_dialog_content = "何か聞こえなかったか？",
  ui_story_5053_50530101_49_dialog_content = "ああ、茂みの方から何か聞こえたな。",
  ui_story_5053_50530101_50_dialog_content = "見に行こう。",
  ui_story_5053_50530101_51_dialog_content = "グゥ…？",
  ui_story_5053_50530101_52_dialog_content = "なんだ、ウサギか。",
  ui_story_5053_50530101_53_dialog_content = "<size=50>グゥ――チチ！</size>",
  ui_story_5053_50530101_54_dialog_content = "驚いたじゃないか。\nってか…ウサギって鳴くんだな。",
  ui_story_5053_50530101_55_dialog_content = "たかがウサギ1匹放っておいてもどうってことない。\n構わず巡回を続けよう。",
  ui_story_5053_50530101_56_dialog_content = "危なかった…",
  ui_story_5053_50530101_57_dialog_content = "機転を利かせてカレブさんをウサギに変身させて正解でした。\nうまくごまかせましたよ！",
  ui_story_5053_50530101_58_dialog_content = "チチチチッ！",
  ui_story_5053_50530101_59_dialog_content = "でも、おかしいですね。\nなんで隠れなきゃいけないんです？",
  ui_story_5053_50530101_60_dialog_content = "ジャキーニ、我々はまだ「記憶の鏡晶」の世界の中なのだ。",
  ui_story_5053_50530101_61_dialog_content = "ええ？そんなはずありませんよ！？\n呪文はあってますし、やり方も…問題ありませんでしたよ！？",
  ui_story_5053_50530101_62_dialog_content = "だってあの時…",
  ui_story_5053_50530101_63_dialog_content = "確か12時の鐘が鳴り始めて、\nすでに一日の終わりを迎えてました。",
  ui_story_5053_50530101_64_dialog_content = "水晶の中の世界から出るには、<color=#FFB400>時間を逆流させる</color>呪文と\n<color=#FFB400>「記憶の鏡晶」から出る</color>呪文を同時に唱えなければいけません。",
  ui_story_5053_50530101_65_dialog_content = "あ…さっきMs.ロトが若い頃のソルラドさんとカレンを送り出してたよ。\nということは…",
  ui_story_5053_50530101_66_dialog_content = "ということは…「記憶の鏡晶」から出る呪文は<color=#FFB400>発動せず</color>、\n時間を逆流させる呪文だけ<color=#FFB400>発動した</color>ってことですか？",
  ui_story_5053_50530101_67_dialog_content = "もしかして、あの怪物の影響なの…？",
  ui_story_5053_50530101_68_dialog_content = "あ、思い出しました！あの怪物、今思い出してもゾッとします！",
  ui_story_5053_50530101_69_dialog_content = "頭にたくさん翼が生えていて、\nそのぎっしり生えた様子が何とも恐ろしかったですね。",
  ui_story_5053_50530101_70_dialog_content = "まるで…",
  ui_story_5053_50530101_71_dialog_content = "まるで黒い天使がこの世に絶望をもたらしたみたいだったわ。",
  ui_story_5053_50530101_72_dialog_content = "そう！<color=#FFB400>「黒の天使」</color>です！",
  ui_story_5053_50530101_73_dialog_content = "はぁ…でも、そんなことに構ってられませんよ。\n今すぐここから出る呪文を唱えて、みなさんを出してあげますね！",
  ui_story_5053_50530101_74_dialog_content = "あの…",
  ui_story_5053_50530101_75_dialog_content = "チチチチッ！",
  ui_story_5053_50530101_76_dialog_content = "さきにカレブ叔父様を元に戻してくれないかしら？",
  ui_story_5053_50530101_77_dialog_content = "あ、忘れるところでした！",
  ui_story_5053_50530101_78_dialog_content = "ムタティオ～ムタティオ～ムタティオ！",
  ui_story_5053_50530101_79_dialog_content = "カレブさんを元の姿に戻してください！",
  ui_story_5053_50530101_80_dialog_content = "アブラカダブラ！",
  ui_story_5053_50530101_81_dialog_content = "<color=#e8d9bb>ボンッ！</color>",
  ui_story_5053_50530101_82_dialog_content = "…",
  ui_story_5053_50530101_83_dialog_content = "「記憶の鏡晶」の隙間には…巨人の国がありました…",
  ui_story_5053_50530101_84_dialog_content = "巨人の国は、消えたのですか？",
  ui_story_5053_50530101_85_dialog_content = "カレブさん、おかえりなさい！",
  ui_story_5053_50530101_86_dialog_content = "おかえりなさい…？",
  ui_story_5053_50530101_87_dialog_content = "帰って来たのですか？ですが、まだ姉さんの…クソッ！",
  ui_story_5053_50530101_88_dialog_content = "え？何を言ってるんです？",
  ui_story_5053_50530101_89_dialog_content = "…カレブさん、実は最初から不思議に思ってたんですよ。",
  ui_story_5053_50530101_90_dialog_content = "勝手に単独行動したり、「記憶の鏡晶」を盗みに行ったり…\nいったい何がしたいんです？",
  ui_story_5053_50530101_91_dialog_content = "<color=#e8d9bb>サッ――</color>",
  ui_story_5053_50530101_92_dialog_content = "誰です？衛兵に見つかったんですか！？",
  ui_story_5053_50530101_93_dialog_content = "ジャキーニ、武器を…",
  ui_story_5053_50530101_94_dialog_content = "「黒の天使」が現れたよ！",
  ui_story_5053_50530101_95_dialog_content = "こ…ここなの…？",
  ui_story_5053_50530102_1_dialog_content = "こ…ここなの…？",
  ui_story_5053_50530102_2_dialog_content = "水晶玉よ、お願いします！",
  ui_story_5053_50530102_3_dialog_content = "「黒の天使」？なんでまた現れたんです？\n時間は戻ったんじゃないんですか？",
  ui_story_5053_50530102_4_dialog_content = "ね、姉さんの声です…",
  ui_story_5053_50530102_5_dialog_content = "ここ…にいたのね！",
  ui_story_5053_50530102_6_dialog_content = "白夜！庇護を！",
  ui_story_5053_50530102_7_dialog_content = "カレブ、戦場で余計な考えは禁物だ！",
  ui_story_5053_50530102_8_dialog_content = "あなたに言われる筋合いはありません！\nこれはいったいどういう…",
  ui_story_5053_50530102_9_dialog_content = "侵入者め、武器を捨てろ！",
  ui_story_5053_50530102_10_dialog_content = "城主様の宮殿に押し入り、\n無法を働くとは大した度胸だ！",
  ui_story_5053_50530102_11_dialog_content = "はぁっ――！",
  ui_story_5053_50530102_12_dialog_content = "か、怪物だと！？あ、あれはいったい何なんだ！？",
  ui_story_5053_50530102_13_dialog_content = "すぐに応援を要請しろ！",
  ui_story_5053_50530102_14_dialog_content = "わ、分かった…",
  ui_story_5053_50530102_15_dialog_content = "ダ…ニエル…！",
  ui_story_5053_50530102_16_dialog_content = "…",
  ui_story_5053_50530102_17_dialog_content = "ど、どうしてなの…？\nどうして「黒の天使」はお父様ばかりを狙うの？",
  ui_story_5053_50530102_18_dialog_content = "しかも「黒の天使」はずっと君たちの名前を呼んでるよ。\nまさか君たちのこと知ってるの？",
  ui_story_5053_50530102_19_dialog_content = "でも…私は知らないわ…",
  ui_story_5053_50530102_20_dialog_content = "やあああ――！",
  ui_story_5053_50530102_21_dialog_content = "支配者の刃！",
  ui_story_5053_50530102_22_dialog_content = "うっ…",
  ui_story_5053_50530102_23_dialog_content = "今のお主の力、初めて戦った時とはだいぶ見劣りするな。",
  ui_story_5053_50530102_24_dialog_content = "はぁっ――！！",
  ui_story_5053_50530102_25_dialog_content = "…だが、相変わらず粘り強い。",
  ui_story_5053_50530102_26_dialog_content = "僕に指揮させてください！感知能力はかなり弱くなっていますが、\n戦いのサポートに支障はありません！",
  ui_story_5053_50530102_27_dialog_content = "感謝する。だが、その役は他におる。",
  ui_story_5053_50530102_28_dialog_content = "ミヤ、お前ならいかにこの局面を打開する？",
  ui_story_5053_50530102_29_dialog_content = "わ、私ですか！？私が指揮を…？",
  ui_story_5053_50530102_30_dialog_content = "左様だ。余を手中の駒だと思え。",
  ui_story_5053_50530102_31_dialog_content = "さあ、どこに置くのだ？",
  ui_story_5053_50530102_32_dialog_content = "ええと…お父様はこのまま「黒の天使」を引き付けて前方へ進み…\n私が後ろに回り込んで同時に攻撃をするのはどうでしょう？",
  ui_story_5053_50530102_33_dialog_content = "手ぬるい！",
  ui_story_5053_50530102_34_dialog_content = "だ、だったら…",
  ui_story_5053_50530102_35_dialog_content = "お前の手中の駒は余一人ではなかろう！？",
  ui_story_5053_50530102_36_dialog_content = "ごめんなさい。私には思いつきません…",
  ui_story_5053_50530102_37_dialog_content = "ミヤ、緊張しないで。君なら出来るよ！",
  ui_story_5053_50530102_38_dialog_content = "PlayerName…",
  ui_story_5053_50530102_39_dialog_content = "（これって騎士団の訓練と同じだわ。\nお父様は戦いを教えようとしてくださってるのかしら？）",
  ui_story_5053_50530102_40_dialog_content = "（だったら、お父様を失望させるわけには…\nいいえ、騎士の名にキズを付けるわけにはいかないわ！）",
  ui_story_5053_50530102_41_dialog_content = "…わかりました。",
  ui_story_5053_50530102_42_dialog_content = "お父様が「黒の天使」を引き付けている隙に…\nジャキーニはここから、叔父様は反対側から横挟みにして――",
  ui_story_5053_50530102_43_dialog_content = "三角形の陣形をとって、包囲攻撃すれば「黒の天使」も…\nたぶん、倒せるんじゃないでしょうか？",
  ui_story_5053_50530102_44_dialog_content = "うわぁ、本格的な作戦ですね！\n了解で～す！",
  ui_story_5053_50530102_45_dialog_content = "悪くない戦術です。それで行きましょう。",
  ui_story_5053_50530102_46_dialog_content = "ここに…いたのね…",
  ui_story_5053_50530102_47_dialog_content = "お主はいったい何者だ？何ゆえ我らを追う？",
  ui_story_5053_50530102_48_dialog_content = "ダ…ニエル…！！！",
  ui_story_5053_50530102_49_dialog_content = "（「黒の天使」の動きが急にゆっくりになった！？\n攻撃のチャンスだ！）",
  ui_story_5053_50530102_50_dialog_content = "今よ、一斉攻撃よ！",
  ui_story_5053_50530102_51_dialog_content = "申し訳ありません…！",
  ui_story_5053_50530102_52_dialog_content = "水晶玉よ、お願いします！！",
  ui_story_5053_50530102_53_dialog_content = "これが私の力よ！",
  ui_story_5053_50530102_54_dialog_content = "ああああ――！",
  ui_story_5053_50530102_55_dialog_content = "ぜんぶ命中しましたよ！私たち、スゴくありません！？",
  ui_story_5053_50530102_56_dialog_content = "い…痛い…！！",
  ui_story_5053_50530102_57_dialog_content = "とても苦しそうだわ…",
  ui_story_5053_50530102_58_dialog_content = "こういう時にお情けは無用です！\nずっと訳もなく攻撃してきたのは「黒の天使」なんですから！",
  ui_story_5053_50530102_59_dialog_content = "そうね。戦場で情をかけるのは禁物ね…\nジャキーニの言う通りだわ。",
  ui_story_5053_50530102_60_dialog_content = "攻撃が効いたのかな…？",
  ui_story_5053_50530102_61_dialog_content = "ああ…ああああ――！",
  ui_story_5053_50530102_62_dialog_content = "あれ…ずいぶん不気味な叫び声をあげてますね。",
  ui_story_5053_50530102_63_dialog_content = "大変だ！「黒の天使」が力をためてる！\nすぐに攻撃が来るよ！",
  ui_story_5053_50530102_64_dialog_content = "ど、どうすれば…",
  ui_story_5053_50530102_65_dialog_content = "ミヤ、よくやったぞ。この先は余に預けよ。",
  ui_story_5053_50530102_66_dialog_content = "お父様…？",
  ui_story_5053_50530102_67_dialog_content = "皆退がれ！",
  ui_story_5053_50530102_68_dialog_content = "ダニ…",
  ui_story_5053_50530102_69_dialog_content = "ダ…ニエル…！！！",
  ui_story_5053_50530102_70_dialog_content = "お主はそれほどまでに余と戦いたいのか？",
  ui_story_5053_50530102_71_dialog_content = "ならば、叶えてやろう。",
  ui_story_5053_50530102_72_dialog_content = "次はお主の名を墓に刻め！",
  ui_story_5053_50530102_73_dialog_content = "<color=#e8d9bb>ドーン――！！</color>",
  ui_story_5053_50530102_74_dialog_content = "う…うう…",
  ui_story_5053_50530102_75_dialog_content = "「黒の天使」はどこへ行ったのです？",
  ui_story_5053_50530102_76_dialog_content = "外の道から逃げたみたいだ。",
  ui_story_5053_50530102_77_dialog_content = "城主様の一撃、まさに天地を切り裂く勢いでしたね！",
  ui_story_5053_50530102_78_dialog_content = "いくら「黒の天使」が強くたって、大きなダメージを受けてるはずです。\nそう遠くへは逃げられないんじゃないですか？",
  ui_story_5053_50530102_79_dialog_content = "…",
  ui_story_5053_50530102_80_dialog_content = "叔父様、あの「黒の天使」のことが気になりますか？",
  ui_story_5053_50530102_81_dialog_content = "あの声は確かに…いいえ、姉さんが怪物であるはずありません。",
  ui_story_5053_50530102_82_dialog_content = "ジャキーニ、今のうちに呪文を唱えよ。",
  ui_story_5053_50530102_83_dialog_content = "あ…そうでした！ずっと邪魔してた「黒の天使」がようやくいなくなったんです。\n今度こそ、みなさんを連れ出しますよ！",
  ui_story_5053_50530102_84_dialog_content = "アド・プラエセンス～アド・プラエセンス～アド・プラエセンス～。",
  ui_story_5053_50530102_85_dialog_content = "私たちを現実の世界へ帰してください！",
  ui_story_5053_50530102_86_dialog_content = "アブラカダブラ！",
  ui_story_5053_50530102_87_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5053_50530102_88_dialog_content = "何も変わってないみたいね…",
  ui_story_5053_50530102_89_dialog_content = "もう一度いきますよ！",
  ui_story_5053_50530102_90_dialog_content = "アド・プラエセンス～アド・プラエセンス～アド・プラエセンス～。",
  ui_story_5053_50530102_91_dialog_content = "私たちを現実の世界へ帰してください！\nアブラカダブラ！",
  ui_story_5053_50530102_92_dialog_content = "ジャキーニ、その呪文、本当にあってるの？",
  ui_story_5053_50530102_93_dialog_content = "もちろん、あってますって！みなさん、手はつなぎました？\nどれどれ…つないでますね…",
  ui_story_5053_50530102_94_dialog_content = "さっきは混乱してたので、\nしっかり手をつなげてなかったのかと思ったんですけど…",
  ui_story_5053_50530102_95_dialog_content = "手をちゃんとつないでるのに、なんでダメなんです！？",
  ui_story_5053_50530102_96_dialog_content = "前に呪文を唱えた時はこの世界の「記憶の鏡晶」を持ってたわ。\nそれが原因じゃないかしら？",
  ui_story_5053_50530102_97_dialog_content = "いいえ、<color=#FFB400>時間を逆流させる時だけこの世界の「記憶の鏡晶」が必要なんです</color>――\nあれはママの作った緊急危険回避装置ですから。",
  ui_story_5053_50530102_98_dialog_content = "この世界を離れるっていう通常の呪文には必要ないんです！",
  ui_story_5053_50530102_99_dialog_content = "他の可能性はないのか？",
  ui_story_5053_50530102_100_dialog_content = "あるいは…<color=#FFB400>全員がそろってない</color>…",
  ui_story_5053_50530102_101_dialog_content = "全員がそろってない？",
  ui_story_5053_50530102_102_dialog_content = "安全を考慮して、「記憶の鏡晶」に入るには起動した人の操作が、\n元の世界に戻るためには、中に入った全員がそろうことが条件になってるんです。",
  ui_story_5053_50530102_103_dialog_content = "入ってくる時は、呪文でこの決まりを破っちゃいましたが…\n出る時はそうもいきません！",
  ui_story_5053_50530102_104_dialog_content = "みなさんそろってますよね？\n私の目、おかしくなってませんよね？",
  ui_story_5053_50530102_105_dialog_content = "僕たち以外にも誰か中に引き込まれちゃったってこと？",
  ui_story_5053_50530102_106_dialog_content = "あるいは…私たちが入る前に、\n誰かが他の方法ですでに「記憶の鏡晶」の中に入ってたのかも…",
  ui_story_5053_50530102_107_dialog_content = "でも、鏡晶を起動した人は亡くなってるし、\nそんなことできるんでしょうか？",
  ui_story_5053_50530102_108_dialog_content = "…",
  ui_story_5053_50530102_109_dialog_content = "ふ、夫人自らいらしてくださったのですか！？",
  ui_story_5053_50530102_110_dialog_content = "誠に申し訳ございません。\n私ども衛兵の力不足で夫人のお休みを妨げてしまいました。",
  ui_story_5053_50530102_111_dialog_content = "大丈夫よ。それより、何があったのか教えてくれるかしら？",
  ui_story_5053_50530102_112_dialog_content = "もちろんです。\nさきほどお庭で正体不明の侵入者がある怪物と戦いました。",
  ui_story_5053_50530102_113_dialog_content = "そのうちの1人が容貌も服装もヴェロニカ殿下とよく似ていたのですが、\n私も確信はございません…",
  ui_story_5053_50530102_114_dialog_content = "ヴェロニカ？そうだったの、大変だったわね。",
  ui_story_5053_50530201_1_dialog_content = "あの…みなさん本当に食べないんですか？\n食べないなら、私が全部いただいちゃいますよ？",
  ui_story_5053_50530201_2_dialog_content = "よく食べられるね…",
  ui_story_5053_50530201_3_dialog_content = "さっき僕たちは城主夫人の庭で戦ったんだよ。\nいったいどう説明したらいいんだろう？",
  ui_story_5053_50530201_4_dialog_content = "まあまあ、気楽にいきましょうよ。\n焦っても解決しませんって。",
  ui_story_5053_50530201_5_dialog_content = "はぁ…君っていつだって楽観的だね。\n本当にうらやましいな…",
  ui_story_5053_50530201_6_dialog_content = "ヨシュアは他人を責め立てなどせぬ。",
  ui_story_5053_50530201_7_dialog_content = "人を遣わして我々をここに来させ、さらに菓子まで出したのは、\n礼をもって接しようという態度の表れだ。困らせるつもりはないのだ。",
  ui_story_5053_50530201_8_dialog_content = "フンッ、それは幸いですね。",
  ui_story_5053_50530201_9_dialog_content = "もし、<color=#FFB400>もう1人</color>もこの場にいたなら、\nとうの昔に白夜城の監獄に入れられていたでしょうがね。",
  ui_story_5053_50530201_10_dialog_content = "もう1人？誰のことです？",
  ui_story_5053_50530201_11_dialog_content = "…",
  ui_story_5053_50530201_12_dialog_content = "カレブの言う「もう1人」とはかつての余のことだ。",
  ui_story_5053_50530201_13_dialog_content = "おや、殿下もご自覚がおありだったのですね。",
  ui_story_5053_50530201_14_dialog_content = "と、とにかく！この世界の「ヨシュア」夫人が\n現れたってことは――",
  ui_story_5053_50530201_15_dialog_content = "少なくともこの世界の「ヨシュア」夫人は、\n黒の天使じゃないってことですよね。",
  ui_story_5053_50530201_16_dialog_content = "我々が今考えるべきはそこではなかろう。\nジャキーニ、他に誰が「記憶の鏡晶」の中に入ったか調べられるか？",
  ui_story_5053_50530201_17_dialog_content = "もちろん、方法はあります。",
  ui_story_5053_50530201_18_dialog_content = "この世界の「記憶の鏡晶」さえあればいいんです！",
  ui_story_5053_50530201_19_dialog_content = "この世界の「記憶の鏡晶」なら、時間を逆流させる他にも、\n<color=#FFB400>誰が「記憶の鏡晶」の中の幻影で、誰が本物なのか検証できるんです</color>。",
  ui_story_5053_50530201_20_dialog_content = "どこにいるかまでは分かりませんが…",
  ui_story_5053_50530201_21_dialog_content = "それに1つ欠点があるんです。\n一人一人検証するしかないので時間がかかるんですよ。",
  ui_story_5053_50530201_22_dialog_content = "白夜城は人が多いし、\n一人一人調べてたら、いつ終わるか…",
  ui_story_5053_50530201_23_dialog_content = "大丈夫ですよ。緊急危険回避装置がある限り、\n何回でも時間を戻せますから！",
  ui_story_5053_50530201_24_dialog_content = "ただ、この世界の運行を維持している光力を使うことになるので…\nむやみに発動できませんけど。",
  ui_story_5053_50530201_25_dialog_content = "ならば今すべきことは「記憶の鏡晶」を探すことだな。\n「黒の天使」の件は改めて話すとしよう。",
  ui_story_5053_50530201_26_dialog_content = "お探しのものはこれかしら？",
  ui_story_5053_50530201_27_dialog_content = "夫人が持ってるのは…「記憶の鏡晶」ですか！？",
  ui_story_5053_50530201_28_dialog_content = "ヨシュア夫人、私たちの話を聞いてたんですか？\nどうして「記憶の鏡晶」を探してるって分かったんです？",
  ui_story_5053_50530201_29_dialog_content = "ふふ、そんなに慌てないで。\nまずは「記憶の鏡晶」を見てちょうだい。",
  ui_story_5053_50530201_30_dialog_content = "これは…そ、そそ、そんな！？",
  ui_story_5053_50530201_31_dialog_content = "ヨシュア夫人…<color=#FFB400>「本物のヨシュア夫人」</color>だったんですか！",
  ui_story_5053_50530201_32_dialog_content = "！！！",
  ui_story_5053_50530201_33_dialog_content = "姉さんですと…なぜ姉さんが…？\n本当に姉さんなのですか？",
  ui_story_5053_50530201_34_dialog_content = "わたくしでなければ、誰だというの？\nかわいい天才君？",
  ui_story_5053_50530201_35_dialog_content = "……",
  ui_story_5053_50530201_36_dialog_content = "ジャキーニ、確かか？",
  ui_story_5053_50530201_37_dialog_content = "絶対に間違いありません！\n私の目に問題がない限り、本当です！",
  ui_story_5053_50530201_38_dialog_content = "お母様が…本物？",
  ui_story_5053_50530201_39_dialog_content = "もちろん、本物よ。",
  ui_story_5053_50530201_40_dialog_content = "ヴェロニカは騎士団に入ったばかりの頃と変わらないわね。\n記憶の中のままだわ。",
  ui_story_5053_50530201_41_dialog_content = "ううっ…そ、それは…",
  ui_story_5053_50530201_42_dialog_content = "ノラが…あの女がヴェロニカの…ミヤの身体を改造したのです…\nそのせいでミヤの身体は永遠に13歳の頃のままに…",
  ui_story_5053_50530201_43_dialog_content = "ですが、おかしいではないですか…？\nこの目で確かめたのですよ…",
  ui_story_5053_50530201_44_dialog_content = "え？どういう意味です？",
  ui_story_5053_50530201_45_dialog_content = "12年前の「ソルラド家記念日」、ミヤ…つまり、ヴェロニカは、\n騎士団の任務に当たった際、暗鬼にシードを植え付けられた。",
  ui_story_5053_50530201_46_dialog_content = "その後啓光の実験室に送り「治療」したが、\n「治療」とは名ばかり、実際は暗鬼と反逆者の仕組んだ罠だったのだ。",
  ui_story_5053_50530201_47_dialog_content = "ヨシュアはヴェロニカを救うために独り敵に立ち向かった。",
  ui_story_5053_50530201_48_dialog_content = "その結果、ヴェロニカを救い出すことに成功はしたが、\nヨシュアも「シード」を植え付けられ…",
  ui_story_5053_50530201_49_dialog_content = "病に散々苦しめられた挙句…",
  ui_story_5053_50530201_50_dialog_content = "<color=#FFB400>自ら命を絶った</color>",
  ui_story_5053_50530201_51_dialog_content = "だが今、そのヨシュアが「記憶の鏡晶」の中に現れた。\nどういうことか説明してもらおう。",
  ui_story_5053_50530201_52_dialog_content = "ソルラド！それが12年ぶりに会った妻に対する態度ですか！？",
  ui_story_5053_50530201_53_dialog_content = "いいのよ、カレブ。みなさんの安全を守るために警戒は必要よ。\nダニエルは間違っていないわ。",
  ui_story_5053_50530201_54_dialog_content = "分かりました…姉さんがそう言うのなら…",
  ui_story_5053_50530201_55_dialog_content = "では、ダニエルの話の続きをしましょう。",
  ui_story_5053_50530201_56_dialog_content = "その通りよ。わたくしは病に苦しんだ末…",
  ui_story_5053_50530201_57_dialog_content = "<color=#e8d9bb>数年前、ソルラド家の邸宅</color>",
  ui_story_5053_50530201_58_dialog_content = "ゲホッゴホゴホッ…ダニエル、殺してちょうだい。",
  ui_story_5053_50530201_59_dialog_content = "ヨシュア、むごいことを言うな…",
  ui_story_5053_50530201_60_dialog_content = "「シード」に抗えば抗うほど、\n「シード」はわたくしを苦しめる。",
  ui_story_5053_50530201_61_dialog_content = "はっきりと分かるの。\n「シード」は今この身体の支配権を奪おうとしている。",
  ui_story_5053_50530201_62_dialog_content = "…お主を救う方法を必ず見つける。余を信じてくれ！",
  ui_story_5053_50530201_63_dialog_content = "ヨハネスの医療チームを覚えておるか？\nそう…そうだ、ヨハネスは名医だ。あやつに頼もう。",
  ui_story_5053_50530201_64_dialog_content = "今すぐ人を遣り、ヨハネスの行方を探させる！",
  ui_story_5053_50530201_65_dialog_content = "ゆっくり休んでおるのだぞ。\n必ずよい知らせを持ってくる。",
  ui_story_5053_50530201_66_dialog_content = "無駄よ、ダニエル。そんなことしても無駄なのよ…",
  ui_story_5053_50530201_67_dialog_content = "ううっ、あああ――",
  ui_story_5053_50530201_68_dialog_content = "抗うのはよしなさい。大人しく身体をよこせばいいのよ。",
  ui_story_5053_50530201_69_dialog_content = "あなたの思い通りにはさせないわ。",
  ui_story_5053_50530201_70_dialog_content = "身体を渡すくらいなら、心臓に短剣を突き刺すわ！",
  ui_story_5053_50530201_71_dialog_content = "なんですって…！短剣をどけなさい！",
  ui_story_5053_50530201_72_dialog_content = "断るわ！",
  ui_story_5053_50530201_73_dialog_content = "どけなさい！！",
  ui_story_5053_50530201_74_dialog_content = "うう…",
  ui_story_5053_50530201_75_dialog_content = "<color=#e8d9bb>ガチャン！</color>",
  ui_story_5053_50530201_76_dialog_content = "「記憶の鏡晶」…？",
  ui_story_5053_50530201_77_dialog_content = "何をするつもり！？やめなさい！！",
  ui_story_5053_50530201_78_dialog_content = "一緒にあの日に戻りましょう…",
  ui_story_5053_50530201_79_dialog_content = "<color=#e8d9bb>ドンッ！</color>",
  ui_story_5053_50530201_80_dialog_content = "姉さん？何事ですか？今の大きな音は何です？",
  ui_story_5053_50530201_81_dialog_content = "なぜ答えないのですか…？どうか脅かさないでください。\n中に入りますよ？",
  ui_story_5053_50530201_82_dialog_content = "ね、姉さん…？",
  ui_story_5053_50530201_83_dialog_content = "<size=50>姉さん！！</size>",
  ui_story_5053_50530201_84_dialog_content = "シードのせいで、わたくしの中に<color=#FFB400>2つの人格</color>が現れた。",
  ui_story_5053_50530201_85_dialog_content = "1人はいつものわたくし、もう1人は理性に欠け、\n狂気に満ちた怪物のような人格よ。",
  ui_story_5053_50530201_86_dialog_content = "もう1つの人格は大きくなる一方で、わたくしの身体を奪い、\n周りの人たちを傷つけようともくろみ始めた。",
  ui_story_5053_50530201_87_dialog_content = "そんなこと絶対に許されない。\nだから、わたくしはもう1つの人格と戦った。",
  ui_story_5053_50530201_88_dialog_content = "2つの人格が1つの身体の中で戦い続け、\n来る日も来る日も張り裂けるような頭痛に苦しみ続けた。",
  ui_story_5053_50530201_89_dialog_content = "けれど、あの怪物はまるで感覚がないかのように、\nまったく影響を受けずに徐々にわたくしを圧倒するようになったの…",
  ui_story_5053_50530201_90_dialog_content = "一方のわたくしは、もう1つの人格との争いの中で衰弱し、\n今にも壊れそうだった。負けは明白だったわ。",
  ui_story_5053_50530201_91_dialog_content = "だから、たとえ勝てなくとも、相手のもくろみを完全につぶす方法を考え出したの。\nその方法というのが――",
  ui_story_5053_50530201_92_dialog_content = "<color=#FFB400>2人もろとも「記憶の鏡晶」の中に閉じ込める</color>ことよ。",
  ui_story_5053_50530201_93_dialog_content = "わたくしは死を覚悟して、\n自分と怪物をこの世界に閉じ込めた。",
  ui_story_5053_50530201_94_dialog_content = "わたくしたちは2つで1つ。\nわたくしさえこの世界を離れることを拒めば、怪物も一緒に残るしかないの。",
  ui_story_5053_50530201_95_dialog_content = "本当に長い…争いだったわ。",
  ui_story_5053_50530201_96_dialog_content = "夜中の12時の鐘が鳴り終わり、\nルールを破ったわたくしたちはこの世界の一部となった。",
  ui_story_5053_50530201_97_dialog_content = "2人とも記憶を失い、この世界の「ヨシュア」として一つになったの。\nそして永遠に同じ日を繰り返し過ごしてきたのよ。",
  ui_story_5053_50530201_98_dialog_content = "あなたたちがここへ来るまで。",
  ui_story_5053_50530201_99_dialog_content = "あなたたちが来たことで、\nわたくしたちの記憶は呼び覚まされた。",
  ui_story_5053_50530201_100_dialog_content = "目覚めた怪物はわたくしと別々になろうともがいた。",
  ui_story_5053_50530201_101_dialog_content = "そして、<color=#FFB400>わたくしの持っていたすべての力を奪い</color>、\n行方をくらまして、「記憶の鏡晶」から出ようとしているの。",
  ui_story_5053_50530201_102_dialog_content = "とても絶望的な状況だけれど、でも今回は…",
  ui_story_5053_50530201_103_dialog_content = "わたくしも一人じゃないわ。",
  ui_story_5053_50530201_104_dialog_content = "…",
  ui_story_5053_50530201_105_dialog_content = "し、信じられないような話ですね…\nつまり、私たちを襲った<color=#FFB400>「黒の天使」がもう1人のヨシュア夫人</color>ってことですよね？",
  ui_story_5053_50530201_106_dialog_content = "「黒の天使」？あの怪物に名前を付けたのね…\nええ、そう理解してくれて構わないわ。",
  ui_story_5053_50530201_107_dialog_content = "あの時寝室で話したことは、余とヨシュアしか知らぬ。\n細部まで少しも違わなかった。",
  ui_story_5053_50530201_108_dialog_content = "ヨシュア、真にお主だったのか…",
  ui_story_5053_50530201_109_dialog_content = "よかった…ようやく信じてくれたのね。",
  ui_story_5053_50530201_110_dialog_content = "うう…お母様…本当にお母様なのね…",
  ui_story_5053_50530201_111_dialog_content = "あらあら、泣いたら可愛い顔が台無しよ。",
  ui_story_5053_50530201_112_dialog_content = "姉さん…まさかここにいらしたとは…ずっと探していたのに、\nなぜ見つけられなかったのでしょう…",
  ui_story_5053_50530201_113_dialog_content = "本当に良かった…\n12年ぶりにようやくまた姉さんと話ができます…",
  ui_story_5053_50530201_114_dialog_content = "（「シード」と2つの人格…ミヤの状況とよく似てる）",
  ui_story_5053_50530201_115_dialog_content = "（ミヤの中の2つの人格は何でも話せる、互いに助け合う友だちだけど、\nヨシュア夫人の場合は道を異にする、争い合う存在だ）",
  ui_story_5053_50530201_116_dialog_content = "（同じ「シード」の影響でも、\n人によって大きな差があるんだね）",
  ui_story_5053_50530201_117_dialog_content = "ところで、さきほど「12年前」と言っていたわね。",
  ui_story_5053_50530201_118_dialog_content = "まさかわたくし12年間もここにいたの？",
  ui_story_5053_50530201_119_dialog_content = "左様だ。",
  ui_story_5053_50530201_120_dialog_content = "どうりで姿形が変わったわけね、ダニエル。",
  ui_story_5053_50530201_121_dialog_content = "みなさんが名前を呼ばなかったら、\nわたくしでさえあなただとは分からなかったわ。",
  ui_story_5053_50530201_122_dialog_content = "その目と顔はどうしたの？なぜ、そんな風に…？",
  ui_story_5053_50530201_123_dialog_content = "長い間戦争と不安定な情勢にさらされてきた。\nどの傷がいつのものだったか、とうに忘れてしまった。",
  ui_story_5053_50530201_124_dialog_content = "だが、お主が余のもとを離れて行ったあの日のこと、そして\nその胸に刺さった短剣の冷やかな感触を忘れたことはない…",
  ui_story_5053_50530201_125_dialog_content = "ダニエル…",
  ui_story_5053_50530201_126_dialog_content = "ということは、ヨシュア夫人の身体は、\nもう埋葬されているんですよね…？",
  ui_story_5053_50530201_127_dialog_content = "そうすると夫人、もしくは「黒の天使」が\n「記憶の鏡晶」の中から出ることは可能なんでしょうか？",
  ui_story_5053_50530201_128_dialog_content = "可能です。",
  ui_story_5053_50530201_129_dialog_content = "姉さんの身体は<color=#FFB400>埋葬されていない</color>のですから。",
  ui_story_5053_50530201_130_dialog_content = "それはどういう意味だ？",
  ui_story_5053_50530201_131_dialog_content = "フンッ…僕が駆け付けた時、\n姉さんは死んでなどいなかったのですよ。",
  ui_story_5053_50530201_132_dialog_content = "僕が少し小細工をし、\n姉さんの身体をひそかに連れ帰って治療を続けていたのです。",
  ui_story_5053_50530201_133_dialog_content = "なんですって…でも、当時白夜城中の人々がお母様のお葬式を見守ったと聞きました。\n叔父様はいったいどうやって…",
  ui_story_5053_50530201_134_dialog_content = "ヨシュアの葬式は余が取り仕切った。\nさような真似を働く隙などなかったはずだ。",
  ui_story_5053_50530201_135_dialog_content = "埋葬後、墓を掘り出しでもせぬ限りな。",
  ui_story_5053_50530201_136_dialog_content = "まあ…わたくしのかわいい天才君ったら、\nいったい何をしたのか教えてちょうだい。",
  ui_story_5053_50530201_137_dialog_content = "姉さんが知りたいというのなら…その通りです。\n葬式の後、僕が姉さんの墓を掘り起こしました。",
  ui_story_5053_50530201_138_dialog_content = "離れた所から墓室に通じる地下通路を掘ったので、\n誰にも知られず姉さんを連れ出し、疑われることもありませんでした。",
  ui_story_5053_50530201_139_dialog_content = "自分で掘ったんですか…？お上品なインテリに見えるのに、\nそんな力仕事までやるんですね！",
  ui_story_5053_50530201_140_dialog_content = "フッ、姉さんのためならこれしきのこと何でもありません。",
  ui_story_5053_50530201_141_dialog_content = "でも、叔父様はどうやってお医者様と納棺師の目をごまかしたんですか？\nまさか買収したのですか…？",
  ui_story_5053_50530201_142_dialog_content = "いいえ、薬を使っただけです。",
  ui_story_5053_50530201_143_dialog_content = "フフ…僕も当時は驚きましたよ。\nアップタウンの医者がこれしきの「小細工」を見破れないとは。",
  ui_story_5053_50530201_144_dialog_content = "どうりで姉さんを治せないわけです。",
  ui_story_5053_50530201_145_dialog_content = "カレブ、お主が黎明学院で教師に盾突いていた時でさえ、\nこれ程傲慢かつ大胆ではなかったはずだ。",
  ui_story_5053_50530201_146_dialog_content = "お主は「黎明学院100年に1人の天才」とまで称された者だ。\nその知恵は正しく使うべきであろう。",
  ui_story_5053_50530201_147_dialog_content = "はぁ…カレブ…なぜそんな勝手な真似を…",
  ui_story_5053_50530201_148_dialog_content = "姉さんがソルラドと子どもたちのそばを離れようとしなかったからです。\nソルラドと一緒にいても辛くなるばかりだというのに…",
  ui_story_5053_50530201_149_dialog_content = "僕はただ姉さんを守りたかっただけです。",
  ui_story_5053_50530201_150_dialog_content = "はぁ…ごめんなさい。わたくしが余計な心配をかけたせいね。",
  ui_story_5053_50530201_151_dialog_content = "お主が甘やかし続けるから、\nこやつはいつまで経っても子どものままなのだ。",
  ui_story_5053_50530201_152_dialog_content = "カレブ、君主を欺いた罪はここを出てから改めて問うとする。",
  ui_story_5053_50530201_153_dialog_content = "…つまり、「黒の天使」を倒してここを離れれば、\nお母様は生き返るんですか？",
  ui_story_5053_50530201_154_dialog_content = "今分かっている状況で判断すれば…\nそれで間違いありません。",
  ui_story_5053_50530201_155_dialog_content = "ならば、ヨシュアの肉体の状態はどうなのだ？\nこの突然の目覚めに耐えうるのか？",
  ui_story_5053_50530201_156_dialog_content = "もちろん、傷一つありません。\n姉さんが昏睡状態に陥ってから、僕がすべての時間と力を注いで治療してきたのですから。",
  ui_story_5053_50530201_157_dialog_content = "その成果は、<color=#FFB400>僕を見ればお分かりになりますよ</color>。",
  ui_story_5053_50530201_158_dialog_content = "見れば分かる？何を見ろって言うんです？",
  ui_story_5053_50530201_159_dialog_content = "…カレブ、たとえヨシュアのためと言えど、\n倫理に背く実験をすることは余が許さぬぞ。",
  ui_story_5053_50530201_160_dialog_content = "フンッ、あなたには関係のないことです。",
  ui_story_5053_50530201_161_dialog_content = "待ってください…何がなんだかよく分からないんですけど！？\nどういうことです？",
  ui_story_5053_50530201_162_dialog_content = "ジャキーニさん、僕は今年いくつだと思いますか？",
  ui_story_5053_50530201_163_dialog_content = "20歳ちょっとですか？",
  ui_story_5053_50530201_164_dialog_content = "ハハッ、そういうことです。",
  ui_story_5053_50530201_165_dialog_content = "あの…私の覚え違いでなければ、\n叔父様は確かもうすぐ40歳のはず…",
  ui_story_5053_50530201_166_dialog_content = "ええっ――！？",
  ui_story_5053_50530201_167_dialog_content = "ええっ――！？",
  ui_story_5053_50530201_168_dialog_content = "てっきり生まれつきお若く見えるのかと思ってました。\nもしくは服で若く見せるのが上手なのかと…まさか実験の成果だったなんて…",
  ui_story_5053_50530201_169_dialog_content = "僕が検証されていない薬を姉さんに使うと思いますか？",
  ui_story_5053_50530201_170_dialog_content = "あの貴族どものように一般人を犠牲にするつもりもありませんし、\n当然自分の身体で実験したに決まっているでしょう。",
  ui_story_5053_50530201_171_dialog_content = "なんてことを…カレブ、あなたって子は…",
  ui_story_5053_50530201_172_dialog_content = "お、お母様、大丈夫？顔色が良くないわ…",
  ui_story_5053_50530201_173_dialog_content = "大丈夫よ…もう慣れているから。この子はいつだって…",
  ui_story_5053_50530201_174_dialog_content = "<size=30>それにしてもPlayerName、カレブさんって幼稚すぎません？\nまさか、その薬って精神年齢の成長まで止めちゃうんですかね？</size>",
  ui_story_5053_50530201_175_dialog_content = "ジャキーニさん！聞こえていますよ！",
  ui_story_5053_50530201_176_dialog_content = "…ただ、姉さんは肉体に問題はないのですが、\n体内の光力がよく暴走してしまうのです。",
  ui_story_5053_50530201_177_dialog_content = "その方面の研究はまだ十分でなく、\n解決方法を見つけられないままなのです。",
  ui_story_5053_50530201_178_dialog_content = "光力？あ…以前私にヨシュア夫人の光力はどこだって聞いたのは、\n治療のためだったんですか？",
  ui_story_5053_50530201_179_dialog_content = "そうですよ。姉さんが注いだ光力の残りを見つけて、\n治療の実験に使おうと思っていたのです。",
  ui_story_5053_50530201_180_dialog_content = "ですが誰が想像できたでしょう。本人がずっと「記憶の鏡晶」の中にいたとは…\n体内の光力が暴走する理由が分かった気がします。",
  ui_story_5053_50530201_181_dialog_content = "つまり、僕の仮説はすべて間違っていたということです…",
  ui_story_5053_50530201_182_dialog_content = "カレブ、その事実はもっと早くに余に告げるべきだった。",
  ui_story_5053_50530201_183_dialog_content = "あなたにですか？これからも姉さんを苦しませるために？",
  ui_story_5053_50530201_184_dialog_content = "まったく…なぜ落ち着いて話せないのかしら？\nみなさんの前でケンカはしないで。",
  ui_story_5053_50530201_185_dialog_content = "すみません、姉さん。",
  ui_story_5053_50530201_186_dialog_content = "ヨシュアの肉体に問題がないのならば、\n急ぎ共に連れ帰るとしよう。",
  ui_story_5053_50530201_187_dialog_content = "本題に戻るぞ。\n「黒の天使」を倒す手立てを考えねばならぬ。",
  ui_story_5053_50530201_188_dialog_content = "ええ。わたくしと「黒の天使」のことを話し合いましょう。",
  ui_story_5053_50530201_189_dialog_content = "わたくしに「黒の天使」を倒すことはできないわ。",
  ui_story_5053_50530201_190_dialog_content = "わたくしたちは<color=#FFB400>1つの肉体を共有し、生死を共にしているの</color>。\n第三者にしか「黒の天使」は倒せないわ。",
  ui_story_5053_50530201_191_dialog_content = "ただ、あなたたちも十分気を付けて。\n「黒の天使」は獲物を探しているの。",
  ui_story_5053_50530201_192_dialog_content = "獲物？",
  ui_story_5053_50530201_193_dialog_content = "ええ、「黒の天使」はわたくしとの間の争いに嫌気がさし、\nわたくしから離れて、独立した存在として身体を支配したがっているの。",
  ui_story_5053_50530201_194_dialog_content = "現実世界では、難しいことだけど――",
  ui_story_5053_50530201_195_dialog_content = "「黒の天使」は「記憶の鏡晶」を起動した者の一部だから、\nこの中では<color=#FFB400>生きた光霊を殺して光力を得ることで、完全体になれる</color>のよ。",
  ui_story_5053_50530201_196_dialog_content = "ジャキーニ、今のは真か？",
  ui_story_5053_50530201_197_dialog_content = "う～ん…信じられないような話ではありますけど、\n「記憶の鏡晶」の中ではあり得ないことじゃないですね。",
  ui_story_5053_50530201_198_dialog_content = "「記憶の鏡晶」は記憶を再生するだけの装置ですが、\nその原理はとても奥深いんです。",
  ui_story_5053_50530201_199_dialog_content = "だからママも女王陛下の命で1つ作ったっきり、\n関係する資料を全部隠しちゃったんですよ…",
  ui_story_5053_50530201_200_dialog_content = "今の状況を整理すると、起こり得る結末は2つですね。",
  ui_story_5053_50530201_201_dialog_content = "1つは僕たちが見事「黒の天使」を倒し、\nヨシュア夫人を連れてここを離れる――",
  ui_story_5053_50530201_202_dialog_content = "そうでなければ、僕らが「黒の天使」に殺されて、\n現実世界で怪物が復活してしまうってことですね？",
  ui_story_5053_50530201_203_dialog_content = "その通りよ、あなた賢いわね。\n確かPlayerNameといったかしら？",
  ui_story_5053_50530201_204_dialog_content = "はい…それはそうと…夫人は僕とジャキーニのことを知ってますし、\n「ミヤ」って名前にも驚いてませんね。",
  ui_story_5053_50530201_205_dialog_content = "まさか、夫人にも時間をリセットする前の記憶があるんですか？",
  ui_story_5053_50530201_206_dialog_content = "ええ。時間が逆流した時、\n<color=#FFB400>わたくしも一緒にいたの</color>。",
  ui_story_5053_50530201_207_dialog_content = "わたくしはもう二度と…家族と離れたくないの。",
  ui_story_5053_50530201_208_dialog_content = "僕が必ず「黒の天使」を倒して姉さんを連れ出してみせます。\nだから、もう悲しまないでください。",
  ui_story_5053_50530201_209_dialog_content = "私も…私も必ずお母様を救い出すわ！",
  ui_story_5053_50530201_210_dialog_content = "ええ、信じているわ。",
  ui_story_5053_50530201_211_dialog_content = "「黒の天使」は理性のない怪物だけど、とても狡猾なの。",
  ui_story_5053_50530201_212_dialog_content = "彼女が自分から姿を現すように、おとりが必要だわ。",
  ui_story_5053_50530201_213_dialog_content = "ダニエル、あなたに頼めるかしら？",
  ui_story_5053_50530201_214_dialog_content = "むろんだ。重要かつ危険な役割だ。\n余を置いて他に適任はおらぬだろう。",
  ui_story_5053_50530201_215_dialog_content = "だが、いかにして誘い出す？",
  ui_story_5053_50530201_216_dialog_content = "何もしなくていいわ。だってあの怪物は…\n<color=#FFB400>あなたを嫌っているようだから</color>。",
  ui_story_5053_50530201_217_dialog_content = "さっきもあなたが撃退しなければ、\nきっと黒の天使にその場で引き裂かれていたわ。",
  ui_story_5053_50530201_218_dialog_content = "それはこの世界の若い頃のあなたに対しても同じよ。\n「黒の天使」は祝典中のあなたを攻撃する可能性もあるわ。",
  ui_story_5053_50530201_219_dialog_content = "もう1人のあなたを殺しても無駄だと分かっていても、\nそうせずにはいられないのよ。",
  ui_story_5053_50530201_220_dialog_content = "…分かった。ならば、若き頃の余を探し、\nその傍らで「黒の天使」が現れるのを待つとしよう。",
  ui_story_5053_50530201_221_dialog_content = "待ってください。お父様、それでは危険すぎます…\n万が一おケガされたらどうするんですか？",
  ui_story_5053_50530201_222_dialog_content = "ロニーは本当に家族思いな子ね。",
  ui_story_5053_50530201_223_dialog_content = "でも、今は緊急事態よ。\n大局を視野に動かなければならないわ。",
  ui_story_5053_50530201_224_dialog_content = "お父様を信じるのよ。いい？",
  ui_story_5053_50530201_225_dialog_content = "うん…",
  ui_story_5053_50530201_226_dialog_content = "パレードが終わった後は、\n確か広場で開幕式でしたよね。",
  ui_story_5053_50530201_227_dialog_content = "広場の近くで待ち伏せしません？",
  ui_story_5053_50530201_228_dialog_content = "いい案だわ。\nでもジャキーニさんにはわたくしと一緒に残ってほしいの。",
  ui_story_5053_50530201_229_dialog_content = "え？なんでですか？見くびっちゃいけませんよ。\n私、PlayerNameよりはずっと強いんですから！",
  ui_story_5053_50530201_230_dialog_content = "ゴホッゴホッ…",
  ui_story_5053_50530201_231_dialog_content = "ええ、知っているわ。\nでも、あなたには「記憶の鏡晶」を操作してもらわないと。",
  ui_story_5053_50530201_232_dialog_content = "他のみなさんに何かあっても、\n時間を戻してまた元の状態に戻せばすむでしょう？",
  ui_story_5053_50530201_233_dialog_content = "あなたに何かあったら、\n取り返しのつかないことになるわ…",
  ui_story_5053_50530201_234_dialog_content = "た、確かにその通りです…",
  ui_story_5053_50530201_235_dialog_content = "では、僕、ミヤ、PlayerNameとおとりである殿下の4人で広場に向かい、\n「黒の天使」を倒すとしましょう。",
  ui_story_5053_50530201_236_dialog_content = "ジャキーニさんと戦闘能力を失った姉さんはここで、\nよい知らせを待っていてください。",
  ui_story_5053_50530201_237_dialog_content = "…ジャキーニさん、姉さんをお願いしますよ。",
  ui_story_5053_50530201_238_dialog_content = "大丈夫ですって！\nなんでそろいもそろって私の実力を疑うんです…？",
  ui_story_5053_50530201_239_dialog_content = "カレブ、珍しいではないか。\nお主は何としてもヨシュアのそばに残るものと思ったが。",
  ui_story_5053_50530201_240_dialog_content = "今は「黒の天使」を倒し、姉さんを一刻も早く連れ出すことこそ最優先事項でしょう？\nそのくらいのこと僕が理解できないとでも？",
  ui_story_5053_50530201_241_dialog_content = "あ、あの…時間もないことですし、急ぎませんか？",
  ui_story_5053_50530201_242_dialog_content = "そうだよ、急ごう！",
  ui_story_5053_50530201_243_dialog_content = "2人とも押さないでください！",
  ui_story_5053_50530201_244_dialog_content = "いってらっしゃ～い！どうかお気をつけて！",
  ui_story_5053_50530201_245_dialog_content = "ヨシュア、今度こそお主を手放したりせぬ。\n約束する。",
  ui_story_5053_50530201_246_dialog_content = "ええ。信じているわ。",
  ui_story_5053_50530201_247_dialog_content = "必ずそうしてくれるって。",
  ui_story_5053_50530301_1_dialog_content = "パレードも終わったな。そろそろ祝典が始まるぞ。",
  ui_story_5053_50530301_2_dialog_content = "今から行って、いい場所取れるかな？",
  ui_story_5053_50530301_3_dialog_content = "さあ、急ごう！",
  ui_story_5053_50530301_4_dialog_content = "形式ばかりをてらった祝典など観て、何が面白いのでしょうか。",
  ui_story_5053_50530301_5_dialog_content = "どこもかしこも人ばかりで、見通しが悪いですね。\nこの状況でどうやって「黒の天使」を見つけるのです？",
  ui_story_5053_50530301_6_dialog_content = "壇上に近づき、待ち伏せするのだ。",
  ui_story_5053_50530301_7_dialog_content = "あなたもこの世界のあなたも「黒の天使」に狙われているのでしょう？\nでしたら、お二人並んで壇上に立った方が効率がよいのでは？",
  ui_story_5053_50530301_8_dialog_content = "あの…私が壇上に立ちます。\nこの世界の人たちも私のことは知っているので…",
  ui_story_5053_50530301_9_dialog_content = "お父様が行ったら、また不必要な騒ぎを起こしてしまいます…",
  ui_story_5053_50530301_10_dialog_content = "一理あるね。でも、万が一「黒の天使」が壇上のソルラドさんを襲ったら、\nミヤ一人で止められるの？",
  ui_story_5053_50530301_11_dialog_content = "私は…一人じゃないわ。",
  ui_story_5053_50530301_12_dialog_content = "この世界の「お父様」がきっと守ってくれる。",
  ui_story_5053_50530301_13_dialog_content = "それに壇上にいる方が会場を見渡せるでしょう？\n「黒の天使」を見つけたら、すぐに居場所を知らせられる…",
  ui_story_5053_50530301_14_dialog_content = "だから…その時は私がみんなから見える場所に立って、\n怪物の方向を知らせるわ！",
  ui_story_5053_50530301_15_dialog_content = "あ…ご、ごめんなさい、お父様…\n私の考え、甘かったでしょうか？",
  ui_story_5053_50530301_16_dialog_content = "いや、よく考えておる。お前の言う通りにしよう。",
  ui_story_5053_50530301_17_dialog_content = "え？本当ですか…？",
  ui_story_5053_50530301_18_dialog_content = "ありがとうございます、お父様。\nで、では…行ってまいります。私の知らせを待っててくださいね！",
  ui_story_5053_50530301_19_dialog_content = "たった1日でミヤがこんな勇敢に…\n自分の意見を主張できるようになるなんて…本当に良かった。",
  ui_story_5053_50530301_20_dialog_content = "PlayerName、感傷に浸っている時間はありませんよ。\n姉さんをひどい目に合わせた悪魔を何としても倒さなければ！",
  ui_story_5053_50530301_21_dialog_content = "あ、はい…今行きます！",
  ui_story_5053_50530301_22_dialog_content = "カレン、式典がもうじき始まる。\n急いで席に着きなさい。",
  ui_story_5053_50530301_23_dialog_content = "はい、お父様。",
  ui_story_5053_50530301_24_dialog_content = "…お父様、カレン。",
  ui_story_5053_50530301_25_dialog_content = "お姉様！？ヴェロニカお姉様だわ！",
  ui_story_5053_50530301_26_dialog_content = "ヴェロニカか？何ゆえお前がここに？",
  ui_story_5053_50530301_27_dialog_content = "お、お母様から記念日の式典に出るよう言われたんです。",
  ui_story_5053_50530301_28_dialog_content = "では、母上には会ったのか？",
  ui_story_5053_50530301_29_dialog_content = "はい…具合が悪いけれど、心配しないでと言われました。",
  ui_story_5053_50530301_30_dialog_content = "おや？これはこれは、ヴェロニカ殿下ではありませんか。\nご無沙汰ですね。お変わりありませんか？",
  ui_story_5053_50530301_31_dialog_content = "ヴェロニカ殿下は騎士団に入り、\n団と共に影ノ街へ向かわれたと聞いておったのですがな？",
  ui_story_5053_50530301_32_dialog_content = "…祝典に参加したかったので、一時休暇を取ってきました。",
  ui_story_5053_50530301_33_dialog_content = "さようでしたか。「ソルラド家」の記念日ですからの。\n確かに殿下も参加すべきですな。",
  ui_story_5053_50530301_34_dialog_content = "残念なことにわしの一族は今も影ノ街に駐屯したまま…\n殿下のような幸福にはあずかれませぬ、ハハハ。",
  ui_story_5053_50530301_35_dialog_content = "ヴェロニカお姉様はソルラド家の人間よ。\n記念日の祝典に参加するために戻って来て何が悪いの！",
  ui_story_5053_50530301_36_dialog_content = "カレン、下がりなさい。\nハメス公爵に無礼な物言いをしてはならん。",
  ui_story_5053_50530301_37_dialog_content = "お父様、カレンを責めないであげてください。\n私が突然現れたのがいけないんです。",
  ui_story_5053_50530301_38_dialog_content = "そういえば、ハメス公爵にお聞きしたいことがあったんです。\n夫人はお元気ですか？",
  ui_story_5053_50530301_39_dialog_content = "わしの家内ですかな？元気にしておりますぞ。",
  ui_story_5053_50530301_40_dialog_content = "公爵のお孫さんはいつも公爵夫人が危篤だと言って、\n休暇をとっていたので、心配していたんです。",
  ui_story_5053_50530301_41_dialog_content = "お元気なら…安心しました。",
  ui_story_5053_50530301_42_dialog_content = "…さようですか。お気遣いに感謝しますぞ。",
  ui_story_5053_50530301_43_dialog_content = "ハメス公爵も時には家族を気遣う時間を\nとったほうがよさそうだな。",
  ui_story_5053_50530301_44_dialog_content = "ヴェロニカ殿下は数日お見かけしないうちにずいぶん大きくなられましたな。\nきっと騎士団で様々なご経験をなさったのでしょう。",
  ui_story_5053_50530301_45_dialog_content = "そうかもしれんな。\n高慢にならぬよう望むばかりだ。",
  ui_story_5053_50530301_46_dialog_content = "何を言うのです、娘にそう厳しくするものではありませんよ。",
  ui_story_5053_50530301_47_dialog_content = "ありがとうございます、トロイ公爵。\nでも、父の言う通りです。これからも謙虚に学んでいきたいと思います。",
  ui_story_5053_50530301_48_dialog_content = "ほう、そうですか…\n騎士団の仕事は殿下を大きく成長させたようですね。",
  ui_story_5053_50530301_49_dialog_content = "祝典がまもなく始まる。\n皆、席に着かれよ。",
  ui_story_5053_50530301_50_dialog_content = "お姉様、さっきはとてもカッコよかったわ！\n元老院のおじ様たち相手にまったくひるまないんだもの！",
  ui_story_5053_50530301_51_dialog_content = "ふふ、そう？本当はちょっと怖かったんだけど…",
  ui_story_5053_50530301_52_dialog_content = "カレンもとっても勇敢よ。\nたった一人でお父様とパレードに出るなんて。",
  ui_story_5053_50530301_53_dialog_content = "いいえ…カレン、本当はお母様のところを離れたくなかったの…",
  ui_story_5053_50530301_54_dialog_content = "でも、馬車に乗る時お父様からお母様は具合が悪いから、\nカレン一人で祝典に参加するように言われて…",
  ui_story_5053_50530301_55_dialog_content = "（そうだったのね。お母様は私たちと会うために、\n具合が悪いと口実をつくって、カレンとお父様を宮殿から引き離したんだわ）",
  ui_story_5053_50530301_56_dialog_content = "（カレンには辛い思いをさせてしまったけど、\nここの世界の出来事は現実ではないし、重要でもないわ）",
  ui_story_5053_50530301_57_dialog_content = "（やはり大局を考えて、小さい事には目をつぶらないと…\nでも…やっぱり…私にはできない！）",
  ui_story_5053_50530301_58_dialog_content = "カレン、一緒に戻ったらお母様と遊びましょうか？",
  ui_story_5053_50530301_59_dialog_content = "いいの？お母様の具合は大丈夫かしら？",
  ui_story_5053_50530301_60_dialog_content = "大丈夫よ。お母様はカレンのことが大好きなのよ。\nカレンがそばにいてくれたら、元気になるわ。",
  ui_story_5053_50530301_61_dialog_content = "カレンもお母様とお姉様のこと大好き！\nお父様のことも好き！",
  ui_story_5053_50530301_62_dialog_content = "帰ったら、お母様にフルーツをプレゼントして、\nパレードのことをお話しするわ！",
  ui_story_5053_50530301_63_dialog_content = "ふふ、カレンはいい子ね。",
  ui_story_5053_50530301_64_dialog_content = "（よかった。カレンが元気になったわ）",
  ui_story_5053_50530301_65_dialog_content = "何か見えましたか？",
  ui_story_5053_50530301_66_dialog_content = "ミヤが壇上に向かって行ったけど、姿は見えないんだ…\nただ…若い頃のソルラドさんが挨拶を始めるみたいだよ。",
  ui_story_5053_50530301_67_dialog_content = "今のところ「黒の天使」の姿は見えない。",
  ui_story_5053_50530301_68_dialog_content = "ここは見通しが悪すぎます。場所を変えませんか？",
  ui_story_5053_50530301_69_dialog_content = "<color=#e8d9bb>ビリッ！パリン！</color>",
  ui_story_5053_50530301_70_dialog_content = "今の音は…",
  ui_story_5053_50530301_71_dialog_content = "カレブさん、場所を変える必要はなさそうだよ。",
  ui_story_5053_50530301_72_dialog_content = "2人とも、避けるのだ！",
  ui_story_5053_50530301_73_dialog_content = "ここに…いたのね！",
  ui_story_5053_50530302_1_dialog_content = "「ソルラド家記念日」の式典開催を宣言する！",
  ui_story_5053_50530302_2_dialog_content = "続いて「決闘の儀式」を行う。",
  ui_story_5053_50530302_3_dialog_content = "（どうしてまだ現れないの…？）",
  ui_story_5053_50530302_4_dialog_content = "（PlayerNameたちはあの辺りにいるはずだけど…\n姿が見えないわ…）",
  ui_story_5053_50530302_5_dialog_content = "（まさか…「黒の天使」はPlayerNameたちの方を襲撃したの？）",
  ui_story_5053_50530302_6_dialog_content = "（どうしたらいいの？何か口実を作って壇から下りる？）",
  ui_story_5053_50530302_7_dialog_content = "お姉様、何を探しているの？",
  ui_story_5053_50530302_8_dialog_content = "な、何でもないわ…カレン、あっちで決闘の儀式が始まってるわ。\nなかなかいい勝負のようね。",
  ui_story_5053_50530302_9_dialog_content = "カレンはいつになったら儀式に参加できるの…？\nカレンだって皆と同じくらい剣術上手なのに。",
  ui_story_5053_50530302_10_dialog_content = "あれ？おかしいわ。\n決闘してた衛兵2人が急に戦うのをやめたわ。",
  ui_story_5053_50530302_11_dialog_content = "しかもこっちへ向かってくる…",
  ui_story_5053_50530302_12_dialog_content = "何か特別な演目なのかしら？",
  ui_story_5053_50530302_13_dialog_content = "む？",
  ui_story_5053_50530302_14_dialog_content = "（お父様もけげんなご様子…\nということは、何もご存じないのね）",
  ui_story_5053_50530302_15_dialog_content = "（当時私はこの場にいなかったから、\n何があったのか分からないけど…明らかに何かおかしいわ）",
  ui_story_5053_50530302_16_dialog_content = "…",
  ui_story_5053_50530302_17_dialog_content = "（まさか…！？）",
  ui_story_5053_50530302_18_dialog_content = "…大変です、お父様！暗殺計画が早まったようです！",
  ui_story_5053_50530302_19_dialog_content = "お前がなぜ暗殺計画を知っておるのだ？\nしかも…「早まった」と？",
  ui_story_5053_50530302_20_dialog_content = "それは…お話しすると長くなるんですが…",
  ui_story_5053_50530302_21_dialog_content = "お主ら、壇上などにきおって、いかなる所存か！？\nここはお主らの来る所でない！",
  ui_story_5053_50530302_22_dialog_content = "…",
  ui_story_5053_50530302_23_dialog_content = "無礼者めが！公爵たるわしの問いに答えぬか！",
  ui_story_5053_50530302_24_dialog_content = "これはいかん…ハメス公爵、下がれ！",
  ui_story_5053_50530302_25_dialog_content = "ヴェロニカ、カレンを頼むぞ！",
  ui_story_5053_50530302_26_dialog_content = "お父様、あぶない！",
  ui_story_5053_50530302_27_dialog_content = "オラァッ！",
  ui_story_5053_50530302_28_dialog_content = "それしきの腕で余を倒すつもりか？",
  ui_story_5053_50530302_29_dialog_content = "一切を支配する！",
  ui_story_5053_50530302_30_dialog_content = "うっ…",
  ui_story_5053_50530302_31_dialog_content = "いかがした？お主も手合わせしたいのか？",
  ui_story_5053_50530302_32_dialog_content = "オラァッ！",
  ui_story_5053_50530302_33_dialog_content = "ハァッ――！",
  ui_story_5053_50530302_34_dialog_content = "うっ…",
  ui_story_5053_50530302_35_dialog_content = "立ったまま余の剣を受け止めるとは。\n申せ、いったい誰の差し金か！？",
  ui_story_5053_50530302_36_dialog_content = "ま、待っ…",
  ui_story_5053_50530302_37_dialog_content = "今さら助けを求めても遅い！",
  ui_story_5053_50530302_38_dialog_content = "お姉様、お父様はなぜあの悪者とコソコソお話になっているの？",
  ui_story_5053_50530302_39_dialog_content = "おかしい…あれはお父様が相手を脅しているというより、\n相手がお父様の剣をつかんでいる…",
  ui_story_5053_50530302_40_dialog_content = "<color=#e8d9bb>カシャ！</color>",
  ui_story_5053_50530302_41_dialog_content = "む？",
  ui_story_5053_50530302_42_dialog_content = "ハッ…アハハハ！すぐだ…もうすぐ…",
  ui_story_5053_50530302_43_dialog_content = "あの人の顔、どうしてあんなに歪んでるの…？",
  ui_story_5053_50530302_44_dialog_content = "ケガをしたのに、なぜ笑っているの？変な人…",
  ui_story_5053_50530302_45_dialog_content = "お主…なぜこれほどの力が？\n<color=#FFB400>剣がまったく抜けぬではないか</color>！",
  ui_story_5053_50530302_46_dialog_content = "ならば、一切を…",
  ui_story_5053_50530302_47_dialog_content = "来たぞ…",
  ui_story_5053_50530302_48_dialog_content = "お父様！空を見てください！",
  ui_story_5053_50530302_49_dialog_content = "<size=45><color=#e8d9bb>グオオ――！</color></size>",
  ui_story_5053_50530302_50_dialog_content = "なに？",
  ui_story_5053_50530302_51_dialog_content = "す、すごい風！カレン、飛ばされそう！",
  ui_story_5053_50530302_52_dialog_content = "カレン、私のところへ！",
  ui_story_5053_50530302_53_dialog_content = "龍…<color=#FFB400>ドラゴン</color>か？\nカルティマめ…壇ごと我らを葬る気か？",
  ui_story_5053_50530302_54_dialog_content = "<size=45><color=#e8d9bb>グオオ――！</color></size>",
  ui_story_5053_50530302_55_dialog_content = "カレン、ヴェロニカ！",
  ui_story_5053_50530302_56_dialog_content = "早く逃げよ！！",
  ui_story_5053_50530302_57_dialog_content = "<size=45><color=#e8d9bb>ドーン――！！</color></size>",
  ui_story_5053_50530401_1_dialog_content = "はぁ――！！",
  ui_story_5053_50530401_2_dialog_content = "フッ、大したことありませんね！",
  ui_story_5053_50530401_3_dialog_content = "たかが「シード」で生まれた怪物の分際で、\n姉さんの声を真似ようとは…",
  ui_story_5053_50530401_4_dialog_content = "姉さんの味わった苦しみをそのままお返ししましょう！",
  ui_story_5053_50530401_5_dialog_content = "はぁっ――！！",
  ui_story_5053_50530401_6_dialog_content = "…",
  ui_story_5053_50530401_7_dialog_content = "カレブ！むやみに追ってはならん！",
  ui_story_5053_50530401_8_dialog_content = "くたばれ！",
  ui_story_5053_50530401_9_dialog_content = "…はぁ！！",
  ui_story_5053_50530401_10_dialog_content = "なに！？",
  ui_story_5053_50530401_11_dialog_content = "カレブさん！！",
  ui_story_5053_50530401_12_dialog_content = "カレ…ブ…？",
  ui_story_5053_50530401_13_dialog_content = "気安く呼ばないでいただきたい…",
  ui_story_5053_50530401_14_dialog_content = "今です！",
  ui_story_5053_50530401_15_dialog_content = "すべての星よ！揺れ動け――！！",
  ui_story_5053_50530401_16_dialog_content = "ああっ…！！",
  ui_story_5053_50530401_17_dialog_content = "ダ…ニエル…",
  ui_story_5053_50530401_18_dialog_content = "ダニ…",
  ui_story_5053_50530401_19_dialog_content = "街の様子が元に戻った…！？",
  ui_story_5053_50530401_20_dialog_content = "消えた…？奴は死んだのですか…？",
  ui_story_5053_50530401_21_dialog_content = "おかしい、あれを見よ。",
  ui_story_5053_50530401_22_dialog_content = "うわ――！",
  ui_story_5053_50530401_23_dialog_content = "逃げろ！！",
  ui_story_5053_50530401_24_dialog_content = "広場にいた群衆があちこち逃げ回っているということは…\n反乱が始まったのですか？",
  ui_story_5053_50530401_25_dialog_content = "でも、ヘンです…僕たちの干渉がなければ、\n反乱は暗殺の後に…",
  ui_story_5053_50530401_26_dialog_content = "いや、これは…",
  ui_story_5053_50530401_27_dialog_content = "上を見よ！",
  ui_story_5053_50530401_28_dialog_content = "グォォ――！",
  ui_story_5053_50530401_29_dialog_content = "カルティマ家のドラゴン！？",
  ui_story_5053_50530401_30_dialog_content = "ドラゴンがどうして城内に？",
  ui_story_5053_50530401_31_dialog_content = "まあ、なんていうことなの！？\n白夜城内にどうしてあのようなものが…",
  ui_story_5053_50530401_32_dialog_content = "このような時こそ私たちを守るのが衛兵の務めではなくって？\n何をぼうっとしているの！？",
  ui_story_5053_50530401_33_dialog_content = "…",
  ui_story_5053_50530401_34_dialog_content = "ちょっと…あ、あなたたち…何をするつもり？",
  ui_story_5053_50530401_35_dialog_content = "殺せ…殺せ…殺せ…",
  ui_story_5053_50530401_36_dialog_content = "あ――",
  ui_story_5053_50530401_37_dialog_content = "支配者の刃！",
  ui_story_5053_50530401_38_dialog_content = "武器も持たぬ民衆を襲うとは、騎士の名に恥じる！\nカルティマはそこまで堕ちたか！？",
  ui_story_5053_50530401_39_dialog_content = "…うう…",
  ui_story_5053_50530401_40_dialog_content = "こ、この人まだ生きてます！",
  ui_story_5053_50530401_41_dialog_content = "殺せ…",
  ui_story_5053_50530401_42_dialog_content = "殺せ…？今何か言いましたか？",
  ui_story_5053_50530401_43_dialog_content = "ソ…ルラド…",
  ui_story_5053_50530401_44_dialog_content = "殺せ…殺せ…侵入者を殺せ！",
  ui_story_5053_50530401_45_dialog_content = "PlayerName、下がれ！",
  ui_story_5053_50530401_46_dialog_content = "ど、どうして…？この人、どうしたの…？",
  ui_story_5053_50530401_47_dialog_content = "<color=#e8d9bb><size=45>ドーン――！！</size></color>",
  ui_story_5053_50530401_48_dialog_content = "す、すごい衝撃です。今度はいったい何が？",
  ui_story_5053_50530401_49_dialog_content = "壇のある方向で爆発が起きました！",
  ui_story_5053_50530401_50_dialog_content = "城主様が襲われた！",
  ui_story_5053_50530401_51_dialog_content = "急げ、逃げろ！！",
  ui_story_5053_50530401_52_dialog_content = "襲われただと？…ミヤ！",
  ui_story_5053_50530401_53_dialog_content = "ミヤがまだ壇上にいたとしたら…そ、そんな、まさか…",
  ui_story_5053_50530401_54_dialog_content = "姉さんはまだ宮殿内にいます。\n反乱軍が押しかければ、姉さんは…",
  ui_story_5053_50530401_55_dialog_content = "PlayerName、お主はカレブと共に戻れ！",
  ui_story_5053_50530401_56_dialog_content = "もし余がミヤを連れて戻らぬ時は…\nジャキーニに時間を逆流させよ、迷ってはならん！",
  ui_story_5053_50530401_57_dialog_content = "ソルラドさん！！！",
  ui_story_5053_50530401_58_dialog_content = "（いったいどうなってるの！？\nまさか「記憶の鏡晶」が壊れたの？）",
  ui_story_5053_50530401_59_dialog_content = "（それとも「黒の天使」がまだ生きてて、何かしたってこと…？）",
  ui_story_5053_50530401_60_dialog_content = "ぼうっとしてないでください！\n包囲を突破しますよ！",
  ui_story_5053_50530401_61_dialog_content = "殺せ…殺せ…殺せ…",
  ui_story_5053_50530402_1_dialog_content = "ハァッ！",
  ui_story_5053_50530402_2_dialog_content = "ううっ…",
  ui_story_5053_50530402_3_dialog_content = "なんということだ。猛り狂った反逆者どもめ…\nどなたか知らないが、感謝する。",
  ui_story_5053_50530402_4_dialog_content = "殿下たちはどちらへ？",
  ui_story_5053_50530402_5_dialog_content = "殿下たち？亡き者を気遣うより、\nどうしたら生き延びるかを考えたほうがよいのでは？",
  ui_story_5053_50530402_6_dialog_content = "亡き者だと？どういう意味か！？",
  ui_story_5053_50530402_7_dialog_content = "カレン殿下とヴェロニカ殿下、それから城主様はドラゴンの攻撃を真っ向から受け…\n<color=#FFB400>すでに亡くなった</color>！",
  ui_story_5053_50530402_8_dialog_content = "…どこだ？ヴェロニカ殿下はどこにいる！？",
  ui_story_5053_50530402_9_dialog_content = "壇上だ。どうしたというのだ？\nこのような時に遺体を引き取ろうというのか？",
  ui_story_5053_50530402_10_dialog_content = "感謝する。",
  ui_story_5053_50530402_11_dialog_content = "愚かな…失ったものに後ろ髪を引かれていては、\n自らも命を落とすぞ。",
  ui_story_5053_50530402_12_dialog_content = "姉さん！",
  ui_story_5053_50530402_13_dialog_content = "ヨシュア夫人！ジャキーニ！どこにいるの？",
  ui_story_5053_50530402_14_dialog_content = "なぜ誰も答えないのでしょう…？姉さん！！",
  ui_story_5053_50530402_15_dialog_content = "カレブ、わたくしならここよ。",
  ui_story_5053_50530402_16_dialog_content = "よかった…ご無事だったのですね…\nまた姉さんを失ってしまうのかと思いました…",
  ui_story_5053_50530402_17_dialog_content = "反乱計画が早まったのです。\n今から安全な所へお連れします。",
  ui_story_5053_50530402_18_dialog_content = "ジャキーニさんはどちらに？\nこんな時にあちこち歩き回るとはまったく…",
  ui_story_5053_50530402_19_dialog_content = "カレブ、そう焦らずに、一つ一つ話してちょうだい。",
  ui_story_5053_50530402_20_dialog_content = "汗がすごいわ。襟にシワが寄っているじゃないの。\nいらっしゃい、整えてあげるわ。",
  ui_story_5053_50530402_21_dialog_content = "え？あ、そのようなことは自分で…",
  ui_story_5053_50530402_22_dialog_content = "あ、ありがとう、姉さん。",
  ui_story_5053_50530402_23_dialog_content = "ヨシュア夫人は無事だったんですね。\nところで、ジャキーニはどこですか？",
  ui_story_5053_50530402_24_dialog_content = "ジャキーニ！どこにいるの！？",
  ui_story_5053_50530402_25_dialog_content = "うっ…",
  ui_story_5053_50530402_26_dialog_content = "ね…姉さん？",
  ui_story_5053_50530402_27_dialog_content = "どうしたの、カレブ？",
  ui_story_5053_50530402_28_dialog_content = "そ、そんな…",
  ui_story_5053_50530402_29_dialog_content = "な…なぜです？",
  ui_story_5053_50530402_30_dialog_content = "カレブさん、胸元の傷は…！？",
  ui_story_5053_50530402_31_dialog_content = "来る途中でケガしたの？いや、違う…",
  ui_story_5053_50530402_32_dialog_content = "その歳になってもまだ、床に座り込むのが好きなのね？",
  ui_story_5053_50530402_33_dialog_content = "あなたは幼すぎるわ。",
  ui_story_5053_50530402_34_dialog_content = "がっかりよ。",
  ui_story_5053_50530402_35_dialog_content = "な…なぜです…",
  ui_story_5053_50530402_36_dialog_content = "姉…さん…",
  ui_story_5053_50530402_37_dialog_content = "ミヤ…",
  ui_story_5053_50530402_38_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5053_50530402_39_dialog_content = "時間は戻せる…",
  ui_story_5053_50530402_40_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5053_50530402_41_dialog_content = "だとしても、このような思いだけはさせたくなかった…",
  ui_story_5053_50530402_42_dialog_content = "そばに置いてやれずとも、いかに嫌われようとも、\nお前が無事に生きてさえいてくれれば、それでよかった…",
  ui_story_5053_50530402_43_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5053_50530402_44_dialog_content = "<size=45>グオォォ――！</size>",
  ui_story_5053_50530402_45_dialog_content = "我が家族の命を奪った後は、余を葬るか？",
  ui_story_5053_50530402_46_dialog_content = "余の家族に与えた苦しみを倍にして返してやろうではないか…",
  ui_story_5053_50530402_47_dialog_content = "<size=45>グオオ――！</size>",
  ui_story_5053_50530402_48_dialog_content = "<size=45>あの世へ送ってやる！！</size>",
  ui_story_5053_50530402_49_dialog_content = "<color=#e8d9bb>カツン、カツン…</color>",
  ui_story_5053_50530402_50_dialog_content = "（どういうこと？どういうこと？どうなってるの！？）",
  ui_story_5053_50530402_51_dialog_content = "（ヨシュア夫人がどうしてカレブさんを殺すの？\n実の弟じゃないの！？）",
  ui_story_5053_50530402_52_dialog_content = "<color=#e8d9bb>カツン、カツン…</color>",
  ui_story_5053_50530402_53_dialog_content = "（まさか、この世界の人たち全員おかしくなっちゃったの？）",
  ui_story_5053_50530402_54_dialog_content = "（それともずっと悪夢を見てるの！？）",
  ui_story_5053_50530402_55_dialog_content = "<color=#e8d9bb>カツン、カツン、カツン、カツン…</color>",
  ui_story_5053_50530402_56_dialog_content = "（もう行ったのかな？）",
  ui_story_5053_50530402_57_dialog_content = "（ずっとテーブルの下に隠れてるわけにもいかないし…\nこの後どうすればいいんだろう？）",
  ui_story_5053_50530402_58_dialog_content = "<color=#e8d9bb>カツン、カツン</color>",
  ui_story_5053_50530402_59_dialog_content = "（足音が…止まった？）",
  ui_story_5053_50530402_60_dialog_content = "見つけたわ～。",
  ui_story_5053_50530402_61_dialog_content = "え！？",
  ui_story_5053_50530402_62_dialog_content = "あらあら。かくれんぼなんてカレンだってもう遊ばないわよ。",
  ui_story_5053_50530402_63_dialog_content = "PlayerNameは子どもじゃないでしょ。\nいつまでお遊びを続けるつもり？",
  ui_story_5053_50530402_64_dialog_content = "はぁ…はぁ…",
  ui_story_5053_50530402_65_dialog_content = "逃げても無駄よ。\n逃げれば逃げるほど苦しんで死ぬことになるわ。",
  ui_story_5053_50530402_66_dialog_content = "ミヤ、カレブ…2人とも良質の光力をもっていたのね。\nこんなに力が満ちあふれているのは初めてよ。",
  ui_story_5053_50530402_67_dialog_content = "次は…空の末裔の力を吸収したら、どうなるのかしら？\n他人の心が読めるようになるのかしらね。",
  ui_story_5053_50530402_68_dialog_content = "あなたの思い通りにはさせません！",
  ui_story_5053_50530402_69_dialog_content = "それもそうね。\nこの世界では、私はもともと他人を操ることができるの。",
  ui_story_5053_50530402_70_dialog_content = "とても単純な関係よね。心地いいわ。",
  ui_story_5053_50530402_71_dialog_content = "はぁ…はぁ…",
  ui_story_5053_50530402_72_dialog_content = "（この先には扉が1つしかない。\n行き止まりじゃありませんように！）",
  ui_story_5053_50530402_73_dialog_content = "そこは…ふっ、空の末裔の直感かしら？",
  ui_story_5053_50530402_74_dialog_content = "趣味がいいわ。",
  ui_story_5053_50530402_75_dialog_content = "<color=#e8d9bb>ギィ…</color>",
  ui_story_5053_50530402_76_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5053_50530402_77_dialog_content = "ジャキーニ…！？",
  ui_story_5053_50530402_78_dialog_content = "ジャキーニ…？身体が冷たい…息を…してない…",
  ui_story_5053_50530402_79_dialog_content = "あなたって本当に趣味がいいのね、PlayerName。",
  ui_story_5053_50530402_80_dialog_content = "北境の占い師は「記憶の鏡晶」を操れる。\nもちろん一番に殺したわ。",
  ui_story_5053_50530402_81_dialog_content = "そうでなかったら、わざわざ彼女一人をここに残すと思う？",
  ui_story_5053_50530402_82_dialog_content = "…ヨシュア夫人、僕には分かりません。\nどうしてこんなことを？",
  ui_story_5053_50530402_83_dialog_content = "どうしてジャキーニと実の弟を殺したんですか…？\nそれから僕も。",
  ui_story_5053_50530402_84_dialog_content = "そんなに難しいこと？\nわたくしにはあなたたちの力が必要なの。",
  ui_story_5053_50530402_85_dialog_content = "恨みも何もないわ。\nただ必要だから、犠牲になってもらっただけ。",
  ui_story_5053_50530402_86_dialog_content = "…分かりません。あなたは本当にヨシュア夫人ですか？",
  ui_story_5053_50530402_87_dialog_content = "いったい、何者なんですか？",
  ui_story_5053_50530402_88_dialog_content = "ヨシュアに決まっているでしょう？\n本物のヨシュアよ！",
  ui_story_5053_50530402_89_dialog_content = "さあ、目を見開いてよく見ておくのね！\n死に際に見たわたくしの姿を永遠に覚えておくのよ！",
  ui_story_5053_50530402_90_dialog_content = "<color=#e8d9bb>シュッ――！</color>",
  ui_story_5053_50530402_91_dialog_content = "ん…？",
  ui_story_5053_50530402_92_dialog_content = "PlayerName…早く、早くこっちへ…",
  ui_story_5053_50530402_93_dialog_content = "ジャキーニ！？",
  ui_story_5053_50530402_94_dialog_content = "生きてたんだね。てっきり君はもう…",
  ui_story_5053_50530402_95_dialog_content = "忘れたんですか…？\n私は小さい頃から各地を旅して回ってる占い師ですよ…",
  ui_story_5053_50530402_96_dialog_content = "獣の前で死んだふりするくらい、お茶の子さいさいです！\n…ゲホッゴホゴホッ。",
  ui_story_5053_50530402_97_dialog_content = "ジャキーニ！",
  ui_story_5053_50530402_98_dialog_content = "…他のみなさんは？",
  ui_story_5053_50530402_99_dialog_content = "…",
  ui_story_5053_50530402_100_dialog_content = "まさか、全員…なんてことを…！",
  ui_story_5053_50530402_101_dialog_content = "北境の占術で幻覚を作りだしたのね…\nさすがは「記憶の鏡晶」を作っただけのことあるわ。",
  ui_story_5053_50530402_102_dialog_content = "小賢しくて憎たらしいわね。",
  ui_story_5053_50530402_103_dialog_content = "それはどうも。なにせ私は小さい頃から\n聞き分けのないことが取り柄なんですから！",
  ui_story_5053_50530402_104_dialog_content = "だったら今すぐ、いい子になってもらうわ！！",
  ui_story_5053_50530402_105_dialog_content = "水晶玉よ、守ってください！",
  ui_story_5053_50530402_106_dialog_content = "PlayerName、「記憶の鏡晶」をこっちへ。",
  ui_story_5053_50530402_107_dialog_content = "手を水晶の上に置いてください。\nいいですか、たとえ私が最後まで耐えられなかったとしても…",
  ui_story_5053_50530402_108_dialog_content = "絶対に手を放しちゃいけませんよ！",
  ui_story_5053_50530402_109_dialog_content = "ジャキーニ…分かったよ！",
  ui_story_5053_50530402_110_dialog_content = "リタロ、リタロ、リタロ！",
  ui_story_5053_50530402_111_dialog_content = "時よ、起点へ戻れ…",
  ui_story_5053_50530402_112_dialog_content = "アブラカダブラ…ううっ…！",
  ui_story_5053_50530402_113_dialog_content = "あ…",
  ui_story_5053_50530402_114_dialog_content = "ジャキーニ！ジャキーニ――！！",
  ui_story_5053_50530501_0X_dialog_content = "<color=#e8d9bb>2回目の時間の逆流の後――</color>",
  ui_story_5053_50530501_1_dialog_content = "殿下、すべて準備が整いました。",
  ui_story_5053_50530501_2_dialog_content = "パレードの馬車が外で待機しております。\nいつでもご出発になれます。",
  ui_story_5053_50530501_3_dialog_content = "…",
  ui_story_5053_50530501_4_dialog_content = "奥様のことが気がかりですか？",
  ui_story_5053_50530501_5_dialog_content = "ヨシュアはこれまで健康で、身体の不調を訴えることなど稀だった。\n特に今日のような特別な日はな。",
  ui_story_5053_50530501_6_dialog_content = "ここのところ、奥様は貴族のご夫人方に城主様の政策を広めようと、\nそれは努力していらっしゃいました。",
  ui_story_5053_50530501_7_dialog_content = "ご安心ください。私がしっかりとお世話いたします。",
  ui_story_5053_50530501_8_dialog_content = "う、ううっ…",
  ui_story_5053_50530501_9_dialog_content = "ここは…？",
  ui_story_5053_50530501_10_dialog_content = "ちょっと待って。ここは…まだ昼間？",
  ui_story_5053_50530501_11_dialog_content = "逃げ回ってたら、ジャキーニを見つけて、それから…",
  ui_story_5053_50530501_12_dialog_content = "（ジャキーニ、僕を守ってくれたんだね。ありがとう…）",
  ui_story_5053_50530501_13_dialog_content = "（でも、ジャキーニは近くにいない。まさか最初の時みたいに、\n別々の場所に散らばっちゃったのかな？）",
  ui_story_5053_50530501_14_dialog_content = "（どうして僕たちが襲われたんだろう？\nあのヨシュア夫人は本物じゃなかった？）",
  ui_story_5053_50530501_15_dialog_content = "（ジャキーニが「記憶の鏡晶」で、あのヨシュア夫人は僕たちと同じで、\n<color=#FFB400>幻影じゃない</color>って確かめたのに）",
  ui_story_5053_50530501_16_dialog_content = "わたくしはヨシュア。\n本物のヨシュアよ。",
  ui_story_5053_50530501_17_dialog_content = "（本物だなんてわざわざ強調してたのは、\n何か意味があるのかな？）",
  ui_story_5053_50530501_18_dialog_content = "（全然分からない…でも今一番大事なのは、\nもし本当にヨシュア夫人に何か異常があったのなら、僕たちはどうやって帰ればいいのか…）",
  ui_story_5053_50530501_19_dialog_content = "（うう…いったいどういう状況なんだ？\nどうして僕だけがここに？）",
  ui_story_5053_50530501_20_dialog_content = "<color=#e8d9bb>パリンッ――</color>",
  ui_story_5053_50530501_21_dialog_content = "何の音？あれは…！？",
  ui_story_5053_50530501_22_dialog_content = "ここに…いたのね？",
  ui_story_5053_50530501_23_dialog_content = "「黒の天使」？なんでまた現れたんです？\n時間は戻ったんじゃないんですか？",
  ui_story_5053_50530501_24_dialog_content = "ね、姉さんの声です…",
  ui_story_5053_50530501_25_dialog_content = "ここに…いたのね！",
  ui_story_5053_50530501_26_dialog_content = "白夜よ、庇護を！",
  ui_story_5053_50530501_27_dialog_content = "カレブ、戦場で余計な考えは禁物だ！",
  ui_story_5053_50530501_28_dialog_content = "ああああ――！",
  ui_story_5053_50530501_29_dialog_content = "支配者の刃！",
  ui_story_5053_50530501_30_dialog_content = "憎い…",
  ui_story_5053_50530501_31_dialog_content = "ぐっ！",
  ui_story_5053_50530501_32_dialog_content = "速い…！城主様、お気を付けを！",
  ui_story_5053_50530501_33_dialog_content = "それほどまでに余と刃を交えたいか？",
  ui_story_5053_50530501_34_dialog_content = "ならば、叶えてやろう。",
  ui_story_5053_50530501_35_dialog_content = "ダ…ニエル…！",
  ui_story_5053_50530501_36_dialog_content = "ミヤたちがあの「黒の天使」と戦ってる…\n時間はちゃんと最初に戻ってるんだ！",
  ui_story_5053_50530501_37_dialog_content = "まずは皆を助けなきゃ！",
  ui_story_5053_50530501_38_dialog_content = "…ここに、いた。",
  ui_story_5053_50530501_39_dialog_content = "衛兵？ちょうどよかった…",
  ui_story_5053_50530501_40_dialog_content = "怪しい人物…消さねば…",
  ui_story_5053_50530501_41_dialog_content = "（え？この人たち、何かおかしい！？）",
  ui_story_5053_50530501_42_dialog_content = "あの、何を言ってるんですか？",
  ui_story_5053_50530501_43_dialog_content = "ヨシュア夫人…何者だ…？侵入者…？",
  ui_story_5053_50530501_44_dialog_content = "侵入者は捕らえよ…殺せ…捕らえよ…殺せ！",
  ui_story_5053_50530501_45_dialog_content = "（この人たち、理性を失ってる…？\n広場にいた人たちと一緒だ…）",
  ui_story_5053_50530501_46_dialog_content = "うわあああ！！！",
  ui_story_5053_50530502_1_dialog_content = "<color=#e8d9bb>ドカン――！！</color>",
  ui_story_5053_50530502_2_dialog_content = "うっ…ゴホッ…",
  ui_story_5053_50530502_3_dialog_content = "「黒の天使」はどこへ？",
  ui_story_5053_50530502_4_dialog_content = "外の小道から逃げたみたいね…",
  ui_story_5053_50530502_5_dialog_content = "城主様の一撃、まさに天地を切り裂く勢いでしたね！",
  ui_story_5053_50530502_6_dialog_content = "いくら「黒の天使」が強くたって、大きなダメージを受けてるはずです。\nそう遠くへは逃げられないんじゃないですか？",
  ui_story_5053_50530502_7_dialog_content = "…",
  ui_story_5053_50530502_8_dialog_content = "叔父様、あの「黒の天使」のことが気になりますか？",
  ui_story_5053_50530502_9_dialog_content = "あの声は確かに…いいえ、姉さんが怪物であるはずありません。",
  ui_story_5053_50530502_10_dialog_content = "それにしても、何かおかしい気が…\nあ、PlayerNameはどこへ行ったの？",
  ui_story_5053_50530502_11_dialog_content = "あ、そうですね！\nPlayerNameったら、どこに行ったんです！？",
  ui_story_5053_50530502_12_dialog_content = "あら、みんなここにいたのね。",
  ui_story_5053_50530502_13_dialog_content = "はぁ…はぁ…もう追ってこないよね？",
  ui_story_5053_50530502_14_dialog_content = "あそこだ…あそこにいるぞ！",
  ui_story_5053_50530502_15_dialog_content = "捕らえろ…殺せ…侵入者だ！",
  ui_story_5053_50530502_16_dialog_content = "（くっ！意識がハッキリしてないはずなのに、すごくしつこい！）",
  ui_story_5053_50530502_17_dialog_content = "違う、そうだ、あそこだ…！",
  ui_story_5053_50530502_18_dialog_content = "（…あ、そうだ！）",
  ui_story_5053_50530502_19_dialog_content = "<color=#e8d9bb>ドン――</color>",
  ui_story_5053_50530502_20_dialog_content = "（これは…荷車？祝典のための物資みたいだけど…\nここなら衛兵たちの盲点だよね）",
  ui_story_5053_50530502_21_dialog_content = "いない。別の場所を…",
  ui_story_5053_50530502_22_dialog_content = "あの通りへ…",
  ui_story_5053_50530502_23_dialog_content = "おや？誰かを探しているのでしょうか？\n様子が少しおかしいようですが。",
  ui_story_5053_50530502_24_dialog_content = "そうですわね。でも、こんな日に騒ぎを起こす人もいないでしょう？\nパレードももう少しで始まりますし。",
  ui_story_5053_50530502_25_dialog_content = "楽しみですわ。",
  ui_story_5053_50530502_26_dialog_content = "（ふぅ…ひとまず見つからずにすんだ…）",
  ui_story_5053_50530502_27_dialog_content = "（さっき通った人たちの話からすると、\nパレードはまだ始まってないのかな？）",
  ui_story_5053_50530502_28_dialog_content = "（まだ時間はありそうだ。もう一度状況を整理してみよう）",
  ui_story_5053_50530502_29_dialog_content = "（今僕が考えなきゃいけないのは…）",
  ui_story_5053_50530502_30_option_content = "今の状況",
  ui_story_5053_50530502_31_dialog_content = "（時間は今、パレード開始前まで戻ってる。\nということは、他の皆はヨシュア夫人に会ってるはずだ）",
  ui_story_5053_50530502_32_dialog_content = "（これから起こり得る状況は2つだけど、いずれにしても重要なのは、\n<color=#FFB400>2回目の時間の逆流が起こる前の出来事を皆が覚えてるかどうか</color>…）",
  ui_story_5053_50530502_33_dialog_content = "（もし覚えてるなら、今頃ヨシュア夫人と戦っているか、\nもしくは逃げてるはず…）",
  ui_story_5053_50530502_34_dialog_content = "（…とすると、皆きっと僕を探してるはずだ。\nだけど僕は白夜城の地理にはそこまで詳しくない…下手に動かない方がよさそうだ）",
  ui_story_5053_50530502_35_dialog_content = "（でももし、時間の逆流前の記憶がないとしたら、\n今ごろはまたヨシュア夫人のワナに引っかかって…）",
  ui_story_5053_50530502_36_dialog_content = "（時間の逆流が起こる前と同じように、\nジャキーニだけ宮殿に残って、他の皆は広場へ向かうはずだ）",
  ui_story_5053_50530502_37_dialog_content = "（ちょうど僕は今、広場近くにいる。\nここで皆が来るのを待ってるのが一番よさそうだ）",
  ui_story_5053_50530502_38_dialog_content = "（でもジャキーニは今ごろ…クソッ！\n皆が来るのを待って、一緒に助けに行くしかない！）",
  ui_story_5053_50530502_39_option_content = "「記憶」について",
  ui_story_5053_50530502_40_dialog_content = "（ジャキーニの話だと、占術を使う時には必ず、\n<color=#FFB400>厳格に決まりを守らなきゃいけない</color>）",
  ui_story_5053_50530502_41_dialog_content = "（最初に時間を逆流させた時、\nジャキーニは<color=#FFB400>しっかり手をつなぐ</color>ように言ってた）",
  ui_story_5053_50530502_42_dialog_content = "（でもヨシュア夫人は最初に時間を逆流させた時、\n僕たちと一緒にいて、だから逆流する前の事を覚えてるって言ってた）",
  ui_story_5053_50530502_43_dialog_content = "（つまり、最初に時間を戻した時…\nヨシュア夫人もこっそり僕たちと手をつないでたってこと？）",
  ui_story_5053_50530502_44_dialog_content = "（だとしたら、2回目に時間を戻した時「記憶の鏡晶」に\n触れてたのは僕とジャキーニだけだから…）",
  ui_story_5053_50530502_45_dialog_content = "（ヨシュア夫人と他の皆は2回目の時間の逆流前のことは\n覚えてないってことになる…）",
  ui_story_5053_50530502_46_dialog_content = "（つまり、真相を知ってるのは僕とジャキーニだけ…？）",
  ui_story_5053_50530502_47_dialog_content = "（そうだといいけど…）",
  ui_story_5053_50530502_48_option_content = "衛兵、ドラゴン、「黒の天使」のこと",
  ui_story_5053_50530502_49_dialog_content = "（あの衛兵たちはどうして僕を\n捕まえようとしてるんだろう？）",
  ui_story_5053_50530502_50_dialog_content = "（あの人たちの表情、広場で騒いでた様子のおかしい人たちと似てる。\n何か病気にかかったような…あるいは誰かに操られてるみたいだった）",
  ui_story_5053_50530502_51_dialog_content = "（衛兵たちはずっと僕と他の皆をわざと引き離すように追いかけ続けて、\n僕は宮殿を離れるしかなかった）",
  ui_story_5053_50530502_52_dialog_content = "（「記憶の鏡晶」の中では感知能力が使えない。\n庭で戦っている時、皆も宮殿の中の異常には気づいてなかった）",
  ui_story_5053_50530502_53_dialog_content = "（皆と合流する機会を逃してしまった…）",
  ui_story_5053_50530502_54_dialog_content = "（ヨシュア夫人に記憶が残ってたなら、\nあの追っ手は口封じに来たってことになる）",
  ui_story_5053_50530502_55_dialog_content = "（もしヨシュア夫人に時間の逆流前の記憶がなかったとしたら、\n僕だけを狙って孤立させ、先に1人だけ片付けようとしてるってことになる）",
  ui_story_5053_50530502_56_dialog_content = "（きっとそうだ。逆流の前にジャキーニを僕たちから引き離そうとしていたのと同じだ）",
  ui_story_5053_50530502_57_dialog_content = "（「黒の天使」との戦いもたぶんワナだ。\n僕たちを分断して、先にジャキーニを殺そうとしてるに違いない）",
  ui_story_5053_50530502_58_dialog_content = "（僕を追ってる衛兵が彼女の手下なら…）",
  ui_story_5053_50530502_59_dialog_content = "（広場の狂った人たちも、\nあの黒いドラゴンも夫人の手下である可能性がある）",
  ui_story_5053_50530502_60_dialog_content = "（そうすると、最初の時間の逆流後に起こった事はすべて、\n夫人の計画通りだってことに…なんて恐ろしい）",
  ui_story_5053_50530502_61_dialog_content = "（でも「黒の天使」って何者なんだろう？\nヨシュア夫人といったいどんな関係が？）",
  ui_story_5053_50530502_62_dialog_content = "（全部あの2人のお芝居ってこと？\nそれとも何か別の真相があるのかな…？）",
  ui_story_5053_50530502_63_dialog_content = "（うーん…情報が少なすぎる）",
  ui_story_5053_50530502_64_dialog_content = "（はぁ…色々考えてはみたけど、結局いま僕にできることは、\nここで皆が来るのを待つことだけか…）",
  ui_story_5053_50530502_65_dialog_content = "（合流したら、真相を話して、一緒にジャキーニを助けにいかなきゃ…）",
  ui_story_5053_50530502_66_dialog_content = "（みんな、絶対に無事でいてよ！）",
  ui_story_5053_50530601_1_dialog_content = "とすると、つまり…",
  ui_story_5053_50530601_2_dialog_content = "私たちが見事「黒の天使」を倒して\nヨシュア夫人を連れてここを離れるか――",
  ui_story_5053_50530601_3_dialog_content = "私たちが「黒の天使」に殺されて、\n現実世界で怪物が復活してしまうかの2つに1つってことですね？",
  ui_story_5053_50530601_4_dialog_content = "ええ、その通りよ。",
  ui_story_5053_50530601_5_dialog_content = "…",
  ui_story_5053_50530601_6_dialog_content = "脱出計画については分かりました。\nただ…",
  ui_story_5053_50530601_7_dialog_content = "PlayerNameはどこへ行ったんでしょう？心配ですね。",
  ui_story_5053_50530601_8_dialog_content = "別行動の時間が長くなるほど、\n何が起こるか分かりませんし…",
  ui_story_5053_50530601_9_dialog_content = "PlayerNameの状況はよく分からないけれど、\n衛兵に探してもらうわ。心配しないで。",
  ui_story_5053_50530601_10_dialog_content = "とにかく、時間に限りが有るわ。みんなが無事に出られるように、\nまずはあの怪物を倒すべきじゃないかしら？",
  ui_story_5053_50530601_11_dialog_content = "そういうことなら、急いであの「黒の天使」を片付けちゃいましょう！",
  ui_story_5053_50530601_12_dialog_content = "いいえ、ジャキーニさんには、\nわたくしと一緒に残ってもらうわ。",
  ui_story_5053_50530601_13_dialog_content = "え？なんでです？私の可愛い水晶玉、\n戦いですっごく役に立つんですよ！",
  ui_story_5053_50530601_14_dialog_content = "ええ、知っているわ。\nでも、あなたには「記憶の鏡晶」を操作してもらわないと。",
  ui_story_5053_50530601_15_dialog_content = "他のみなさんに何かあっても、\n時間を戻してまた元の状態に戻せばすむでしょう？",
  ui_story_5053_50530601_16_dialog_content = "あなたに何かあったら、\n取り返しのつかないことになるわ…",
  ui_story_5053_50530601_17_dialog_content = "た、確かにその通りです…",
  ui_story_5053_50530601_18_dialog_content = "お母様とジャキーニが残るなら、\nカレンを呼び戻しましょう。",
  ui_story_5053_50530601_19_dialog_content = "お母様も私もいなくて、きっと寂しい思いをしてるはずよ。\nかわいそうだわ。",
  ui_story_5053_50530601_20_dialog_content = "そうね。では、この後使いを遣って、\nカレンに部屋に戻って休むよう伝えてもらいましょう。",
  ui_story_5053_50530601_21_dialog_content = "お母様のお側にいさせてあげれば？\nあの子、ずっと楽しみにしていたのに、お部屋に帰してしまうの？",
  ui_story_5053_50530601_22_dialog_content = "パレードをずっと楽しみにしていたし、\n帰ってもお母様の近くにいられないなんて…",
  ui_story_5053_50530601_23_dialog_content = "ロニー、「記憶の鏡晶」の中で起こることはすべて幻影なの。\n真実ではないのよ。",
  ui_story_5053_50530601_24_dialog_content = "大局を重んじなければならないわ。\n小さなことで一番大事な目的が果たせなくなってはいけないのよ。",
  ui_story_5053_50530601_25_dialog_content = "…",
  ui_story_5053_50530601_26_dialog_content = "姉さんの言う通り、ここで起こる事はすべて幻影です。\nミヤ、感情に振り回されてはいけません。",
  ui_story_5053_50530601_27_dialog_content = "わ、分かりました。ごめんなさい…私、まだ未熟で…",
  ui_story_5053_50530601_28_dialog_content = "…",
  ui_story_5053_50530601_29_dialog_content = "ヨシュアの言うことにも一理ある。\n全員の安全が第一だ。カレブも残るがよい。",
  ui_story_5053_50530601_30_dialog_content = "PlayerNameは余が探すとしよう。\n皆無事に合流せねばならん。",
  ui_story_5053_50530601_31_dialog_content = "あなたがわざわざ行くことはないわ。\n衛兵に探させても同じよ。",
  ui_story_5053_50530601_32_dialog_content = "でも、あの怪物は全員が力を合わせなければ、\n勝てる可能性は低いわ。",
  ui_story_5053_50530601_33_dialog_content = "どちらの方が重要か、あなたなら判断がつくはずよ。\n冷静にならなくては。",
  ui_story_5053_50530601_34_dialog_content = "さすが、差し引きが分かっておるな。実に懐かしい会話だ。\nまるで昔に戻ったかのようではないか。",
  ui_story_5053_50530601_35_dialog_content = "…",
  ui_story_5053_50530601_36_dialog_content = "今はご夫婦で言い争う時ではありません。\nそもそも残された時間が少ないのですよ。",
  ui_story_5053_50530601_37_dialog_content = "もとより何をすべきかは理解しておる。\n指図など必要ない。",
  ui_story_5053_50530601_38_dialog_content = "ミヤ、行くぞ。",
  ui_story_5053_50530601_39_dialog_content = "は、はい、お父様。",
  ui_story_5053_50530601_40_dialog_content = "何なんでしょう、あの方は！\n急にへそを曲げるなんて。",
  ui_story_5053_50530601_41_dialog_content = "…",
  ui_story_5053_50530601_42_dialog_content = "ヨシュアのことで気がかりがあるのか？",
  ui_story_5053_50530601_43_dialog_content = "あ、ええと、その…確かに少し…",
  ui_story_5053_50530601_44_dialog_content = "たぶん、私自身の問題なんです…\n離れていた時間が長かったせいか、お母様が何だか遠くに感じられて…",
  ui_story_5053_50530601_45_dialog_content = "では、お前の思う母ヨシュアとは、どのような人物だ？",
  ui_story_5053_50530601_46_dialog_content = "お母様は…誰よりも優しく、誰よりも寛容で、\n誰よりも子どもを深く愛している人です。",
  ui_story_5053_50530601_47_dialog_content = "そうか。余の知るヨシュアも陽光のように優しく、\nしかして固い意志を持つ、誠実で勇敢な者であった。",
  ui_story_5053_50530601_48_dialog_content = "お父様…！",
  ui_story_5053_50530601_49_dialog_content = "ミヤ、己を信じよ。\nそしてお前の思う、優しく強い母を信じるのだ。",
  ui_story_5053_50530601_50_dialog_content = "自分を信じる、ですか？",
  ui_story_5053_50530601_51_dialog_content = "この予想外の事態の中で、まだ稚拙さが残っておるにせよ、\nお前は十分に己の強さと勇気を示した。",
  ui_story_5053_50530601_52_dialog_content = "その成長は、余も認めざるを得まい。",
  ui_story_5053_50530601_53_dialog_content = "今後はお前の考えを尊重しよう。\nむやみに干渉はせぬ。",
  ui_story_5053_50530601_54_dialog_content = "お前の母の事にしろ、カレンやその他の事にしろ、\nもう恐れる必要はない。",
  ui_story_5053_50530601_55_dialog_content = "己の正しいと信じる道を堂々と歩むがよい。\n余はお前を信じる。",
  ui_story_5053_50530601_56_dialog_content = "（お父様、励ましてくださってるの？）",
  ui_story_5053_50530601_57_dialog_content = "（こんなことを言ってくださるなんて、初めての気が…\nでも、嬉しい…）",
  ui_story_5053_50530601_58_dialog_content = "ありがとうございます、お父様。\nもっと勇気を持てるよう努力いたします。",
  ui_story_5053_50530601_59_dialog_content = "では、先程の作戦通り、私は上に行きます。\n「黒の天使」を見つけ次第、お知らせします。",
  ui_story_5053_50530601_60_dialog_content = "十分に気を付けよ、ミヤ。",
  ui_story_5053_50530601_61_dialog_content = "（ミヤはひとまず心配あるまい。\nだが、PlayerNameはどこへ行った？）",
  ui_story_5053_50530601_62_dialog_content = "（何かがおかしい。いったい…）",
  ui_story_5053_50530601_63_dialog_content = "ここに…",
  ui_story_5053_50530601_64_dialog_content = "いたのね！",
  ui_story_5053_50530601_65_dialog_content = "この声は…",
  ui_story_5053_50530601_66_dialog_content = "ダニ…エル…！！",
  ui_story_5053_50530601_67_dialog_content = "ああああ！！",
  ui_story_5053_50530601_68_dialog_content = "このような所に現れるとは…",
  ui_story_5053_50530601_69_dialog_content = "まあよい。民に危害が及ばぬだけ良しとしよう。",
  ui_story_5053_50530601_70_dialog_content = "痛い…殺す…殺す…！",
  ui_story_5053_50530601_71_dialog_content = "余はヨシュアの声などで惑いはせぬぞ。",
  ui_story_5053_50530701_1_dialog_content = "うう…ああ！",
  ui_story_5053_50530701_2_dialog_content = "（ミヤとカレブがおらぬ今、戦力は互角といったところか。\nただ、この数の暗鬼では戦局が不利になろう）",
  ui_story_5053_50530701_3_dialog_content = "「白夜よ、庇護を！」",
  ui_story_5053_50530701_4_dialog_content = "これでほぼ互角だ。満足か？",
  ui_story_5053_50530701_5_dialog_content = "ダ…ニ…エル…！",
  ui_story_5053_50530701_6_dialog_content = "憎い…あなたが…憎い…！",
  ui_story_5053_50530701_7_dialog_content = "なぜ…なの…？",
  ui_story_5053_50530701_8_dialog_content = "辛い…苦しい…！なぜ…裏切った…の！？",
  ui_story_5053_50530701_9_dialog_content = "一緒に…未来を…切り開こうと…、約束…したのに…！",
  ui_story_5053_50530701_10_dialog_content = "なぜ…家族や…わたくしを…犠牲に…するの！？",
  ui_story_5053_50530701_11_dialog_content = "辛い…苦しい！",
  ui_story_5053_50530701_12_dialog_content = "何を…",
  ui_story_5053_50530701_13_dialog_content = "こんな…ことなら…",
  ui_story_5053_50530701_14_dialog_content = "あなたと…出会わなければ…よかった…",
  ui_story_5053_50530701_15_dialog_content = "あなたと…結ばれなければ…よかったのに！！",
  ui_story_5053_50530701_16_dialog_content = "！？",
  ui_story_5053_50530701_17_dialog_content = "ヨシュア…！？",
  ui_story_5053_50530701_18_dialog_content = "あり得ぬ…",
  ui_story_5053_50530701_19_dialog_content = "…！！！",
  ui_story_5053_50530701_20_dialog_content = "あ…！ヴェロニカが…危ない…",
  ui_story_5053_50530701_21_dialog_content = "どこへ行く！？",
  ui_story_5053_50530701_22_dialog_content = "グオォォ――！",
  ui_story_5053_50530701_23_dialog_content = "ええい、邪魔だ！",
  ui_story_5053_50530701_24_dialog_content = "（こっちの世界のソルラドさんのあいさつが終わった。\nこの後、決闘の儀式が始まる…）",
  ui_story_5053_50530701_25_dialog_content = "（前回の流れなら、次にドラゴンが現れて、\n民衆と兵士が一斉に大騒ぎになる…）",
  ui_story_5053_50530701_26_dialog_content = "（その混乱に乗じて、壇上に向かおう！\n皆と合流して、ヨシュア夫人のことを教えなきゃ！）",
  ui_story_5053_50530701_27_dialog_content = "グォォ――！",
  ui_story_5053_50530701_28_dialog_content = "きゃああああ！！",
  ui_story_5053_50530701_29_dialog_content = "あ、あれは何だ！？",
  ui_story_5053_50530701_30_dialog_content = "助けて！は、早く逃げろ！！",
  ui_story_5053_50530701_31_dialog_content = "よし！この隙に一気にソルラドさんたちと合流して――",
  ui_story_5053_50530701_32_dialog_content = "<color=#e8d9bb>ドカン！！</color>",
  ui_story_5053_50530701_33_dialog_content = "ど、どういうこと…！？あれは…",
  ui_story_5053_50530701_34_dialog_content = "グォォ――！",
  ui_story_5053_50530701_35_dialog_content = "<color=#e8d9bb>ドン！！！</color>",
  ui_story_5053_50530701_36_dialog_content = "ああ…！！うっ！！",
  ui_story_5053_50530701_37_dialog_content = "いったいどういうこと！？\nあれは「黒の天使」じゃ…？",
  ui_story_5053_50530701_38_dialog_content = "空中で何をしてるの？\nドラゴンの攻撃を阻止してる？",
  ui_story_5053_50530701_39_dialog_content = "ドラゴンか！？",
  ui_story_5053_50530701_40_dialog_content = "龍だ！龍が降臨したぞ！",
  ui_story_5053_50530701_41_dialog_content = "謀反…カルティマか？",
  ui_story_5053_50530701_42_dialog_content = "このような時に現れるとは、大した度胸だ。",
  ui_story_5053_50530701_43_dialog_content = "（しかし、黒い怪物の方は…？）",
  ui_story_5053_50530701_44_dialog_content = "お、お姉様、何が起こっているの？",
  ui_story_5053_50530701_45_dialog_content = "カレン、私の後ろに隠れて！",
  ui_story_5053_50530701_46_dialog_content = "（あれは「黒の天使」だわ。でも…どういうことなの？）",
  ui_story_5053_50530701_47_dialog_content = "いったいどうなっているの…！？",
  ui_story_5053_50530701_48_dialog_content = "ヴェロニカ、カレン、下がっておれ！",
  ui_story_5053_50530701_49_dialog_content = "<color=#e8d9bb>ボン――</color>",
  ui_story_5053_50530701_50_dialog_content = "（炎が当たった…いいえ、違う。\n黒の天使がドラゴンの炎を受け止めたんだわ…）",
  ui_story_5053_50530701_51_dialog_content = "でも、いったいどうして…",
  ui_story_5053_50530701_52_dialog_content = "お姉様、あの怪物がドラゴンの攻撃から\n私たちを守ってくれたみたい。",
  ui_story_5053_50530701_53_dialog_content = "でも…気を失ってしまったみたいよ？",
  ui_story_5053_50530701_54_dialog_content = "「黒の天使」が…？どうして…？",
  ui_story_5053_50530701_55_dialog_content = "ミヤ！！",
  ui_story_5053_50530701_56_dialog_content = "ミヤ！無事？",
  ui_story_5053_50530701_57_dialog_content = "PlayerName？私は大丈夫、心配しないで。\nそれより、どうしてここに？",
  ui_story_5053_50530701_58_dialog_content = "こ、ここにいたぞ…！",
  ui_story_5053_50530701_59_dialog_content = "殺せ…殺せ…侵入者を殺せ！",
  ui_story_5053_50530701_60_dialog_content = "うっ！またあの人たちだ！",
  ui_story_5053_50530701_61_dialog_content = "衛兵たち…なんだか様子がおかしいわ！？",
  ui_story_5053_50530701_62_dialog_content = "龍だ！龍が降臨したぞ！",
  ui_story_5053_50530701_63_dialog_content = "突撃だ！",
  ui_story_5053_50530701_64_dialog_content = "PlayerName、気を付けて！\n反乱軍が向かってくるわ！",
  ui_story_5053_50530701_65_dialog_content = "ミヤ、事情は後で話すね。\n戦況がだいぶ混乱してる、まずは戦おう！",
  ui_story_5053_50530701_66_dialog_content = "ドラゴンにせよ、黒い怪物にせよ…\n今日この日にソルラド家の権威を試すとはな！",
  ui_story_5053_50530701_67_dialog_content = "グォォ！！！",
  ui_story_5053_50530701_68_dialog_content = "用心せよ！ひとまず「黒の天使」には構うな！",
  ui_story_5053_50530701_69_dialog_content = "あれは他の敵とは違う。一息で倒せるものではない。",
  ui_story_5053_50530701_70_dialog_content = "お主、何者だ…？",
  ui_story_5053_50530701_71_dialog_content = "火力を集中せよ、余と共に龍を打ち倒すのだ！",
  ui_story_5053_50530701_72_dialog_content = "たかが龍ごとき…",
  ui_story_5053_50530701_73_dialog_content = "白夜の光よ！",
  ui_story_5053_50530701_74_dialog_content = "グオオ――グオォ！！",
  ui_story_5053_50530701_75_dialog_content = "なに！？のどを貫いた傷が一瞬で治っただと！？",
  ui_story_5053_50530701_76_dialog_content = "治癒能力が高いのか？それとも…「不死性」か？",
  ui_story_5053_50530701_77_dialog_content = "あり得ぬ…いったい誰がそれほどの力を与えたというのだ？\nマイムか？",
  ui_story_5053_50530701_78_dialog_content = "…",
  ui_story_5053_50530701_79_dialog_content = "警戒せよ。次の攻撃がくる。",
  ui_story_5053_50530801_1_dialog_content = "うう…はぁ…はぁ…",
  ui_story_5053_50530801_2_dialog_content = "殺せ、殺せ…侵入者を…殺せ！",
  ui_story_5053_50530801_3_dialog_content = "殺せええええ！！",
  ui_story_5053_50530801_4_dialog_content = "ううっ、狂った衛兵がどんどん増えてる…\nミヤ、まだ持ちこたえられる？",
  ui_story_5053_50530801_5_dialog_content = "見た目からして不気味すぎるよ。\n瞳が真っ白になってるし、表情もヘンだし…",
  ui_story_5053_50530801_6_dialog_content = "私は大丈夫。でも、このままじゃ敵が増えるばかりだわ！",
  ui_story_5053_50530801_7_dialog_content = "さっきまで逃げ回っていた人が次の瞬間にはおかしくなって…\n倒した反乱軍の人たちまで…",
  ui_story_5053_50530801_8_dialog_content = "まるで伝染病のようだわ…",
  ui_story_5053_50530801_9_dialog_content = "たぶんあいつらに傷つけられると、ああなっちゃうんだ。\nミヤ、距離をしっかり保って戦って！",
  ui_story_5053_50530801_10_dialog_content = "でも、これじゃキリがないわ。\nいつかは体力が尽きてしまう…",
  ui_story_5053_50530801_11_dialog_content = "これも彼女の企みのうちってことなのかな…！？\n誰か助けに来てくれそうな人は…あ、城主さん！！",
  ui_story_5053_50530801_12_dialog_content = "お父様は今ドラゴンと戦っているわ、応援はムリよ！",
  ui_story_5053_50530801_13_dialog_content = "（お父様、私はどうすれば…？）",
  ui_story_5053_50530801_14_dialog_content = "お前の母の事にしろ、カレンやその他の事にしろ、\nもう恐れる必要はない。",
  ui_story_5053_50530801_15_dialog_content = "己の正しいと信じる道を堂々と歩むがよい。\n余はお前を信じる。",
  ui_story_5053_50530801_16_dialog_content = "（自分を信じる、自分の判断を…）",
  ui_story_5053_50530801_17_dialog_content = "ヒポカ――！",
  ui_story_5053_50530801_18_dialog_content = "<color=#e8d9bb>ドン！！！</color>",
  ui_story_5053_50530801_19_dialog_content = "つ、強い！",
  ui_story_5053_50530801_20_dialog_content = "ヒポカ、出て来てくれてありがとう。\nもう二度とあなたを放さないわ…！",
  ui_story_5053_50530801_21_dialog_content = "ミヤ、すごいよ！\n狂った衛兵たちをほとんど倒しちゃった！",
  ui_story_5053_50530801_22_dialog_content = "役に立ったなら良かったわ。\n急いでお父様の応援に向かいましょう！",
  ui_story_5053_50530801_23_dialog_content = "ミヤ…ちょっと待って…",
  ui_story_5053_50530801_24_dialog_content = "…はぁ、はぁ…",
  ui_story_5053_50530801_25_dialog_content = "お…お姉様…",
  ui_story_5053_50530801_26_dialog_content = "カ、カレン！？頭から血が…！？",
  ui_story_5053_50530801_27_dialog_content = "狂った衛兵にケガを！？\nだったら、カレンは…",
  ui_story_5053_50530801_28_dialog_content = "ミヤ、近づいちゃだめだ！\nカレンの瞳が衛兵たちと同じようになってる！",
  ui_story_5053_50530801_29_dialog_content = "カレン、ランスを置いて…お姉様の方へ来なさい。",
  ui_story_5053_50530801_30_dialog_content = "ね、いい子だから。",
  ui_story_5053_50530801_31_dialog_content = "…",
  ui_story_5053_50530801_32_dialog_content = "お姉様…い、痛い…",
  ui_story_5053_50530801_33_dialog_content = "怖がらなくて大丈夫よ。お姉様が傷の手当をしてあげる。\nだから、武器を置いてちょうだい。ね？",
  ui_story_5053_50530801_34_dialog_content = "ううん。私、頭が…痛いの…！",
  ui_story_5053_50530801_35_dialog_content = "おかしな声が聞こえる…お姉様を殺せって…\n嫌よ！",
  ui_story_5053_50530801_36_dialog_content = "カレン、大丈夫よ。お姉様が守ってあげるから！",
  ui_story_5053_50530801_37_dialog_content = "お姉様、来ちゃダメ！！",
  ui_story_5053_50530801_38_dialog_content = "…私は、カレン・ド・ソルラド…高潔なるソルラド家の娘、\n白夜城の守護者…",
  ui_story_5053_50530801_39_dialog_content = "絶対に家族を傷つけたりしない！絶対に！",
  ui_story_5053_50530801_40_dialog_content = "うう…ああっ！カレンはお姉様を傷つけない！\nそんなことをするくらいなら…",
  ui_story_5053_50530801_41_dialog_content = "お姉様、ごめんなさい。\nカレン、もうおそばにはいられない。",
  ui_story_5053_50530801_42_dialog_content = "ダメよ！武器を下ろして！ダメ、止めてっ！！",
  ui_story_5053_50530801_43_dialog_content = "カレン！！",
  ui_story_5053_50530801_44_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5053_50530801_45_dialog_content = "ランスで喉を…",
  ui_story_5053_50530801_46_dialog_content = "カレンが……",
  ui_story_5053_50530801_47_dialog_content = "…",
  ui_story_5053_50530801_48_dialog_content = "あ…ああ…",
  ui_story_5053_50530801_49_dialog_content = "あああああああ！！！！",
  ui_story_5053_50530801_50_dialog_content = "いや、いやあああああああ！！",
  ui_story_5053_50530801_51_dialog_content = "ミヤ！ミヤ、しっかりして！これは現実じゃないんだ…\nこの世界のカレンはただの幻影なんだよ！！",
  ui_story_5053_50530801_52_dialog_content = "カレン！！カレン！！逝かないで…ダメよ…\nカレン…私を一人にしないで…カレン…",
  ui_story_5053_50530801_53_dialog_content = "ミヤ、しっかりして！僕の声が聞こえる？ミヤ！！",
  ui_story_5053_50530801_54_dialog_content = "（僕の声がまったく聞こえないみたいだ…\nまさかまた発作が…！？）",
  ui_story_5053_50530801_55_dialog_content = "ああああああ！！",
  ui_story_5053_50530801_56_dialog_content = "熱い！",
  ui_story_5053_50530801_57_dialog_content = "ミヤの力が暴走し始めた！？",
  ui_story_5053_50530801_58_dialog_content = "…",
  ui_story_5053_50530801_59_dialog_content = "な、何するつもり…！？",
  ui_story_5053_50530801_60_dialog_content = "泣かないで…",
  ui_story_5053_50530801_61_dialog_content = "ロニー…泣かないで…私のロニー…",
  ui_story_5053_50530801_62_dialog_content = "悲しむことはないわ…大丈夫よ…",
  ui_story_5053_50530801_63_dialog_content = "あ…",
  ui_story_5053_50530801_64_dialog_content = "薔薇を一輪…かわいいあの子に贈りましょう…♪",
  ui_story_5053_50530801_65_dialog_content = "そよ風が頬をなでる…\nあなたの笑顔は世界に一つだけの宝物…♪",
  ui_story_5053_50530801_66_dialog_content = "薔薇を一輪…大切なパパとママに贈りましょう…♪",
  ui_story_5053_50530801_67_dialog_content = "どんな時も…愛しい家族、私の宝物…♪",
  ui_story_5053_50530801_68_dialog_content = "ロニー…お母様よ…",
  ui_story_5053_50530801_69_dialog_content = "お母様…？お母様…",
  ui_story_5053_50530801_70_dialog_content = "あ、あああああ！",
  ui_story_5053_50530801_71_dialog_content = "カレン、カレンが…",
  ui_story_5053_50530801_72_dialog_content = "カレンの手が…さっきまであんなに暖かかった手が…\nカレンが血を流して…",
  ui_story_5053_50530801_73_dialog_content = "お母様…ああ…",
  ui_story_5053_50530801_74_dialog_content = "大丈夫…悪い夢を見ているだけよ…",
  ui_story_5053_50530801_75_dialog_content = "ロニーは…悪い夢を…見ているだけ…",
  ui_story_5053_50530801_76_dialog_content = "泣きたければ…好きなだけ泣いて…",
  ui_story_5053_50530801_77_dialog_content = "お母様が…そばにいてあげる…",
  ui_story_5053_50530801_78_dialog_content = "…",
  ui_story_5053_50530801_79_dialog_content = "温かい…懐かしい子守歌…",
  ui_story_5053_50530801_80_dialog_content = "本当にお母様なのね…",
  ui_story_5053_50530801_81_dialog_content = "お母様…ずっと会いたかった…",
  ui_story_5053_50530801_82_dialog_content = "お母様もよ…会いたかったわ…",
  ui_story_5053_50530801_83_dialog_content = "（黒の天使が優しくミヤをなぐさめてる…？）",
  ui_story_5053_50530801_84_dialog_content = "（黒の天使は理性を失った怪物じゃなかった！？\nいや…ヨシュア夫人の言ってたことが全部ウソだったなら…）",
  ui_story_5053_50530801_85_dialog_content = "…ミヤ、大丈夫？立てる？",
  ui_story_5053_50530801_86_dialog_content = "PlayerName…ごめんなさい、取り乱してしまって…",
  ui_story_5053_50530801_87_dialog_content = "私、あなたを傷つけたりしてない…？",
  ui_story_5053_50530801_88_dialog_content = "そんなことあるわけないでしょ。\n僕は全然大丈夫。君が無事ならいいんだ。",
  ui_story_5053_50530801_89_dialog_content = "でも、「黒の天使」って何者なの？\n僕にはまったく分からなくなったよ。",
  ui_story_5053_50530801_90_dialog_content = "黒の天使こそお母様よ。私にはわかった。",
  ui_story_5053_50530801_91_dialog_content = "黒の天使が本物のヨシュア夫人…！？",
  ui_story_5053_50530801_92_dialog_content = "理屈では理解しがたいってことは分かってるわ。\nでも、感じるの。黒の天使はお母様だって…",
  ui_story_5053_50530801_93_dialog_content = "もう1人のお母様は「黒の天使」を理性を失った怪物だと言ったけど、\n「黒の天使」の胸の中は優しさであふれてる…",
  ui_story_5053_50530801_94_dialog_content = "そもそも宮殿にいるお母様の方が、\nどこか遠い存在のような気がしていた…",
  ui_story_5053_50530801_95_dialog_content = "…いや、分かる気がするよ。\nむしろその方が、全てに筋が通るって言った方がいいかな。",
  ui_story_5053_50530801_96_dialog_content = "え？どういうこと？",
  ui_story_5053_50530801_97_dialog_content = "一言で説明するのは難しいんだ。\nとにかく今はジャキーニが危ない。急いで戻らないと！",
  ui_story_5053_50530801_98_dialog_content = "詳しい事は移動しながら話すよ！",
  ui_story_5053_50530801_99_dialog_content = "ジャキーニ？だったら心配いらないわ。\nカレブ叔父様も一緒だもの、守ってくださるはずよ。",
  ui_story_5053_50530801_100_dialog_content = "あの二人は一緒にいるの？",
  ui_story_5053_50530801_101_dialog_content = "ええ。お父様が叔父様に残るように言ったの。\n最初はどうしてそうしたのか分からなかったけど。",
  ui_story_5053_50530801_102_dialog_content = "いや、カレブさんが残っていたとしても、\nたぶん同じことだと思う。",
  ui_story_5053_50530801_103_dialog_content = "宮殿にいる「ヨシュア夫人」は血も涙もないんだ。\n手段を選ばずに僕たち全員を殺そうとしてる。",
  ui_story_5053_50530801_104_dialog_content = "な…なんですって…！？",
  ui_story_5053_50530801_105_dialog_content = "ミヤ、実はこれが初めてじゃないんだ！",
  ui_story_5053_50530801_106_dialog_content = "！！",
  ui_story_5053_50530801_107_dialog_content = "カレブが…危ない…",
  ui_story_5053_50530801_108_dialog_content = "カレ…ブ…わたくしの…弟…",
  ui_story_5053_50530801_109_dialog_content = "弟が…危ない…",
  ui_story_5053_50530801_110_dialog_content = "――つまり、時間は2回巻き戻されているということ…？",
  ui_story_5053_50530801_111_dialog_content = "今すぐ戻らなきゃ！お父様の所へ行きましょう！！",
  ui_story_5053_50530801_112_dialog_content = "お父様！",
  ui_story_5053_50530801_113_dialog_content = "城主さん！すぐに宮殿に戻って、カレブさんとジャキーニを助けましょう！\n詳しい事は道中でお話しします！",
  ui_story_5053_50530801_114_dialog_content = "ダ…ニエル…",
  ui_story_5053_50530801_115_dialog_content = "…どうやら余の考えていたより複雑な事態のようだな。",
  ui_story_5053_50530801_116_dialog_content = "だが、余がここを離れるわけにはいかぬ。",
  ui_story_5053_50530801_117_dialog_content = "このドラゴンはいかなる傷もすぐに回復する。\n致命傷さえもだ。",
  ui_story_5053_50530801_118_dialog_content = "「不死性」と言う、この忌まわしい特性だが…",
  ui_story_5053_50530801_119_dialog_content = "伝え聞くところ、それを持ちうるものは、\n「記憶の鏡晶」の中の幻影のみだ。",
  ui_story_5053_50530801_120_dialog_content = "そんな、どうして…",
  ui_story_5053_50530801_121_dialog_content = "たぶん「ヨシュア夫人」のしわざでしょう。\n城主さん、ここでドラゴンを足止めしてもらえますか？",
  ui_story_5053_50530801_122_dialog_content = "「ヨシュア夫人」か…よかろう。\n宮殿はお主らに任せる。",
  ui_story_5053_50530801_123_dialog_content = "ヴェロニカ、なぜまだ逃げておらぬ？\nそばにいるのは…",
  ui_story_5053_50530801_124_dialog_content = "…",
  ui_story_5053_50530801_125_dialog_content = "お父様…急いで宮殿に戻り、やらなければならないことがあります。\nどうかお止めにならないでください。",
  ui_story_5053_50530801_126_dialog_content = "今この状況より急ぐことか？",
  ui_story_5053_50530801_127_dialog_content = "何者とも知れぬやからと行動を共にするなど、許さぬぞ。",
  ui_story_5053_50530801_128_dialog_content = "城主殿下、貴殿はすでに私という何者とも知れぬ年寄りと共に戦っておられる。",
  ui_story_5053_50530801_129_dialog_content = "今になって気にすることではありますまい。",
  ui_story_5053_50530801_130_dialog_content = "…",
  ui_story_5053_50530801_131_dialog_content = "心配せずとも、私はPlayerNameとヴェロニカ殿下の仲間だ。\nあなたの家族は我々がお守りしよう。",
  ui_story_5053_50530801_132_dialog_content = "貴殿にはこの白夜城の民を守るという責任がある。\n全ての民をな。",
  ui_story_5053_50530801_133_dialog_content = "その必要はない。戦いは長けた者に任せてある。\n我が妻も凡骨ではない。諸君らの手をわずらわせることもない。",
  ui_story_5053_50530801_134_dialog_content = "それに、怪物のような見てくれの者までいるとなっては、\nにわかに信用できぬ。",
  ui_story_5053_50530801_135_dialog_content = "…",
  ui_story_5053_50530801_136_dialog_content = "心配は要らぬ、我が妻だ。",
  ui_story_5053_50530801_137_dialog_content = "何…！？",
  ui_story_5053_50530801_138_dialog_content = "…！",
  ui_story_5053_50530801_139_dialog_content = "（お父様もやっぱり、本物のお母様はこっちだと思っていたのね！）",
  ui_story_5053_50530801_140_dialog_content = "オホン…貴殿、ただ者にはない伴侶選びの眼があるようであるな。",
  ui_story_5053_50530801_141_dialog_content = "ふん、お互いにな。",
  ui_story_5053_50530801_142_dialog_content = "2人とも、急ぐのだ。残された時は多くない。",
  ui_story_5053_50530801_143_dialog_content = "はい！",
  ui_story_5053_50530801_144_dialog_content = "カレブ…",
  ui_story_5053_50530801_145_dialog_content = "お母様もいらっしゃる？",
  ui_story_5053_50530801_146_dialog_content = "カレブを…守る…",
  ui_story_5053_50530801_147_dialog_content = "ええ、一緒に叔父様を守りましょう！",
  ui_story_5053_50530901_1_dialog_content = "カレブさん、外の様子はどうです？",
  ui_story_5053_50530901_2_dialog_content = "さっき鼓膜が破れそうなほど大きい音がしましたね。\n何だかイヤな予感がします。",
  ui_story_5053_50530901_3_dialog_content = "ええ、なぜだか分かりませんが、\nドラゴンが予想よりも早く現れました。",
  ui_story_5053_50530901_4_dialog_content = "今ごろ広場は大騒ぎでしょうね。",
  ui_story_5053_50530901_5_dialog_content = "だとしたら、みなさんとても危険な状態なんじゃありません？",
  ui_story_5053_50530901_6_dialog_content = "城主様にミヤ、それから行方の分からないPlayerNameも…",
  ui_story_5053_50530901_7_dialog_content = "心配はいらないわ。ダニエルがいれば。",
  ui_story_5053_50530901_8_dialog_content = "宮殿の方も…いいわ、順調よ。時間通りね。",
  ui_story_5053_50530901_9_dialog_content = "…",
  ui_story_5053_50530901_10_dialog_content = "さすが姉さんですね。前もって対策を練ってあったとは。",
  ui_story_5053_50530901_11_dialog_content = "ジャキーニさん、心配はご無用ですよ。",
  ui_story_5053_50530901_12_dialog_content = "そうですね…",
  ui_story_5053_50530901_13_dialog_content = "そうそう、ジャキーニさん。\n部屋のドアを閉めてもらえるかしら？",
  ui_story_5053_50530901_14_dialog_content = "あ、そうですね！鍵を掛けた方が安心ですもんね。\n了解です。",
  ui_story_5053_50530901_15_dialog_content = "カレブ、一つ聞きたいことがあるの。\nなぜわたくしを助けたいの？",
  ui_story_5053_50530901_16_dialog_content = "え？あなたは僕の姉さんです。\n姉さんを助けるのは当然のことではありませんか。",
  ui_story_5053_50530901_17_dialog_content = "…「家族」だからってことかしら？",
  ui_story_5053_50530901_18_dialog_content = "当然です。僕にとって、この世のあらゆるものが不確実なのです。\nですが、姉さんと僕、父さんだけは…",
  ui_story_5053_50530901_19_dialog_content = "僕たち家族の絆だけは変わりません。\nどれだけの年月が過ぎようとも、そう確信しています。",
  ui_story_5053_50530901_20_dialog_content = "そう？動機は何にせよ、少なくともわたくしの肉体を助けてくれたのだもの。\nあなたには感謝しなくてはね。",
  ui_story_5053_50530901_21_dialog_content = "よくやったわ、カレブ。",
  ui_story_5053_50530901_22_dialog_content = "姉さん…！",
  ui_story_5053_50530901_23_dialog_content = "確かにこの世のあらゆるものは不確実よね。\nでも、いくら時間が経っても、変わらないものがあるの…",
  ui_story_5053_50530901_24_dialog_content = "12年経ったわ。今の白夜城は何か変わったかしら？",
  ui_story_5053_50530901_25_dialog_content = "いいえ、相変わらず昔のままです。\n貴族の虫けらどもは今だ現状に甘んじ、変化を拒み、愚かそのものです。",
  ui_story_5053_50530901_26_dialog_content = "貴族たちに食いつくされ、白夜城も今やただ輝かしい外見を残すばかりになりました。\n内から外まで腐り切っています。",
  ui_story_5053_50530901_27_dialog_content = "やはりそうなのね…では、ソルラド家はどうかしら？",
  ui_story_5053_50530901_28_dialog_content = "ソルラドですか？白夜城よりもさらに目も当てられません。",
  ui_story_5053_50530901_29_dialog_content = "当時奴がもっともらしく姉さんに誓った言葉のうち、\n実現したことがいくつありますか？",
  ui_story_5053_50530901_30_dialog_content = "何が「白夜城を根底から改革し、\nこの地を最も公平で自由な場所に変えてみせる」ですか…",
  ui_story_5053_50530901_31_dialog_content = "あの腐り切った貴族どもとやり合うのに精いっぱいで、\n何も変えられていやしません。",
  ui_story_5053_50530901_32_dialog_content = "家族も奴の弱さのためにバラバラになり、\n姉さんも、ミヤもカレンも皆巻き込んで、男の風上にも置けない奴です。",
  ui_story_5053_50530901_33_dialog_content = "政治の事はよく分かりませんが、\nカレブさんも少し極端過ぎやしません？",
  ui_story_5053_50530901_34_dialog_content = "厄介な貴族のオジサンたちを相手にしながら、\n民衆にとって偉大で頼りがいのある君主になっただけでも十分すごいですよ？",
  ui_story_5053_50530901_35_dialog_content = "ジャキーニさん、あなたは北境の方ですから、輝かしい外見しか見えていないのです。\n実際の白夜城のことをどれだけご存じだというのですか？",
  ui_story_5053_50530901_36_dialog_content = "でも、北境の女王陛下さえソルラド様は…\nはぁ…やめやめ！私は衛兵とおしゃべりでもしてきます！",
  ui_story_5053_50530901_37_dialog_content = "だったら、わたくしはどう？\nソルラド家に嫁いだわたくしも同じかしら？",
  ui_story_5053_50530901_38_dialog_content = "もちろん姉さんは別です！姉さんはソルラドの甘い言葉に騙されただけです。\n姉さんは被害者です！",
  ui_story_5053_50530901_39_dialog_content = "もし…仮にの話ですが、姉さんがソルラド家を離れたいなら、\n我が家はいつだって姉さんを喜んで迎えます。",
  ui_story_5053_50530901_40_dialog_content = "もし姉さんが白夜城は嫌だというなら、\n別の土地へ移住しても構いません！",
  ui_story_5053_50530901_41_dialog_content = "いいえ、カレブ。白夜城がこのまま腐っていくのを放っておくわけにはいかないわ。\n必ずわたくしが変えてみせる。",
  ui_story_5053_50530901_42_dialog_content = "…",
  ui_story_5053_50530901_43_dialog_content = "でも、あなたの言う通りよ。\nダニエルは救いようがない…完全に失望したわ。",
  ui_story_5053_50530901_44_dialog_content = "姉さん…！ようやく離縁する気になったのですか！？",
  ui_story_5053_50530901_45_dialog_content = "カレブ、あなたのように公然と城主に反対を唱える人は、\n今やそう多くはないわ。",
  ui_story_5053_50530901_46_dialog_content = "わたくしとあの男の教育は間違っていなかったようね。",
  ui_story_5053_50530901_47_dialog_content = "あの男…？父さんのことを言っているのですか？\n姉さん…なぜ急にそんな他人のような呼び方を…",
  ui_story_5053_50530901_48_dialog_content = "真実を教える時がきたようね。\n衛兵、やってしまいなさい。",
  ui_story_5053_50530901_49_dialog_content = "…",
  ui_story_5053_50530901_50_dialog_content = "うわぁ！い、痛いじゃないですか！\n何するんです？",
  ui_story_5053_50530901_51_dialog_content = "真実…？姉さん…ジャキーニさんに何を…？",
  ui_story_5053_50530901_52_dialog_content = "カレブ、<color=#FFB400>わたくしはあなたの実の姉ではないの</color>。",
  ui_story_5053_50530901_53_dialog_content = "あ…？",
  ui_story_5053_50530901_54_dialog_content = "何年も前、我が一族はソルラドの統治に異議を唱えたために、\n先代城主、つまりダニエルの父親に粛清された。",
  ui_story_5053_50530901_55_dialog_content = "その時の被害者には他にもいくつかの一族がいて、\n幼いわたくしとわずかな人たちだけが生き残った。",
  ui_story_5053_50530901_56_dialog_content = "わたくしたちはソルラド家を心底恨み、\n心を一つにして、それぞれ己の一族のために復讐を誓ったわ。",
  ui_story_5053_50530901_57_dialog_content = "そしてわたくしはある遺族の家庭に入り、\nソルラド家に殺された娘の身代わりとなって、アップタウンに移り住んだの。",
  ui_story_5053_50530901_58_dialog_content = "待ってください…遺族の家庭…？\n<color=#FFB400>ソルラド家に殺された娘</color>の身代わり…？",
  ui_story_5053_50530901_59_dialog_content = "ええ、それがあなたの姉さん「<color=#FFB400>ヨシュア</color>」よ。\nあなたの実の姉と母親はとうの昔に亡くなっているの。",
  ui_story_5053_50530901_60_dialog_content = "彼女たち自身はソルラド家に異を唱えたわけでもなく、\nその日たまたま粛清された家の友人を訪ねていただけだったというのに。",
  ui_story_5053_50530901_61_dialog_content = "…父さんは…父さんはこのことを知っていたのですか…？",
  ui_story_5053_50530901_62_dialog_content = "もちろんよ。身代わりはあの男が考えた計画だもの。",
  ui_story_5053_50530901_63_dialog_content = "ま、まさか…冗談ですよね？\nあの実直で真面目な父さんがそんなこと…",
  ui_story_5053_50530901_64_dialog_content = "恨みの力はとても大きいのよ、カレブ。",
  ui_story_5053_50530901_65_dialog_content = "わたくしたちが協力して、あなたを育てたのは「家族」だからではないわ。\n復讐を誓ったからよ。",
  ui_story_5053_50530901_66_dialog_content = "あなたの父親は暗殺に失敗し、自ら命を絶ち、あなたと私をまもった。\n復讐の火種を残すためにね。",
  ui_story_5053_50530901_67_dialog_content = "当時再三懇願してきたのに免じて、わたくしはダニエルに\nソルラド家を変えるチャンスを与えてあげたの。",
  ui_story_5053_50530901_68_dialog_content = "それだけでなく、彼を助けて選挙に勝たせ、\n新しい城主にしてあげたわ。",
  ui_story_5053_50530901_69_dialog_content = "わたくしは――彼の父親と違って、\n罪のない人まで手にかける殺りく者ではないもの。",
  ui_story_5053_50530901_70_dialog_content = "でも、あの時の選択は間違いだったわ。ダニエルの無能のせいですべてが無意味になってしまった。\nソルラドにわたくしたちの怒りを思い知らせる時が来たの。",
  ui_story_5053_50530901_71_dialog_content = "カレブ、<color=#FFB400>ジャキーニ</color>を殺しなさい。",
  ui_story_5053_50530901_72_dialog_content = "…何ですと？姉さん…今何と…？",
  ui_story_5053_50530901_73_dialog_content = "ここから出るには外から入って来た者の光力が必要なの。\nわたくしには外の世界で果たすべき使命がまだあるの。",
  ui_story_5053_50530901_74_dialog_content = "いけません…！姉さん、事情がどうあれ、ジャキーニさんとは無関係でしょう！？\n姉さんも罪のない人まで殺したくないと言ったではないですか！",
  ui_story_5053_50530901_75_dialog_content = "これは「必要な犠牲」よ。",
  ui_story_5053_50530901_76_dialog_content = "ちょっと…気がおかしくなったんですか！？\nあの優しいヨシュア夫人はどこに行ったんです？",
  ui_story_5053_50530901_77_dialog_content = "そんなの僕の方が聞きたいですよ…家族じゃない？絆などない？\n冗談じゃない…ジャキーニさん、この人は本当に幻影ではないのですか？",
  ui_story_5053_50530901_78_dialog_content = "幻影じゃありませんって！変身の占術もかけてませんよ！",
  ui_story_5053_50530901_79_dialog_content = "カレブ、真実を知っても、このまま見て見ぬふりをするつもり？\n…あなたの父親と母親、姉の犠牲を無駄にするの？",
  ui_story_5053_50530901_80_dialog_content = "…",
  ui_story_5053_50530901_81_dialog_content = "まあいいわ。教育がまだ足りなかったようね。\nジャキーニはわたくしが片付けましょう。",
  ui_story_5053_50530901_82_dialog_content = "ただし、この後その手でダニエルと他の人たちを片付けて、決意を示してもらうわ。\nそれが最後のチャンスよ。",
  ui_story_5053_50530901_83_dialog_content = "全員殺すつもりですって！？なんてことです！\n放してください、そうはさせませんよ！",
  ui_story_5053_50530901_84_dialog_content = "憎むならソルラド家を憎むのね。\nさようなら、北境の使者さん。",
  ui_story_5053_50530901_85_dialog_content = "<color=#e8d9bb>バッ――</color>",
  ui_story_5053_50530901_86_dialog_content = "…姉さん、あなたの言う通りです。今の姉さんはまるで他人のようですが、\n本能で分かるのです。あなたは僕の最愛の姉さんです。",
  ui_story_5053_50530901_87_dialog_content = "だから、僕は姉さんを止めます。\n後悔するようなことを姉さんにさせるわけにはいきません！",
  ui_story_5053_50530901_88_dialog_content = "後悔ですって？優しい姉を演じ、度胸のない父親に代わってあなたの面倒を見てきたのは、\nわたくしたちの意志を立派に引き継いでもらうためよ。",
  ui_story_5053_50530901_89_dialog_content = "うう…！",
  ui_story_5053_50530901_90_dialog_content = "それなのに、わたくしに背くとは…\nあなたまでわたくしに背くのね！！",
  ui_story_5053_50530901_91_dialog_content = "いいえ…僕は姉さんに背いたことなどありません。",
  ui_story_5053_50530901_92_dialog_content = "チッ、手がしびれるわ…こんな技を身に付けていたとは…\nまったく小賢しいわ！",
  ui_story_5053_50530901_93_dialog_content = "僕も本当の事を話しましょう。僕はずっと奴は姉さんにふさわしくないと言ってきました。\nでも本当は分かっていたのです…",
  ui_story_5053_50530901_94_dialog_content = "僕はただあなたの夫が、あなたの子どもたちが嫌いなだけだったのです！\n僕からたった一人の家族を奪った彼らが嫌いだっただけなのです！",
  ui_story_5053_50530901_95_dialog_content = "血はつながっていなかったとしても…\nここまで育ててくれたあなたを僕は心から愛しています！",
  ui_story_5053_50530901_96_dialog_content = "どんなに才能があっても、あなたはいつまでも姉離れのできない、\n大きな赤ん坊にすぎないのね！邪魔しないで！",
  ui_story_5053_50530901_97_dialog_content = "そうです！僕は今も子どものままです！\n笑いたければ笑えばいい！",
  ui_story_5053_50530901_98_dialog_content = "ですが…そんな僕でもあなたがどれだけ子どもたちと夫を愛しているかくらいは分かります。\n僕がどんなに頑張ってもその事実は変えられない！",
  ui_story_5053_50530901_99_dialog_content = "ただの家族ごっこだと言ったでしょう！",
  ui_story_5053_50530901_100_dialog_content = "フッ…姉さん、申し訳ありません。\n今度ばかりは信じられませんよ。",
  ui_story_5053_50530901_101_dialog_content = "あなたが苦しまないためにも、僕は絶対にあなたの大切な家族を守ります！\nたとえこの命を犠牲にしようとも守ってみせます！",
  ui_story_5053_50530901_102_dialog_content = "いいわ。では、あなたの命と光力をもらうことにするわ。",
  ui_story_5053_50530901_103_dialog_content = "え…！？",
  ui_story_5053_50530901_104_dialog_content = "ダメ…やめてください！カレブさん！！",
  ui_story_5053_50530901_105_dialog_content = "…あなたが自分で選んだのよ。",
  ui_story_5053_50530901_130_dialog_content = "カレブさん！！",
  ui_story_5053_50530901_131_dialog_content = "<color=#e8d9bb>ボンッ――</color>",
  ui_story_5053_50530901_132_dialog_content = "<size=45>ああああ――！</size>",
  ui_story_5053_50530901_133_dialog_content = "うっ！！",
  ui_story_5053_50530901_134_dialog_content = "うぐっ――！",
  ui_story_5053_50530901_135_dialog_content = "！？",
  ui_story_5053_50530901_136_dialog_content = "嫌になるわね。気色悪い怪物がこんな時に現れるなんて…！",
  ui_story_5053_50530901_138_dialog_content = "カレブさん、しっかりしてください！カレブさん！！",
  ui_story_5053_50530901_139_dialog_content = "カレ…ブ…！！",
  ui_story_5053_50530901_140_dialog_content = "うう…一突きで殺せたものを…\nやはり本気では殺せませんか…",
  ui_story_5053_50530901_141_dialog_content = "大変です…傷が深すぎます。血が止められません…",
  ui_story_5053_50530901_143_dialog_content = "暗いですね…何も見えません。",
  ui_story_5053_50530901_145_dialog_content = "だ…ダメ…",
  ui_story_5053_50530901_146_dialog_content = "姉さん…姉さんなのですか…？",
  ui_story_5053_50530901_147_dialog_content = "カレ…ブ…",
  ui_story_5053_50530901_148_dialog_content = "姉さんは…ここに…いるわ…",
  ui_story_5053_50530901_149_dialog_content = "ほ…本当に…？ゲホゲホッ！！",
  ui_story_5053_50530901_150_dialog_content = "姉さん…武器を置いたのですか…？",
  ui_story_5053_50530901_151_dialog_content = "良かった…",
  ui_story_5053_50530901_152_dialog_content = "…",
  ui_story_5053_50530901_153_dialog_content = "カレブさん！！カレブさん！！",
  ui_story_5053_50530901_155_dialog_content = "カレ…ブ…！！！！",
  ui_story_5053_50530901_156_dialog_content = "ダメ…逝っては…ダメよ…！！",
  ui_story_5053_50530901_157_dialog_content = "<size=50>いやああああああ！！！！</size>",
  ui_story_5053_50531001_1_dialog_content = "はぁ…はぁ…",
  ui_story_5053_50531001_2_dialog_content = "PlayerName、大丈夫？走れないなら、少し休みましょう。",
  ui_story_5053_50531001_3_dialog_content = "大丈夫だよ。「黒の天使」に追いつこうと焦っちゃって…\nそれにしても速いな！",
  ui_story_5053_50531001_4_dialog_content = "最初は僕たちと一緒のペースだったのに、\n突然何か感じたみたいに飛んでいっちゃった…",
  ui_story_5053_50531001_5_dialog_content = "実はさっき黒の天使が君を助けに行った時もあんな感じだったんだ。\nだから…ジャキーニたちが心配だよ。",
  ui_story_5053_50531001_6_dialog_content = "そうね。もうすぐ着くわ。無事だといいけど…",
  ui_story_5053_50531001_7_dialog_content = "ミヤ、ジャキーニは本当に2回目の時間の逆流以前のことを\nまったく覚えてなかったんだよね？",
  ui_story_5053_50531001_8_dialog_content = "ええ。私たちもジャキーニも覚えてなくて…\nだからみんな、あっちの「お母様」の話を信じたのよ。",
  ui_story_5053_50531001_9_dialog_content = "正直にいうと、PlayerNameの話を聞いた今でも、\nまだ信じられないでいるの…",
  ui_story_5053_50531001_10_dialog_content = "だからこの目で真実を確めなくちゃ…！",
  ui_story_5053_50531001_11_dialog_content = "（ジャキーニも覚えてないのに、どうして僕は覚えてるんだろう？\nこれっていったいどういう…）",
  ui_story_5053_50531001_12_dialog_content = "宮殿の様子がおかしいわ。\n門番の衛兵たちはどこへ行ったの？",
  ui_story_5053_50531001_13_dialog_content = "地面がかすかに揺れてる…ミヤ、気を付けて！",
  ui_story_5053_50531001_14_dialog_content = "！？",
  ui_story_5053_50531001_15_dialog_content = "ああ――！侵入者は、あらがう者は、殺せ――！",
  ui_story_5053_50531001_16_dialog_content = "ああああ――！！",
  ui_story_5053_50531001_17_dialog_content = "殺せ――！殺せ――！殺せ――！",
  ui_story_5053_50531001_18_dialog_content = "また狂気に犯されたあの衛兵たちだ！",
  ui_story_5053_50531001_19_dialog_content = "いやああああ！！助けてください！！",
  ui_story_5053_50531001_20_dialog_content = "あれは…ジャキーニ！？",
  ui_story_5053_50531001_21_dialog_content = "ジャキーニが衛兵たちに追われてる！\nミヤ、急いで突破しよう！",
  ui_story_5053_50531001_22_dialog_content = "人数が多すぎるわ！ヒポ…",
  ui_story_5053_50531001_23_dialog_content = "ヴェロニカ殿下、お任せを――！",
  ui_story_5053_50531001_24_dialog_content = "！？",
  ui_story_5053_50531001_25_dialog_content = "<color=#e8d9bb>ガシャン――</color>",
  ui_story_5053_50531001_26_dialog_content = "うう…！！",
  ui_story_5053_50531001_27_dialog_content = "ああああ！！",
  ui_story_5053_50531001_28_dialog_content = "（Ms.ブラン！？強い！まるでダンスでもしているかのように、\nあっという間に衛兵を倒しちゃった！）",
  ui_story_5053_50531001_29_dialog_content = "Ms.ロト！後ろ！",
  ui_story_5053_50531001_30_dialog_content = "ご心配には及びません、ヴェロニカ殿下。",
  ui_story_5053_50531001_31_dialog_content = "これは「ナイトガーディアン」の務めです。\n何人たりとも白夜城をみだりに荒らさせはしません。",
  ui_story_5053_50531001_32_dialog_content = "私がいるかぎり、白夜城の秩序を乱すことは許しません。",
  ui_story_5053_50531001_33_dialog_content = "「白夜に捧ぐ――」",
  ui_story_5053_50531001_34_dialog_content = "ううっ――！！",
  ui_story_5053_50531001_35_dialog_content = "うわああ！！",
  ui_story_5053_50531001_36_dialog_content = "ヴェロニカ殿下、ジャキーニ様、おケガはありませんか？",
  ui_story_5053_50531001_37_dialog_content = "ありません…私は大丈夫です。",
  ui_story_5053_50531001_38_dialog_content = "来てくれてありがとう。\n私たちだけだったら、あの人数を倒すのは難しかったわ。",
  ui_story_5053_50531001_39_dialog_content = "殿下、これはいったいどういうことでしょう？\n見たところ反乱軍ではないようですが？",
  ui_story_5053_50531001_40_dialog_content = "ち、違います。反乱軍じゃありません。今本当に大変なことになってるんです。\nこの人たちはみんなヨシュア夫人が…",
  ui_story_5053_50531001_41_dialog_content = "あら、わたくしがどうかしたのかしら？\nMs.ロト、ちょうどよい所に来てくれたわ。",
  ui_story_5053_50531001_42_dialog_content = "この招かれざる客たちはPlayerNameとジャキーニたちが企んだことなの。\nうまい言葉を使って、ロニーを惑わせたのよ。",
  ui_story_5053_50531001_43_dialog_content = "ヴェロニカはもうこの人たちの言いなり…救いようがないわ。\n母親として本当にがっかりしているの。",
  ui_story_5053_50531001_44_dialog_content = "こうとなっては仕方ないわ。\nMs.ロト、3人を片付けてちょうだい。",
  ui_story_5053_50531001_45_dialog_content = "…",
  ui_story_5053_50531001_46_dialog_content = "お母様、何をおっしゃるの！？\nやっぱりPlayerNameの言う通りだったのね…",
  ui_story_5053_50531001_47_dialog_content = "Ms.ロト、今目の前にいる「ヨシュア夫人」は本物ではありません！\n僕自身もまだよく分かってませんが…",
  ui_story_5053_50531001_48_dialog_content = "でも、信じてください。\n目の前にいるのはあなたの知ってるヨシュア夫人じゃないんです！",
  ui_story_5053_50531001_49_dialog_content = "私もソルラド家の名にかけて誓うわ。\nPlayerNameの言うことは本当よ。",
  ui_story_5053_50531001_50_dialog_content = "お母様のことは私が一番よく分かっているわ。\nお母様が今みたいなこと言うはずがないもの！",
  ui_story_5053_50531001_51_dialog_content = "…",
  ui_story_5053_50531001_52_dialog_content = "何を迷っているの？\nわたくしが昔教えたことを忘れてしまったのかしら？",
  ui_story_5053_50531001_53_dialog_content = "刃を持つ者は主の理想の実行者なの。\n理想と大義を貫くために、一切の代償を払わなければならないわ。",
  ui_story_5053_50531001_54_dialog_content = "白夜城の未来に余計な感情は障害でしかないわ。\nそんなものにあなたも未練はないでしょう？",
  ui_story_5053_50531001_55_dialog_content = "（どういうこと？Ms.ブランはヨシュア夫人の教え子だったの？）",
  ui_story_5053_50531001_56_dialog_content = "…その通りです。すべては「白夜城の未来」のためです。",
  ui_story_5053_50531001_57_dialog_content = "何をする気…！？",
  ui_story_5053_50531001_58_dialog_content = "すべての子どもたちが平等に笑顔になれる世界を実現するため、\nすべての障害物を取り除きます。たとえそれがあなたであっても。",
  ui_story_5053_50531001_59_dialog_content = "…",
  ui_story_5053_50531001_60_dialog_content = "さすがわたくしの教え子ね。\n師に刃を向けるとは、その勇気、褒めてあげるわ。",
  ui_story_5053_50531001_61_dialog_content = "いいでしょう。\nならば、あなたもこの人たちと一緒にここで消えなさい！",
  ui_story_5053_50531001_62_dialog_content = "<color=#e8d9bb>ガキン――</color>",
  ui_story_5053_50531001_63_dialog_content = "うっ――！？",
  ui_story_5053_50531001_64_dialog_content = "（これはまずいですね…先生の攻撃が速すぎます…！）",
  ui_story_5053_50531001_65_dialog_content = "Ms.ロト！？",
  ui_story_5053_50531001_66_dialog_content = "PlayerNameさん、\n急いでヴェロニカ殿下とジャキーニ様を連れてお逃げください！",
  ui_story_5053_50531001_67_dialog_content = "私では相手になるか分かりません。\n今すぐここから逃げてください！",
  ui_story_5053_50531001_68_dialog_content = "で、でも…",
  ui_story_5053_50531001_69_dialog_content = "余計なことは考えず、今最も重要なのはあなた方の命です！\n急いでください！",
  ui_story_5053_50531001_70_dialog_content = "…仕方ない…ミヤ、ジャキーニ、逃げよう！",
  ui_story_5053_50531001_71_dialog_content = "（Ms.ロト、どうか無事でいて…！）",
  ui_story_5053_50531002_1_dialog_content = "よいしょ！他にドアをふさぐものはある？",
  ui_story_5053_50531002_2_dialog_content = "いいえ、さっきの椅子が最後よ。",
  ui_story_5053_50531002_3_dialog_content = "あああ、おかしい！こんなのおかしいですよ！",
  ui_story_5053_50531002_4_dialog_content = "PlayerNameの言ったことが本当なら、\n時間はもう2回逆流してるってことですよね？",
  ui_story_5053_50531002_5_dialog_content = "1回目はみなさん手をつないでいて、私の手順も間違いありませんでした。\nだから、時間を戻す前の記憶をもっていた…",
  ui_story_5053_50531002_6_dialog_content = "2回目は私も一緒だったのに、\n私だけが記憶を失ってるんですね…",
  ui_story_5053_50531002_7_dialog_content = "そうなんだ。何が原因なんだろう？",
  ui_story_5053_50531002_8_dialog_content = "…原因はなんとなく分かります。",
  ui_story_5053_50531002_9_dialog_content = "「記憶の鏡晶」の中にある光力が残り少なくなったんです！",
  ui_story_5053_50531002_10_dialog_content = "えっ！？",
  ui_story_5053_50531002_11_dialog_content = "うーん…私たちも敵もどうやらやりすぎたみたいですね。",
  ui_story_5053_50531002_12_dialog_content = "残り少ない光力ではもう、「記憶の鏡晶」のすべての機能を\n維持することができなくなったんです。",
  ui_story_5053_50531002_13_dialog_content = "でも、なんでPlayerNameは全部覚えてるんでしょう？",
  ui_story_5053_50531002_14_dialog_content = "それから2人のヨシュア夫人も…考えれば考えるほど謎です。",
  ui_story_5053_50531002_15_dialog_content = "まさか宮殿にいる「ヨシュア夫人」は、\n別の人が夫人のふりをしてるんですか？",
  ui_story_5053_50531002_16_dialog_content = "私にもまったくわからないわ。\nでも、お父様はまだ広場でドラゴンと戦ってる…心配だわ…",
  ui_story_5053_50531002_17_dialog_content = "僕たちにはもういくつも選択肢が残されてるわけじゃない。\nもう一度時間をリセットしよう。",
  ui_story_5053_50531002_18_dialog_content = "ダメですって！私たちが記憶を失くしたら、\nあなた1人でヨシュア夫人とやり合うんですよ。危険すぎます！",
  ui_story_5053_50531002_19_dialog_content = "そうよ。もう一人の「お母様」が相手じゃ、\nひとりではムリだわ。",
  ui_story_5053_50531002_20_dialog_content = "ドアをふさいだので、時間は稼げるはずです。\n本で調べてみますね…",
  ui_story_5053_50531002_21_dialog_content = "「北境の占術は古代光霊の集落に源を発する」…\n古代光霊…古代光霊…",
  ui_story_5053_50531002_22_dialog_content = "あ、なるほど！この占術は光霊が光霊のために作ったんです。\nでも、PlayerNameは空の末裔です！",
  ui_story_5053_50531002_23_dialog_content = "もしかしたら種族の違いが原因かもしれませんよ？\nだって、この本には光霊以外の種族の使用に関する記載が一切ないですもん。",
  ui_story_5053_50531002_24_dialog_content = "そういうことだったのか…感知能力が大幅に弱まったのも、\nそのことと関係あるのかな？",
  ui_story_5053_50531002_25_dialog_content = "うーん…PlayerNameは啓光のゲームで遊んだことあります？",
  ui_story_5053_50531002_26_dialog_content = "ゲームを再起動すると「キャラ」は記憶をなくしますけど、\n「プレイヤー」は失くしませんよね？",
  ui_story_5053_50531002_27_dialog_content = "つまり、君の仮説でいえば、\n僕はゲームでいう「プレイヤー」ってこと？",
  ui_story_5053_50531002_28_dialog_content = "その通りです！\nあなたはルールの制限を受けないプレイヤーなんです！",
  ui_story_5053_50531002_29_dialog_content = "だからこそ、時間を戻す前にあなたが次はどう動くべきか、\nしっかり緻密な計画を立ててましょう。",
  ui_story_5053_50531002_30_dialog_content = "そうよ。今度もまた何の準備もなく時間を戻したら危険だわ。",
  ui_story_5053_50531002_31_dialog_content = "その通りだね…計画的に進めないと。",
  ui_story_5053_50531002_32_dialog_content = "今最も危険なのは「ヨシュア夫人」だ。",
  ui_story_5053_50531002_33_dialog_content = "でも、2人もヨシュア夫人がいるってどういうことだろう？\n今だによく分からないんだ。",
  ui_story_5053_50531002_34_dialog_content = "2人ともヨシュア夫人じゃごちゃ混ぜになっちゃいます。\n1人はもう「黒の天使」って呼んでることですし…",
  ui_story_5053_50531002_35_dialog_content = "もう1人は「白の悪魔」と呼びましょう！",
  ui_story_5053_50531002_37_dialog_content = "「白の悪魔」…お母様をそんな風に呼ぶのは気が引けるけど、\n確かに今のお母様にはふさわしい呼び名だわ。",
  ui_story_5053_50531002_38_dialog_content = "「白の悪魔」の行動と把握している情報からして、\n別人がお母様に扮してるってことはないと思うわ。",
  ui_story_5053_50531002_39_dialog_content = "「シード」はそれを埋め込まれた者の身体に別人格を生み出すの…\n私には理解できる気がするわ。",
  ui_story_5053_50531002_40_dialog_content = "私がバーバ・ヤーガと一つの心を共有しながら2つの顔を持つのと同じで、\nどちらがいいとか悪いとか決められないと思うの。",
  ui_story_5053_50531002_41_dialog_content = "バーバ・ヤーガは確かに時どき極端だけれど、\n決して悪い子じゃないわ。それはPlayerNameがよく分かってくれてるはずよ。",
  ui_story_5053_50531002_42_dialog_content = "だから、「黒の天使」と「白の悪魔」も同じなんじゃないかしら？",
  ui_story_5053_50531002_43_dialog_content = "だって「黒の天使」は確かに攻撃もしてきたけれど、\n広場では私たちを救ってくれたわ。",
  ui_story_5053_50531002_44_dialog_content = "もしかしたら制御が効かない時があるだけなのかもしれない。",
  ui_story_5053_50531002_45_dialog_content = "うーん…「黒の天使」はバーバ・ヤーガと似てるかもしれないけど、\n「白の悪魔」はミヤとはまったく違うよ。",
  ui_story_5053_50531002_46_dialog_content = "「白の悪魔」は心のない、ただの殺戮者だ。\nまさかヨシュア夫人にそんな一面があったっていうの？",
  ui_story_5053_50531002_47_dialog_content = "それは…私にも分からないわ。\nお母様はずっと心のきれいな優しい人で、殺りく者の一面なんてなかったわ…",
  ui_story_5053_50531002_48_dialog_content = "あの…ちょっと一言いいですか。",
  ui_story_5053_50531002_49_dialog_content = "それについては、ヨシュア夫人が自分で言ってたんです。\n昔は冷酷な殺りく者だったって…",
  ui_story_5053_50531002_50_dialog_content = "何年も前、我が一族はソルラドの統治に異議を唱えたために、\n先代城主、つまりダニエルの父親に粛清された。",
  ui_story_5053_50531002_51_dialog_content = "その時の被害者には他にもいくつかの一族がいて、\n幼いわたくしとわずかな人たちだけが生き残った。",
  ui_story_5053_50531002_52_dialog_content = "わたくしたちはソルラド家を心底恨み、\n心を一つにして、それぞれ己の一族のために復讐を誓ったわ。",
  ui_story_5053_50531002_53_dialog_content = "そしてわたくしはある遺族の家庭に入り、\nソルラド家に殺された娘の身代わりとなって、アップタウンに移り住んだの。",
  ui_story_5053_50531002_54_dialog_content = "えっ…！？そんなのあり得ないよ！\nヨシュア夫人は城主夫人だよ！？",
  ui_story_5053_50531002_55_dialog_content = "ウソをついたのかもしれない！",
  ui_story_5053_50531002_56_dialog_content = "私だって信じられませんよ…",
  ui_story_5053_50531002_57_dialog_content = "…",
  ui_story_5053_50531002_58_dialog_content = "ミヤだって信じないよね！？",
  ui_story_5053_50531002_59_dialog_content = "いいえ、実は私…その方が筋が通ると思うの。",
  ui_story_5053_50531002_60_dialog_content = "お母様は素晴らしい人よ。偉大な人だとさえ思ってる。",
  ui_story_5053_50531002_61_dialog_content = "白夜城城主夫人の地位にありながら、\n初心を忘れず、善良で理性ある心を保ち続けていたのだもの…",
  ui_story_5053_50531002_62_dialog_content = "家ではお父様と私たちの面倒を見て、\n外では城主夫人としての強さと揺るがぬ意志を示していたわ。",
  ui_story_5053_50531002_63_dialog_content = "名誉や富に目がくらむこともなく、\n決断すべき時にはいつだって自分を犠牲にすることを選んできた。",
  ui_story_5053_50531002_64_dialog_content = "普通の裕福な家庭に育ったお嬢様にできることじゃないわ。",
  ui_story_5053_50531002_65_dialog_content = "過去に悲しい経験をし、長い間自身に犠牲を強い、\n自我を抑えながら、他人に話して分かってもらうこともできない…",
  ui_story_5053_50531002_66_dialog_content = "お母様の苦しみは私の苦しみよりも\n何千倍も何万倍も大きかったんだわ。",
  ui_story_5053_50531002_67_dialog_content = "そんなお母様の心に深い憎しみに囚われた「白の悪魔」が\n住んでいても当然だと思うの。",
  ui_story_5053_50531002_68_dialog_content = "そういうことだったのか…",
  ui_story_5053_50531002_69_dialog_content = "ヨシュア夫人はすごいですね…\nそれに…かわいそうです。",
  ui_story_5053_50531002_70_dialog_content = "ただ、今の推測が本当だったとしたら、\nどうしてバーバ・ヤーガは私の体と分離してないのかしら？",
  ui_story_5053_50531002_71_dialog_content = "そうだね。そこは君とヨシュア夫人の違いだね。",
  ui_story_5053_50531002_72_dialog_content = "ミヤとバーバ・ヤーガは友だちで、\nバーバ・ヤーガはいつも君を守ってる。",
  ui_story_5053_50531002_73_dialog_content = "バーバ・ヤーガはもしかしたら、君がこの世界の中で\n分裂してしまわないように、あえて出てこないんじゃないかな？",
  ui_story_5053_50531002_74_dialog_content = "一方、ヨシュア夫人の場合は正反対で、\n2つの人格は対立してる。",
  ui_story_5053_50531002_75_dialog_content = "そ、そうだったのね。よかった…\n私が勝手にドレスを着替えちゃったから、怒ったのかと思ったわ。",
  ui_story_5053_50531002_76_dialog_content = "そんな思いやりを見せてくれるなんて、\n戻ったらきちんとお礼を言わなきゃ…",
  ui_story_5053_50531002_77_dialog_content = "とにかく、さっき「白の悪魔」が話してた事実から考えると――",
  ui_story_5053_50531002_78_dialog_content = "誰も傷つけずにここから出るためには、\n2人を一緒に連れ出さなきゃいけないってことになりますね。",
  ui_story_5053_50531002_79_dialog_content = "「白の悪魔」…今回こそウソついてませんよね…？",
  ui_story_5053_50531002_80_dialog_content = "ウソじゃないと思うよ。だって、初めて時間を戻す前の夫人の行動は\n夫人の話してくれた真実とつじつまが合うからね。",
  ui_story_5053_50531002_81_dialog_content = "ただ、まだ何か切り札を残してる可能性は\n考えておいた方がいいと思うけど…",
  ui_story_5053_50531002_82_dialog_content = "…",
  ui_story_5053_50531002_83_dialog_content = "ミヤ？",
  ui_story_5053_50531002_84_dialog_content = "今の状態のお母様がここから出たら、\n現実世界でどうなるのかって考えてたの…",
  ui_story_5053_50531002_85_dialog_content = "このまま深い悲しみと苦痛を抱えたまま生きていくのか…\nそれとも…暗鬼になってしまうの…？",
  ui_story_5053_50531002_86_dialog_content = "それは…いい方に考えようよ。",
  ui_story_5053_50531002_87_dialog_content = "少なくとも今はソルラドさんもカレブさんも、\nそれから僕とジャキーニだっているんだよ。",
  ui_story_5053_50531002_88_dialog_content = "皆で力を合わせれば、絶対に今よりもよくなるよ。",
  ui_story_5053_50531002_89_dialog_content = "そして、その始まりがこの世界から出ることなんだ！",
  ui_story_5053_50531002_90_dialog_content = "…うん、あなたの言う通りね！",
  ui_story_5053_50531002_91_dialog_content = "ただ、あの2人を同時に連れ出すのは至難の業ですね。\n「白の悪魔」が大人しくついてくるとは思えません。",
  ui_story_5053_50531002_92_dialog_content = "それにもう1人の自分のこと、気色悪いって言ってましたし、\n1つの身体になってくれそうもありません…",
  ui_story_5053_50531002_93_dialog_content = "そうだね。だから僕たち全員を殺そうとしてるんだよね。",
  ui_story_5053_50531002_94_dialog_content = "今考えられる最善の方法は\n力づくで連れ出すことしかないかもしれない。",
  ui_story_5053_50531002_95_dialog_content = "でも、そうだとしても、ドラゴンと衛兵たちが邪魔してくるし…",
  ui_story_5053_50531002_96_dialog_content = "ジャキーニ、どうしてドラゴンや衛兵たちが\n僕たちを襲ってきたのか分かる？",
  ui_story_5053_50531002_97_dialog_content = "うーん、どれどれ…あ、これです！\n「「記憶の鏡晶」を起動した者は中の世界に一定程度干渉できる」って書いてあります。",
  ui_story_5053_50531002_98_dialog_content = "ママったら、なんでぼやっとしか書いてないんでしょう！",
  ui_story_5053_50531002_99_dialog_content = "こうなったら、私の知識を使って考えるしかないですね。\nうーん…",
  ui_story_5053_50531002_100_dialog_content = "「記憶の鏡晶」は<color=#FFB400>鏡湖の水</color>と<color=#FFB400>起動した者の光力</color>を動力として、\n中の世界を構築してます。",
  ui_story_5053_50531002_101_dialog_content = "<color=#FFB400>起動した者の光力</color>は…ヨシュア夫人の光力ですよね！\nつまり、今見てる幻影はすべてヨシュア夫人の光力で作られてるんです。",
  ui_story_5053_50531002_102_dialog_content = "前に夫人が力をもっていかれた、みたいなこと言ってませんでした？",
  ui_story_5053_50531002_103_dialog_content = "ええ…",
  ui_story_5053_50531002_104_dialog_content = "それだけじゃないよ。皆の光力を吸収して、\nさらに強くなったって言ってた。",
  ui_story_5053_50531002_105_dialog_content = "分かりました！そういうことでしたか！",
  ui_story_5053_50531002_106_dialog_content = "「白の悪魔」の力は半分「黒の天使」に持っていかれたんです。",
  ui_story_5053_50531002_107_dialog_content = "あと半分はまだ残っていて、\n「記憶の鏡晶」の中の幻影を制御するのに使ってるのかもしれません！",
  ui_story_5053_50531002_108_dialog_content = "幻影はすべてヨシュア夫人の光力で出来てるんですから…",
  ui_story_5053_50531002_109_dialog_content = "自身の光力で干渉…いいえ、幻影を「動かす」ことができるんです！",
  ui_story_5053_50531002_110_dialog_content = "となると、「白の悪魔」はウソばかりを話してたってことになりますね！？\n私たち、うまくだまされちゃいましたよ！",
  ui_story_5053_50531002_111_dialog_content = "そんなことできるの？じゃあ、外で戦ってるMs.ロトは…",
  ui_story_5053_50531002_112_dialog_content = "…かなり危険かもしれませんね。",
  ui_story_5053_50531002_113_dialog_content = "恐ろしいわ。なんて緻密で残忍なのかしら…",
  ui_story_5053_50531002_114_dialog_content = "私はこれまでお母様に恐怖を感じたことなんてなかったわ。\nでも、もしあの優しさを失ったら、お母様は…",
  ui_story_5053_50531002_115_dialog_content = "そんな風に恐ろしい人になってしまうの？",
  ui_story_5053_50531002_116_dialog_content = "ドラゴンと狂気に陥った人たちは皆「白の悪魔」の駒だよね。\n彼らを倒して、白の悪魔の力を削ぐ以外に――",
  ui_story_5053_50531002_117_dialog_content = "僕たちが優位に立てる方法はないのかな…？\nあ、そうだ！",
  ui_story_5053_50531002_118_dialog_content = "今の「黒の天使」はソルラドさん以外の家族には悪意を持ってない。\nしかも「白の悪魔」が「黒の天使」を殺すことはできない。",
  ui_story_5053_50531002_119_dialog_content = "もし「黒の天使」を味方につけられるなら、\n勝算はだいぶ高くなるはずだよ。",
  ui_story_5053_50531002_120_dialog_content = "わ、大胆な発想ですね！そういうとこ好きですよ！",
  ui_story_5053_50531002_121_dialog_content = "ただ、PlayerName…これだけは言っておかなきゃいけません。",
  ui_story_5053_50531002_122_dialog_content = "今の「記憶の鏡晶」の光力じゃ、\n時間の逆流はあと1回が限度です。",
  ui_story_5053_50531002_123_dialog_content = "つまり、絶対に成功しなきゃいけないんです！",
  ui_story_5053_50531002_124_dialog_content = "絶対に…成功…分かった…",
  ui_story_5053_50531002_125_dialog_content = "PlayerName、もし時間が戻った後、追っ手を避けて、\n「白の悪魔」のことをすぐに皆に話したらどうかしら？",
  ui_story_5053_50531002_126_dialog_content = "わぁ…ミヤってPlayerNameより大胆なんですね。\nイメージ変わっちゃいました。",
  ui_story_5053_50531002_127_dialog_content = "そ、そうかしら？",
  ui_story_5053_50531002_128_dialog_content = "う―ん、僕もそれはリスクが高いと思うよ。",
  ui_story_5053_50531002_129_dialog_content = "僕には自分の身を守る力がない。\n「白の悪魔」にとって僕を消すことなんて簡単だよ。",
  ui_story_5053_50531002_130_dialog_content = "それに君たちには記憶がないんだ。\nそんな衝撃的な話、すぐには受け入れられないと思うよ。",
  ui_story_5053_50531002_131_dialog_content = "確かにそうね…特に叔父様は簡単には信じないでしょう。",
  ui_story_5053_50531002_132_dialog_content = "でも、みんなが信じるか信じないかは、\nあまり心配しなくても大丈夫だと思うわ。",
  ui_story_5053_50531002_133_dialog_content = "お父様はとても鋭い方よ。\n今回も最初に「白の悪魔」と話した時、何か疑ってらしたの。",
  ui_story_5053_50531002_134_dialog_content = "だから「白の悪魔」を見てるように叔父様を宮殿に残したんだわ。\n叔父様に真相を見極めてもらうためでもあったのかもしれない…",
  ui_story_5053_50531002_135_dialog_content = "だから、あなたは「黒の天使」にだけ気を付ければいいと思うわ。",
  ui_story_5053_50531002_136_dialog_content = "さすがソルラドさんだな…",
  ui_story_5053_50531002_137_dialog_content = "<color=#e8d9bb>ドンドンドン！！！</color>",
  ui_story_5053_50531002_138_dialog_content = "うわぁ、何の音です！？",
  ui_story_5053_50531002_139_dialog_content = "大変、衛兵が来たんだわ！",
  ui_story_5053_50531002_140_dialog_content = "私がドアをふさいでるから、ジャキーニは今のうちに時間を…",
  ui_story_5053_50531002_141_dialog_content = "<color=#e8d9bb>ボン！！</color>",
  ui_story_5053_50531002_142_dialog_content = "ミヤ！気を付けて！",
  ui_story_5053_50531002_143_dialog_content = "あれは！？",
  ui_story_5053_50531002_144_dialog_content = "…",
  ui_story_5053_50531002_145_dialog_content = "Ms.ロト…！？",
  ui_story_5053_50531002_146_dialog_content = "ミヤ、下がって！",
  ui_story_5053_50531002_147_dialog_content = "…いいえ。",
  ui_story_5053_50531002_148_dialog_content = "Ms.ロトはきっと苦しんでいるわ。\nカレンが理性で懸命に抵抗していたように…",
  ui_story_5053_50531002_149_dialog_content = "…今度こそ迷わない。\nカレンと同じ苦しみをあなたに味わせるわけにはいかないわ。",
  ui_story_5053_50531002_150_dialog_content = "私が苦しみから救ってあげる。",
  ui_story_5053_50531002_151_dialog_content = "行くわよ！",
  ui_story_5053_50531002_152_dialog_content = "――！",
  ui_story_5053_50531002_153_dialog_content = "ミヤ…",
  ui_story_5053_50531002_154_dialog_content = "ジャキーニ、ミヤが引き止めてくれてる間に…\n時間を戻そう。",
  ui_story_5053_50531002_155_dialog_content = "時間が戻って気が付いたら、まずは「黒の天使」を見つけて、\nそれから衛兵たちを避けて、で、その後は…",
  ui_story_5053_50531002_156_dialog_content = "PlayerName…手が震えてますね。",
  ui_story_5053_50531002_157_dialog_content = "…",
  ui_story_5053_50531002_158_dialog_content = "こんな重大な任務を1人で果たさなきゃなんですから、緊張して当たり前ですよね。\nでも、怖がることはありません。",
  ui_story_5053_50531002_159_dialog_content = "私は本気であなたを信じてますよ。\n絶対にうまくいきます！",
  ui_story_5053_50531002_160_dialog_content = "ジャキーニ…！",
  ui_story_5053_50531002_161_dialog_content = "ありがとう！必ず成功させてみせるよ！",
  ui_story_5053_50531002_162_dialog_content = "リタロ、リタロ、リタロ！時よ、起点へ戻れ。",
  ui_story_5053_50531002_163_dialog_content = "アブラカダブラ！",
  ui_story_5053_50531101_0X_dialog_content = "<color=#e8d9bb>――3回目の時間の逆流の後――</color>",
  ui_story_5053_50531101_1_dialog_content = "殿下、すべて準備が整いました。",
  ui_story_5053_50531101_2_dialog_content = "パレードの馬車が外で待機しております。\nいつでもご出発になれます。",
  ui_story_5053_50531101_3_dialog_content = "うむ、分かった。",
  ui_story_5053_50531101_4_dialog_content = "カレン、先に乗りなさい。",
  ui_story_5053_50531101_5_dialog_content = "か、カレンは…残ってお母様のそばにいます！",
  ui_story_5053_50531101_6_dialog_content = "ジャキーニ…ミヤ…僕が必ず…",
  ui_story_5053_50531101_7_dialog_content = "あれ…ここは…？",
  ui_story_5053_50531101_8_dialog_content = "あ、そうか！ジャキーニが時間を戻してくれたんだ！",
  ui_story_5053_50531101_9_dialog_content = "外では…こっちの世界のソルラドさんがカレンを連れて出かけようとしてる。",
  ui_story_5053_50531101_10_dialog_content = "間違いない。戻ってきたんだ！",
  ui_story_5053_50531101_11_dialog_content = "だったら、僕がまずやるべきことは…",
  ui_story_5053_50531101_12_dialog_content = "怪しい人物…夫人の命令…消さねば…",
  ui_story_5053_50531101_13_dialog_content = "怪しい人物…ここにはいない…",
  ui_story_5053_50531101_14_dialog_content = "ふぅ…最初の「追っ手を避ける」は無事クリアだね。",
  ui_story_5053_50531101_15_dialog_content = "（時間が戻る前にミヤとジャキーニと一緒に立てた計画に従えば、\n僕がやらなきゃいけないことは3つ）",
  ui_story_5053_50531101_16_dialog_content = "（1つは「黒の天使」を見つけて、僕たちに協力してもらえるよう説得する）",
  ui_story_5053_50531101_17_dialog_content = "（2つ目は、ドラゴンと狂気に犯された人たちの襲撃を阻止して、障害を取り除く）",
  ui_story_5053_50531101_18_dialog_content = "（3つ目、誰も犠牲にならないことを大前提に、「白の悪魔」を抑える）",
  ui_story_5053_50531101_19_dialog_content = "（ミヤ、ジャキーニ…）",
  ui_story_5053_50531101_20_dialog_content = "（これで最後だ。成功あるのみ、失敗は許されない…）",
  ui_story_5053_50531101_21_dialog_content = "怪しい人物…探して…消さねば…",
  ui_story_5053_50531101_22_dialog_content = "！！",
  ui_story_5053_50531101_23_dialog_content = "ここには…いない…",
  ui_story_5053_50531101_24_dialog_content = "（危なかった…前の経験からして、\n「白の悪魔」に操られた衛兵たちはずっと僕を探し続けるはず）",
  ui_story_5053_50531101_25_dialog_content = "（時間も能力も、できる行動も限られてる…\n3つ同時に進めなきゃダメだ）",
  ui_story_5053_50531101_26_dialog_content = "（賭けてみるしかない！）",
  ui_story_5053_50531102_1_dialog_content = "<color=#e8d9bb>ドッカーン――！！</color>",
  ui_story_5053_50531102_2_dialog_content = "うっ…ゴホッ…",
  ui_story_5053_50531102_3_dialog_content = "「黒の天使」はどこへ行ったの？",
  ui_story_5053_50531102_4_dialog_content = "外の道から逃げたみたいです。",
  ui_story_5053_50531102_5_dialog_content = "城主様の一撃、まさに天地を切り裂く勢いでしたね！",
  ui_story_5053_50531102_6_dialog_content = "とにかく、誰もケガをしてないなら…",
  ui_story_5053_50531102_7_dialog_content = "あら、みんなここにいたのね。",
  ui_story_5053_50531102_8_dialog_content = "お母様…どうしてここへ？パレードに行かれたのではなかったの？",
  ui_story_5053_50531102_9_dialog_content = "…",
  ui_story_5053_50531102_10_dialog_content = "…どうやら庭に招かれざる客が来ていたようね。",
  ui_story_5053_50531102_11_dialog_content = "ケガはないかしら？",
  ui_story_5053_50531102_12_dialog_content = "姉さん？でも、あの逃げた「黒の天使」は…",
  ui_story_5053_50531102_13_dialog_content = "ふふ、かわいい天才君もおかしなこと言う時があるのね。",
  ui_story_5053_50531102_14_dialog_content = "大丈夫よ。戦ったばかりできっと疲れているのね。\n中に入って休むといいわ。",
  ui_story_5053_50531102_15_dialog_content = "あの怪物は、わたくしが人を遣って追うことにしましょう。",
  ui_story_5053_50531102_16_dialog_content = "ちょっと待って、お母様。あの…おかしいわ…",
  ui_story_5053_50531102_17_dialog_content = "PlayerNameはどこかしら？",
  ui_story_5053_50531102_18_dialog_content = "あ、そうですね。PlayerNameはどこです？\nなんでいないんですか？",
  ui_story_5053_50531102_19_dialog_content = "初めからここにはいなかった。",
  ui_story_5053_50531102_20_dialog_content = "えっ…",
  ui_story_5053_50531102_21_dialog_content = "ごめんなさい、お母様。私たちまずはPlayerNameを探さなくては…\n危険な目に遭っているかもしれないわ…",
  ui_story_5053_50531102_22_dialog_content = "そうね。ヴェロニカは友だちを気遣える、とても優しい子ね。\nでも、みんなにはもっと大切なことを話さなければならないの。",
  ui_story_5053_50531102_23_dialog_content = "PlayerNameのことは、人を遣って探させるわ。\nだから、中に入ってくれる？",
  ui_story_5053_50531102_24_dialog_content = "え？ええ…わかった…",
  ui_story_5053_50531102_25_dialog_content = "…不思議なこともあるものだ。",
  ui_story_5053_50531102_26_dialog_content = "若者の生死安否が分からなくなっておるというに、\nさように落ち着いておるとは、お主らしくないな。",
  ui_story_5053_50531102_27_dialog_content = "あら？「ダニエル」はわたくしがそんなにか弱い女だと思っていたの？",
  ui_story_5053_50531102_28_dialog_content = "…",
  ui_story_5053_50531102_29_dialog_content = "ダニエルですと？姉さん、知っていたのですか…まさか！？",
  ui_story_5053_50531201_1_dialog_content = "はぁ…はぁ…",
  ui_story_5053_50531201_2_dialog_content = "さ、さっき…確かにここを曲がったのに…\nどうしていなくなっちゃんたんだろう？",
  ui_story_5053_50531201_3_dialog_content = "…憎い…ダニ…エル…",
  ui_story_5053_50531201_4_dialog_content = "いた！木箱の後ろだ！",
  ui_story_5053_50531201_5_dialog_content = "…！！",
  ui_story_5053_50531201_6_dialog_content = "ちょっと待って！戦うつもりで来たんじゃないんだ！\nカレブさんとミヤに危険が迫ってる。君の助けが必要なんだよ！",
  ui_story_5053_50531201_7_dialog_content = "カ…レブ…？ミヤ…？",
  ui_story_5053_50531201_8_dialog_content = "そうだよ。君の弟のカレブと娘のヴェロニカのことだ。",
  ui_story_5053_50531201_9_dialog_content = "2人とも君の大切な家族だよね？",
  ui_story_5053_50531201_10_dialog_content = "大切な…家族…",
  ui_story_5053_50531201_11_dialog_content = "君の家族が危ないんだ。君の力が必要なんだよ。",
  ui_story_5053_50531201_12_dialog_content = "家族が…危ない…",
  ui_story_5053_50531201_13_dialog_content = "どうしたの…？",
  ui_story_5053_50531201_14_dialog_content = "<size=50>…家族…ダニエル！！</size>",
  ui_story_5053_50531201_15_dialog_content = "え！？ちょ、ちょっと落ち着いて！\nそんな大きな声を出すと衛兵にみつかっちゃう！",
  ui_story_5053_50531201_16_dialog_content = "（前はカレブさんが危険だって聞いて「黒の天使」は助けに行ったのに、\nどうして今回はいらだち始めちゃったんだろう？）",
  ui_story_5053_50531201_17_dialog_content = "（まさか、家族のミヤが話しかけないと「黒の天使」を\n落ち着かせることはできないのかな？）",
  ui_story_5053_50531201_18_dialog_content = "痛い…！すごく痛い…！",
  ui_story_5053_50531201_19_dialog_content = "どうしよう…早く何とかしないと…\nどうしたらいいんだ！もう時間がないのに！",
  ui_story_5053_50531201_20_dialog_content = "泣かないで…",
  ui_story_5053_50531201_21_dialog_content = "ロニー…泣かないで…私のロニー…",
  ui_story_5053_50531201_22_dialog_content = "悲しむことはないわ…大丈夫よ…",
  ui_story_5053_50531201_23_dialog_content = "あ…",
  ui_story_5053_50531201_24_dialog_content = "（感知能力のない光霊が誰かを慰める時に使う方法なら、\n「黒の天使」にも効果があるかもしれない…）",
  ui_story_5053_50531201_25_dialog_content = "（試してみるしかないね！）",
  ui_story_5053_50531201_26_dialog_content = "薔薇を…一輪？かわいいあの子に贈りましょう…♪",
  ui_story_5053_50531201_27_dialog_content = "そよ風が…頬をなでる…\nあなたの笑顔は世界に一つだけ…♪",
  ui_story_5053_50531201_28_dialog_content = "…？",
  ui_story_5053_50531201_29_dialog_content = "…",
  ui_story_5053_50531201_30_dialog_content = "薔薇を…一輪？大切なパパとママに贈りましょう♪",
  ui_story_5053_50531201_31_dialog_content = "うるさいわ。",
  ui_story_5053_50531201_32_dialog_content = "すまぬ、あまりにも下手で耳障りだったか？",
  ui_story_5053_50531201_33_dialog_content = "街で偶然聞いたのだが、なかなかよい歌だったのでな。\n少し覚えていたのだ。",
  ui_story_5053_50531201_34_dialog_content = "旋律も歌詞も確かではない。許せ。",
  ui_story_5053_50531201_35_dialog_content = "ソルラド家の人間にダウンタウンの歌を歌う資格はないわ。",
  ui_story_5053_50531201_36_dialog_content = "…何ゆえ、それほどまでにソルラド家を憎むのか？",
  ui_story_5053_50531201_37_dialog_content = "己を偽り、犠牲にしてまでも余に近づき、恋仲となり――",
  ui_story_5053_50531201_38_dialog_content = "余を踏み台にして、父上を暗殺する――",
  ui_story_5053_50531201_39_dialog_content = "…",
  ui_story_5053_50531201_40_dialog_content = "お主の演技は完璧であった。戦闘能力も学識も極めて優れていた。",
  ui_story_5053_50531201_41_dialog_content = "いったいどれ程の時間と辛酸を耐え忍んで、\nそのような力を身に付けたのか余には想像もできぬ。",
  ui_story_5053_50531201_42_dialog_content = "5年か？10年か、それとも…これまでのすべての時間をかけてか？",
  ui_story_5053_50531201_43_dialog_content = "すべてはただ一人の暗殺のため、己の命をも懸けた暗殺のためにか。",
  ui_story_5053_50531201_44_dialog_content = "余の父は、お主やお主の後ろ盾となる者たちがそれほどまで恨む存在だったのか？",
  ui_story_5053_50531201_45_dialog_content = "もし誤解があったのならば、余は必ずやその誤解を晴らす。",
  ui_story_5053_50531201_46_dialog_content = "父の名誉のためだけではない。何より…\nお主がこのまま憎しみの中で生きていくのを見てはいられぬのだ。",
  ui_story_5053_50531201_47_dialog_content = "「ソルラド」は強権主義と暴政の化身よ。",
  ui_story_5053_50531201_48_dialog_content = "あなたたちが口にするもののすべてが、\nその身にまとうもののすべてが被害者たちの血と涙で出来ている。",
  ui_story_5053_50531201_49_dialog_content = "その「被害者」にはカレブの「実の姉」とお主の「本当の家族」も含まれるのか？",
  ui_story_5053_50531201_50_dialog_content = "…",
  ui_story_5053_50531201_51_dialog_content = "警戒することはない。推測にすぎぬ。",
  ui_story_5053_50531201_52_dialog_content = "7年前カレブの母親はある反逆者の追跡中に他界した。",
  ui_story_5053_50531201_53_dialog_content = "その時、現場には姉の「ヨシュア」もいた。",
  ui_story_5053_50531201_54_dialog_content = "だが、その姉は奇跡的に生き残った…いや、「不自然に生き残った」というべきか。",
  ui_story_5053_50531201_55_dialog_content = "そうして、今のお主、新たな「ヨシュア」が誕生した。\nそうであろう？",
  ui_story_5053_50531201_56_dialog_content = "…",
  ui_story_5053_50531201_57_dialog_content = "この推測を他言したことはないばかりか、\nお主が別の人間になりすましてここにいることを話したこともない。",
  ui_story_5053_50531201_58_dialog_content = "誰もがお主は家に戻ったと、\nお主の養父にも余はそう告げた。",
  ui_story_5053_50531201_59_dialog_content = "だが実際には家に戻ってはいなかった。\n養父もお主が失踪したことを誰にも話さなかった。",
  ui_story_5053_50531201_60_dialog_content = "明らかに、あいつはお主に帰る家がないことを知っていたからだ。",
  ui_story_5053_50531201_61_dialog_content = "…",
  ui_story_5053_50531201_62_dialog_content = "しかも奴自身逃げることなく、\n授業中余とお主がうまくやっているか探りを入れてきたものだ。",
  ui_story_5053_50531201_63_dialog_content = "君主殺しは大罪、極刑に処される。\nだが奴が気に掛けていたのは他でもなくお主の安否だったのだ。",
  ui_story_5053_50531201_64_dialog_content = "あの穏やかな学者は憎しみや恐れよりも\nお主のことを大切に思っていた。",
  ui_story_5053_50531201_65_dialog_content = "養父のためにも、我が父の暗殺はあきらめよ。",
  ui_story_5053_50531201_66_dialog_content = "お主があきらめるのならば、余もこれまでのことをすべて水に流し、\nお主を家族の元へ帰してやろう。",
  ui_story_5053_50531201_67_dialog_content = "情に訴えかけようとしても無駄よ。\nわたくしもあの男もそんなことどうでもいいの。",
  ui_story_5053_50531201_68_dialog_content = "わたくしたちは「ソルラド」への憎しみでつながった同志。\n理想のために犠牲になるのなら名誉だわ。",
  ui_story_5053_50531201_69_dialog_content = "おや、今のは何の証拠もない推測にすぎぬぞ。",
  ui_story_5053_50531201_70_dialog_content = "それをお主はカレブの父と手を組んできたことを認めおったな。",
  ui_story_5053_50531201_71_dialog_content = "ハハハ、この大局は余の勝ちだな！",
  ui_story_5053_50531201_72_dialog_content = "……",
  ui_story_5053_50531201_73_dialog_content = "オホン…つまらぬ戯言だ。\n張り詰めた空気を和らげようと思ったのだが…",
  ui_story_5053_50531201_74_dialog_content = "信用できないのはよく分かる。",
  ui_story_5053_50531201_75_dialog_content = "父上は何事においても厳しく徹底している。反逆者には一切の容赦もない。\n1人でも見逃すくらいならば…罪のない者まで巻き込むことをいとわぬ。",
  ui_story_5053_50531201_76_dialog_content = "そうすることで内は団結し、\n外には厳しく向かう空気を打ち立てられるのだと言っていた。",
  ui_story_5053_50531201_77_dialog_content = "誰もがソルラド家をあがめ、\nソルラド家は人々が従う唯一の指導者になるのだと。",
  ui_story_5053_50531201_78_dialog_content = "すべての者が唯一の正しき指導者を仰ぐ時、\n貪欲な利己主義者は存在しなくなると。",
  ui_story_5053_50531201_79_dialog_content = "あらゆる汚れを取り除けば、\n白夜城は当然この世で最も清らかで純粋な所になるのだと考えていたのだ。",
  ui_story_5053_50531201_80_dialog_content = "父上は偉大な理想を抱いておられた。\n余はそのような父を尊敬している。",
  ui_story_5053_50531201_81_dialog_content = "だが…その偉業は今だ道半ばにあり、\n父の理想も皆に受け入れられてはいないのだ。",
  ui_story_5053_50531201_82_dialog_content = "お主は気づいたろうか？我が家の者たちの表情に。",
  ui_story_5053_50531201_83_dialog_content = "余が宮殿にいる時は皆緊張した、こびるような顔をしている。",
  ui_story_5053_50531201_84_dialog_content = "だが余はかつて見たことがあるのだ。余のいない所では、\n皆笑顔を見せ、そしてその笑顔は本物の喜びの表情だった。",
  ui_story_5053_50531201_85_dialog_content = "だから父上に問うた。何ゆえ彼らはそうなのかと。",
  ui_story_5053_50531201_86_dialog_content = "その問いに対し、父上は彼らは汚れたこうかつな生き方に慣れてしまっているからだと答えた。",
  ui_story_5053_50531201_87_dialog_content = "だから、絶対的に正しいソルラド家の者を直視できないのだと。",
  ui_story_5053_50531201_88_dialog_content = "それは彼ら自身ではどうにもできない愚かさであり、\nだからこそ我々の導きが必要なのだとも言った。",
  ui_story_5053_50531201_89_dialog_content = "そのすべてを背負い、正していくことこそ、\nソルラド家の使命なのだ。",
  ui_story_5053_50531201_90_dialog_content = "…だが余はその息の詰まるような空気に耐えられなかった。",
  ui_story_5053_50531201_91_dialog_content = "ゆえによく壁を越えて、外に飛び出し、\n身分を隠して束の間の自由を楽しんでいたのだ。",
  ui_story_5053_50531201_92_dialog_content = "ヨシュア。ずっとお主だけは違うと思っていた。\nお主だけは余の前で共に心から笑ってくれると思っていた。",
  ui_story_5053_50531201_93_dialog_content = "だが結局、それもすべて思い込みにすぎなかったようだ…\n余はまだ何も分かっていなかったのだな。",
  ui_story_5053_50531201_94_dialog_content = "いい気味だわ。",
  ui_story_5053_50531201_95_dialog_content = "ハハハ…その通りだ。何しろ余は「ソルラド」だからな。",
  ui_story_5053_50531201_96_dialog_content = "ゆえに、お主の憎しみに正面から向き合わねばならん。",
  ui_story_5053_50531201_97_dialog_content = "この完璧とも言える暗殺計画は、\nわずか数人で成し得るものでは到底ない。",
  ui_story_5053_50531201_98_dialog_content = "他人になりすまし、長年の訓練を受け、\n関係者の協力を取り付ける…",
  ui_story_5053_50531201_99_dialog_content = "いったいどれ程の数の者が関われば、\nここまで完璧にできるであろう。",
  ui_story_5053_50531201_100_dialog_content = "「ソルラド」家がかけてきた圧力は欲望を消し去るに至らず、\nかえって己を無数の民の敵に仕立てあげてしまった。",
  ui_story_5053_50531201_101_dialog_content = "今の状況は父上が目指したものではない…",
  ui_story_5053_50531201_102_dialog_content = "自身の過ちに気付いたのなら、わざとらしくわたくしを\n取り込もうとはせずに父親と一緒に死ねばいいわ。",
  ui_story_5053_50531201_103_dialog_content = "過ちを犯したからといって死を選ぶのは、\nつぐないではない、ただの逃避だ。",
  ui_story_5053_50531201_104_dialog_content = "父上の理想はすべて正しいとは言えない。\nだが、父上の政には良き所もある。",
  ui_story_5053_50531201_105_dialog_content = "その最も顕著な証がまさにこの暗殺だ。",
  ui_story_5053_50531201_106_dialog_content = "…？",
  ui_story_5053_50531201_107_dialog_content = "かつて白夜城では、階級と血統がすべてであった。",
  ui_story_5053_50531201_108_dialog_content = "権力を持つ者は賄賂や汚職に染まり、法を定めようとも形骸化し、\n要職はすべて権勢のある一族たちで占められていた…",
  ui_story_5053_50531201_109_dialog_content = "だが、父の圧政下で、ダウンタウンの住民も\n正義を広める力を持つようになった。",
  ui_story_5053_50531201_110_dialog_content = "貴族らはおびえ、自ら罪を告白し、許しを求めるようになった。",
  ui_story_5053_50531201_111_dialog_content = "才能を有する者は階級を越え、試験により、\n能力に見合った正しい評価を受けられるようになった。",
  ui_story_5053_50531201_112_dialog_content = "それが父上の目指したものだ。\n出身を問わず、能力と努力によって評価する世の中だ。",
  ui_story_5053_50531201_113_dialog_content = "平民出身の学者であるカレブの父が典型的な例であろう？",
  ui_story_5053_50531201_114_dialog_content = "余の申したことに偽りはない。でなければ、富もなく、\n貴族でもない彼がその才覚だけでアップタウンに来られるはずがない。",
  ui_story_5053_50531201_115_dialog_content = "家庭教師の娘であるお主が余に近づけることもなかったはずだ。",
  ui_story_5053_50531201_116_dialog_content = "暗殺計画を立てた者はその点を確信していたからこそ、\nこれを前提条件としたのだ。",
  ui_story_5053_50531201_117_dialog_content = "…",
  ui_story_5053_50531201_118_dialog_content = "答えてくれ。父の政のいったいどこに不足があったのだ？",
  ui_story_5053_50531201_119_dialog_content = "ダウンタウンがいまだに闇の勢力に牛耳られているからか？\nそれとも徹底した粛清がいくつものえん罪を生み出したからか？",
  ui_story_5053_50531201_120_dialog_content = "もしそうであるならば、余が必ず徹底的に調べよう。",
  ui_story_5053_50531201_121_dialog_content = "今さらそのようなことをしても、\nお主の傷や痛みを癒すことはできぬであろうが…",
  ui_story_5053_50531201_122_dialog_content = "その他の多くの者たちのために、\n過ちは直ちに正さなければならない。",
  ui_story_5053_50531201_123_dialog_content = "…やはり、あなたは何も分かっていないのね。",
  ui_story_5053_50531201_124_dialog_content = "民が必要としているのは、正しい政ではなく、\n真の自由なのよ。",
  ui_story_5053_50531201_125_dialog_content = "真の…自由、と？",
  ui_story_5053_50531201_126_dialog_content = "自身で生き方を選ぶことができ、\n貴せんのレッテルを張られることもない。",
  ui_story_5053_50531201_127_dialog_content = "喜びも憎しみもありのままの気持ちを吐露することができ、\nだからといって自身や家族の安全が脅かされることもない。",
  ui_story_5053_50531201_128_dialog_content = "それこそ自由よ。",
  ui_story_5053_50531201_129_dialog_content = "使用人たちがあなたにおびえていたのは、\nため息一つをとっても時機を間違えば、家族全員の命が危険にさらされるから。",
  ui_story_5053_50531201_130_dialog_content = "身分を問わず、能力と努力だけで評価される？\n笑わせないで！",
  ui_story_5053_50531201_131_dialog_content = "「ソルラド」家の望みはあなたたちの顔色を見て生きる、\n家畜のような民を育てることでしょう！？",
  ui_story_5053_50531201_132_dialog_content = "…",
  ui_story_5053_50531201_133_dialog_content = "…",
  ui_story_5053_50531201_134_dialog_content = "そのために我が父を殺し、「ソルラド」を滅ぼすのか。",
  ui_story_5053_50531201_135_dialog_content = "「ソルラド」の消えた世界で、\n真に自由な暮らしを送るというのか？",
  ui_story_5053_50531201_136_dialog_content = "「ヨシュア」、それがお主の望む幸せなのか？",
  ui_story_5053_50531201_137_dialog_content = "幸せなど望んでいないわ。",
  ui_story_5053_50531201_138_dialog_content = "暗殺を完遂した時、わたくしの命も終わる。",
  ui_story_5053_50531201_139_dialog_content = "つまり、成功如何に関わらず、お主は死を選ぶというのか？",
  ui_story_5053_50531201_140_dialog_content = "仲間を守るためにか？",
  ui_story_5053_50531201_141_dialog_content = "いいえ。使命を果たしたからには\nおめおめと生きている理由などないからよ。",
  ui_story_5053_50531201_142_dialog_content = "生きている…理由がないと…？",
  ui_story_5053_50531201_143_dialog_content = "貴族が自身の利益のためだけに動くように、\nわたくしたちも理想のためだけに生きるの。",
  ui_story_5053_50531201_144_dialog_content = "富も名誉もいらない。すべては新たな星が天に輝き、\nすべての人々を照らす日を迎えるためなのよ。",
  ui_story_5053_50531201_145_dialog_content = "そしてわたくしたちは自身の命を燃やし、古くなった太陽を落とすために生きているだけよ。\nあなたたちの陳腐な功利主義でわたくしたちを量らないでちょうだい。",
  ui_story_5053_50531201_146_dialog_content = "ああ。お主と話ができることをうれしく思うが、\n何ゆえこのような答えのない難しい話ばかりをせねばならぬのか。",
  ui_story_5053_50531201_147_dialog_content = "お主はいつもこのようなことばかりを考えていたのか…？",
  ui_story_5053_50531201_148_dialog_content = "お主の言う「古くなった太陽」が我が父だと言うのなら…\n「新たな星」はいったい誰のことだ？",
  ui_story_5053_50531201_149_dialog_content = "すべてはお主の背後にいる組織の者が我が父に代わって\n新たな統治者になるためだというのか？",
  ui_story_5053_50531201_150_dialog_content = "…",
  ui_story_5053_50531201_151_dialog_content = "…受け入れがたい。",
  ui_story_5053_50531201_152_dialog_content = "仲間や家族のために敵と共に自らも犠牲になるのなら理解できる。\nだが「おめおめと生きている理由などない」とはどういうことか？",
  ui_story_5053_50531201_153_dialog_content = "お主を奪われ、余に盾突く弟や――",
  ui_story_5053_50531201_154_dialog_content = "お主の安否を心配し、お主の帰りを待つ父親は――",
  ui_story_5053_50531201_155_dialog_content = "生きていく理由にならないと申すのか…？",
  ui_story_5053_50531201_156_dialog_content = "ソルラド家が皆の自由を奪ったと考えているのなら、\n「ソルラド」を見事滅ぼした後、自由に生きればよいではないか！",
  ui_story_5053_50531201_157_dialog_content = "それが何ゆえ「ソルラド」なき後、お主は自由を得られぬ？",
  ui_story_5053_50531201_158_dialog_content = "我が父が突如病死しても、お主は己の命を絶つというのか！？",
  ui_story_5053_50531201_159_dialog_content = "さっき確かめたでしょう？わたくしとあの男、\nそしてあの男の息子とは偽の家族にすぎない。",
  ui_story_5053_50531201_160_dialog_content = "「ソルラド」の統治を終わらせるための武器でしかないのよ。",
  ui_story_5053_50531201_161_dialog_content = "「ソルラド」が消えれば、わたくしに存在価値はなくなるの。\n自由は民のためにあるの、わたくしとは関係ないわ。",
  ui_story_5053_50531201_162_dialog_content = "…偽りだ。",
  ui_story_5053_50531201_163_dialog_content = "「新たな星」とやらは自由とは何か、愛とは何かを教えてはくれなかったようだな。",
  ui_story_5053_50531201_164_dialog_content = "そのような有様で如何にして多くの民に自由と愛をもたらすというのだ？",
  ui_story_5053_50531201_165_dialog_content = "…",
  ui_story_5053_50531201_166_dialog_content = "…分かった。",
  ui_story_5053_50531201_167_dialog_content = "余はお主の世界を知らぬ。\nゆえに圧政に対する恨みつらみを知る由もない。",
  ui_story_5053_50531201_168_dialog_content = "お主も余の世界を知らぬ。\nゆえに愛と自由がどのようなものか理解できぬ。",
  ui_story_5053_50531201_169_dialog_content = "それは我々の間にある越えられぬ溝だ。",
  ui_story_5053_50531201_170_dialog_content = "その通りよ。だから、あきらめ…",
  ui_story_5053_50531201_171_dialog_content = "だからこそ力を合わせねばならぬ。\n互いの不足を補い合わなければならぬのだ。",
  ui_story_5053_50531201_172_dialog_content = "バカなこと言わないで。",
  ui_story_5053_50531201_173_dialog_content = "余もお主も我が父も、その「新たな星」とやらも…",
  ui_story_5053_50531201_174_dialog_content = "己の目と心だけであらゆる者の望みを思い計るのは、\n無理なのやもしれぬ。",
  ui_story_5053_50531201_175_dialog_content = "だが互いに先入観を捨て、共に努力することはできる。",
  ui_story_5053_50531201_176_dialog_content = "そして、すべての者の声が届く、真に自由な世を創るのだ。",
  ui_story_5053_50531201_177_dialog_content = "それこそお主の理想であろう？",
  ui_story_5053_50531201_178_dialog_content = "…",
  ui_story_5053_50531201_179_dialog_content = "お主を止めたあの日から、ずっと考えていた。",
  ui_story_5053_50531201_180_dialog_content = "己の夢を他者に託すのは、間違った選択ではないのか。",
  ui_story_5053_50531201_181_dialog_content = "ただ父の理想に従うことも、死を持って「新たな星」に道を拓いてやることも――",
  ui_story_5053_50531201_182_dialog_content = "運命を自分の手に握る以上に現実的な術は他にないのではないか？",
  ui_story_5053_50531201_183_dialog_content = "余も今はまだ何も分からず迷っておる。",
  ui_story_5053_50531201_184_dialog_content = "だが、これだけは分かるのだ。\nお主と共にあるのなら、すべてが変わっていくだろう。",
  ui_story_5053_50531201_185_dialog_content = "お主がいれば――",
  ui_story_5053_50531201_186_dialog_content = "余はより広く物事を見ることが出来るようになるだろう。\nアップタウンの外にどのような世界が広がっているのか知ることができる。",
  ui_story_5053_50531201_187_dialog_content = "されば父の政のどこに問題があったのかも見えてくるであろう。",
  ui_story_5053_50531201_188_dialog_content = "そして余もお主に生きるとはどういうことか分からせてやれる。\nお主が心から笑えるようにしてやる。",
  ui_story_5053_50531201_189_dialog_content = "その笑顔をさらに多くの者へとお主が伝えていけばよいのだ！",
  ui_story_5053_50531201_190_dialog_content = "…くだらないわ。",
  ui_story_5053_50531201_191_dialog_content = "宮廷にはあなたのオママゴトに付き合ってくれる人がたくさんいるでしょう？\nわたくしでなくてもいいはずよ。",
  ui_story_5053_50531201_192_dialog_content = "うむ…だが…",
  ui_story_5053_50531201_193_dialog_content = "我が父に逆らおうとする者は少ない。\nしかもアップタウンの者はおおかた外の世界を理解することはできぬだろう…",
  ui_story_5053_50531201_194_dialog_content = "それに…コホン。初めてお主に会った時と同様――",
  ui_story_5053_50531201_195_dialog_content = "一目ぼれしたのだ。",
  ui_story_5053_50531201_196_dialog_content = "…",
  ui_story_5053_50531201_197_dialog_content = "（「黒の天使」がじっとして動かない…\n落ち着いたってことなのかな…？）",
  ui_story_5053_50531201_198_dialog_content = "あの…落ち着いて話を聞けるようになりましたか？",
  ui_story_5053_50531201_199_dialog_content = "あの「白の悪魔」…つまりもう一人のあなたですが、\nカレブさんとミヤを殺そうとしてるんです。",
  ui_story_5053_50531201_200_dialog_content = "あなたの助けが…",
  ui_story_5053_50531201_201_dialog_content = "ダニ…エル…",
  ui_story_5053_50531201_202_dialog_content = "えっ？",
  ui_story_5053_50531201_203_dialog_content = "ダニエル…なぜ…裏切ったの…！？",
  ui_story_5053_50531201_204_dialog_content = "<size=45>ダニエル！！</size>",
  ui_story_5053_50531201_205_dialog_content = "どうしたっていうんだ！？今度はもっと狂暴になっちゃったよ！\n僕はソルラドさんじゃありません、しっかりしてください！",
  ui_story_5053_50531201_206_dialog_content = "<size=45>ダニエル！ダニエル！</size>",
  ui_story_5053_50531201_207_dialog_content = "（もう時間がない！少なくとも注意を引くことには成功したし、\nまずは中央広場まで誘い出そう！）",
  ui_story_5053_50531201_208_dialog_content = "<size=45>ダニエル――</size>",
  ui_story_5053_50531301_1_dialog_content = "白夜城じゅうの民が会し、今日という特別な日を共に祝ってくれることに感謝する。",
  ui_story_5053_50531301_2_dialog_content = "ソルラド家は白夜城の主の冠を戴く者であり、同時にまた使命を託された一族でもある。",
  ui_story_5053_50531301_3_dialog_content = "我らはこの手で人々を守り続けよう。\nだが、民を守るために我らが握る剣は皆から託されたもの。",
  ui_story_5053_50531301_4_dialog_content = "今日ここで「ソルラド」家の美徳と白夜城の民の美徳を讃えよう。",
  ui_story_5053_50531301_5_dialog_content = "「ソルラド家記念日」の式典開催を宣言する！",
  ui_story_5053_50531301_6_dialog_content = "式典が予定通り始まった。\nどうやら黒の天使は壇上に姿を現していないようだな。",
  ui_story_5053_50531301_7_dialog_content = "障害を…排除する…",
  ui_story_5053_50531301_8_dialog_content = "ならば、この兵士たちはどういうことだ？",
  ui_story_5053_50531301_9_dialog_content = "理論上、記憶の鏡晶の中の者たちは\n光力で作られた幻影にすぎぬ。",
  ui_story_5053_50531301_10_dialog_content = "それが何ゆえ突然理性を失い、\n言葉の通じぬ操り人形となってしまうのか…",
  ui_story_5053_50531301_11_dialog_content = "では、作戦通り私は上に行きます。\n「黒の天使」を見つけ次第、お知らせします。",
  ui_story_5053_50531301_12_dialog_content = "十分に気を付けよ、ミヤ。",
  ui_story_5053_50531301_13_dialog_content = "（ミヤはひとまず心配あるまい。\nだが、PlayerNameはどこへ行った？）",
  ui_story_5053_50531301_14_dialog_content = "むむ？",
  ui_story_5053_50531301_15_dialog_content = "PlayerName…",
  ui_story_5053_50531301_16_dialog_content = "PlayerNameを…探す…",
  ui_story_5053_50531301_17_dialog_content = "待て。お主らのいで立ち、\nよもやカルティマ家の騎士ではあるまいな。",
  ui_story_5053_50531301_18_dialog_content = "式典の間、街を守るのがカルティマの務めであったはずだ。\nそれが何ゆえこのような所をうろついておる？",
  ui_story_5053_50531301_19_dialog_content = "（兵士らの足下がふらついている。\n何かブツブツと言っているが、酒にでも酔っておるのか？）",
  ui_story_5053_50531301_20_dialog_content = "（しかも何ゆえPlayerNameの名が出て来た？）",
  ui_story_5053_50531301_21_dialog_content = "PlayerNameを…探す…",
  ui_story_5053_50531301_22_dialog_content = "PlayerNameを…消す…",
  ui_story_5053_50531301_23_dialog_content = "今の言葉は聞き捨てならぬ。",
  ui_story_5053_50531301_24_dialog_content = "事の次第を聞かせてもらおうではないか。",
  ui_story_5053_50531301_25_dialog_content = "障害を…排除する…！",
  ui_story_5053_50531301_26_dialog_content = "黒幕を聞き出すどころか、通常の会話も成り立たないとは。\nこの兵士らはいったいどうなっているのだ？",
  ui_story_5053_50531301_27_dialog_content = "（時間を戻せば、「記憶の鏡晶」の中にPlayerNameを知る者はいないはずだ）",
  ui_story_5053_50531301_28_dialog_content = "（PlayerNameに恨みを持つことはおろか、\nその存在を知る者でさえわずかなはずだ）",
  ui_story_5053_50531301_29_dialog_content = "あなたがわざわざ行くことはないわ。\n衛兵に探させても同じよ。",
  ui_story_5053_50531301_30_dialog_content = "でも、あの怪物は全員が力を合わせなければ、\n勝てる可能性は低いわ。",
  ui_story_5053_50531301_31_dialog_content = "どちらの方が重要か、あなたなら判断がつくはずよ。\n冷静にならなくては。",
  ui_story_5053_50531301_32_dialog_content = "（…我々以外にPlayerNameの存在を知っているのは、\nヨシュアたった一人…）",
  ui_story_5053_50531301_33_dialog_content = "（そしてまた、我々以外で「記憶の鏡晶」の中にいる、\n唯一の生きた光霊だ）",
  ui_story_5053_50531301_34_dialog_content = "（だが、お主はいったいいかなる理由で、\n何の関係もない若者を殺そうとしているのだ？）",
  ui_story_5053_50531301_35_dialog_content = "（幸いカレブをヨシュアの元に残してきた）",
  ui_story_5053_50531301_36_dialog_content = "（頭の回転の速いカレブのことだ。余の代わりにすべてを見極めてくれるであろう。\n喜びのあまり冷静さを失わぬことを願うばかりだ）",
  ui_story_5053_50531301_37_dialog_content = "はぁ…はぁ…ソルラドさん！よかった、ここにいたんですね！",
  ui_story_5053_50531301_38_dialog_content = "PlayerName…？",
  ui_story_5053_50531301_39_dialog_content = "ああああ―――！！！",
  ui_story_5053_50531301_40_dialog_content = "PlayerName、伏せよ！",
  ui_story_5053_50531301_41_dialog_content = "「黒の天使」のことは気にしないでください！\n早く壇上へ！ミヤが危険です！",
  ui_story_5053_50531301_42_dialog_content = "どういう意味だ？",
  ui_story_5053_50531301_43_dialog_content = "信じてください！早く壇上へ！！",
  ui_story_5053_50531301_44_dialog_content = "よかろう…",
  ui_story_5053_50531301_45_dialog_content = "え！？な、何するんですか！？",
  ui_story_5053_50531301_46_dialog_content = "動くでない。お主を壇上に連れて行く。",
  ui_story_5053_50531301_47_dialog_content = "！？",
  ui_story_5053_50531301_48_dialog_content = "ダニ…エル…？ダニエル！！",
  ui_story_5053_50531301_49_dialog_content = "ちょっと！押さないでよ！",
  ui_story_5053_50531301_50_dialog_content = "な、何事だ？",
  ui_story_5053_50531301_51_dialog_content = "怪物だ！怪物が出たぞ！！",
  ui_story_5053_50531301_52_dialog_content = "下が騒がしいようだが、何事だ？",
  ui_story_5053_50531301_53_dialog_content = "<size=30>あれは…お父様とPlayerName…\nそれから「黒の天使」だわ…</size>",
  ui_story_5053_50531301_54_dialog_content = "ヴェロニカ、何か申したか？",
  ui_story_5053_50531301_55_dialog_content = "いいえ、何でもありません…",
  ui_story_5053_50531301_56_dialog_content = "人混みを抜けてこちらへ向かってくるぞ！",
  ui_story_5053_50531301_57_dialog_content = "護衛兵、さっさと止めぬか！！",
  ui_story_5053_50531301_58_dialog_content = "（黒の天使は本当にお父様を狙ってきたわ。お母様の言った通り…）",
  ui_story_5053_50531301_59_dialog_content = "（どうして壇上に向かってくるのかは分からないけど、\nお父様を守らなくては！）",
  ui_story_5053_50531301_60_dialog_content = "（お願い、力よ、どうか言うことを聞いて…！）",
  ui_story_5053_50531301_61_dialog_content = "お姉様、いったい何事なの？\n広場を横切ってこちらに向かってくる人たちは誰なの？",
  ui_story_5053_50531301_62_dialog_content = "な、何でもないわ。カレンは動き回らずに近くにいるのよ。",
  ui_story_5053_50531301_63_dialog_content = "先頭を走っている男は何者か？",
  ui_story_5053_50531301_64_dialog_content = "人一人抱えていながら、いともたやすく衛兵をかわしておるぞ。",
  ui_story_5053_50531301_65_dialog_content = "あの姿、まるで…",
  ui_story_5053_50531301_66_dialog_content = "おい、あの老いぼれめ、転ばせた兵士を踏み台に…\n壇上へ向かって飛びあがったぞ！！",
  ui_story_5053_50531301_67_dialog_content = "護衛兵、皆を保護せよ。\n曲者どもは余が相手する。",
  ui_story_5053_50531301_68_dialog_content = "…",
  ui_story_5053_50531301_69_dialog_content = "何者か？",
  ui_story_5053_50531301_70_dialog_content = "PlayerName、お主のいう危険はどこだ？",
  ui_story_5053_50531301_71_dialog_content = "お主、余の問いに答えよ！",
  ui_story_5053_50531301_72_dialog_content = "空です。もうすぐ飛んできます！",
  ui_story_5053_50531301_73_dialog_content = "あの怪物は何だ！？護衛兵！護衛兵はどこだ！私を守らぬか！",
  ui_story_5053_50531301_74_dialog_content = "ダニ…エル？ダニエル…？ダニエル…",
  ui_story_5053_50531301_75_dialog_content = "ああああ――ダニエル――！！！",
  ui_story_5053_50531301_76_dialog_content = "お父様を傷つける者は私が許さない！",
  ui_story_5053_50531301_77_dialog_content = "…来ました！ドラゴンです！！",
  ui_story_5053_50531301_78_dialog_content = "<size=50>グオォ――！！</size>",
  ui_story_5053_50531301_79_dialog_content = "龍…ドラゴンか？",
  ui_story_5053_50531301_80_dialog_content = "カルティマ家の血に刻まれた契約…\nだが、何ゆえ今現れた？",
  ui_story_5053_50531301_81_dialog_content = "若者よ、今は余計なことを考えている暇はない。\n目の前の危険に集中せよ。",
  ui_story_5053_50531301_82_dialog_content = "カルティマの逆賊め。お主に指図される筋合いはない！",
  ui_story_5053_50531301_83_dialog_content = "集中するのだ！敵が誰か正しく見極めよ！\n来るぞ！",
  ui_story_5053_50531301_84_dialog_content = "…",
  ui_story_5053_50531301_85_dialog_content = "ド、ドラゴン…！ドラゴンが現れるのは\n確かもっと後のはずじゃ…",
  ui_story_5053_50531301_86_dialog_content = "お姉様、大丈夫よ！カレンが守ってあげる！",
  ui_story_5053_50531301_87_dialog_content = "これは…反乱が早まったんだわ。\nカレン、早くどこかに身を隠して！",
  ui_story_5053_50531301_88_dialog_content = "カ…レン…？ヴェロ…ニカ…？",
  ui_story_5053_50531301_89_dialog_content = "グォォ！！！！！",
  ui_story_5053_50531301_90_dialog_content = "ドラゴンが攻撃してきます！！",
  ui_story_5053_50531301_91_dialog_content = "――――！！",
  ui_story_5053_50531301_92_dialog_content = "いったいどこから現れたのかしら！？",
  ui_story_5053_50531301_93_dialog_content = "わあああ～、パパ！パパ！怖いよ…",
  ui_story_5053_50531301_94_dialog_content = "火を噴いたぞ！早く逃げろ！！",
  ui_story_5053_50531301_95_dialog_content = "息子は？あの子はどこに行ったんだ！？",
  ui_story_5053_50531301_96_dialog_content = "…",
  ui_story_5053_50531301_97_dialog_content = "兵隊さん、小さな男の子を見ませんでしたか？\nこれくらいの背丈の…",
  ui_story_5053_50531301_98_dialog_content = "…増やす…そして奴らを…消す…",
  ui_story_5053_50531301_99_dialog_content = "え？何か言いましたか？",
  ui_story_5053_50531301_100_dialog_content = "仲間を…増やす…そして…奴らを消す…",
  ui_story_5053_50531301_101_dialog_content = "うぐっ！？な、何をするんです…",
  ui_story_5053_50531301_102_dialog_content = "仲間を…増やす…そして…奴らを消す…",
  ui_story_5053_50531301_103_dialog_content = "ゴホゴホッ…お姉様、お父様、どこにいるの？",
  ui_story_5053_50531301_104_dialog_content = "カレン、大丈夫！？",
  ui_story_5053_50531301_105_dialog_content = "うん、ちょっとむせただけ。カレンは大丈夫よ。",
  ui_story_5053_50531301_106_dialog_content = "よかった…",
  ui_story_5053_50531301_107_dialog_content = "ヴェロニカ…カレン…",
  ui_story_5053_50531301_108_dialog_content = "成功です！4人でドラゴンの襲撃を阻止しましたよ！！",
  ui_story_5053_50531301_109_dialog_content = "（思った通り、家族じゃないと「黒の天使」を落ち着かせられないんだ。\nちょっと危険な賭けだったけど、勝ってよかった！）",
  ui_story_5053_50531301_110_dialog_content = "喜ぶのはまだ早い。",
  ui_story_5053_50531301_111_dialog_content = "ドラゴンはエネルギーをためるために、\nひとまず空中に戻り旋回しているにすぎぬ。",
  ui_story_5053_50531301_112_dialog_content = "次の攻撃がまもなく始まるぞ。",
  ui_story_5053_50531301_113_dialog_content = "ならば、次の攻撃の前にやつを一刀両断するまでのこと。",
  ui_story_5053_50531301_114_dialog_content = "一発で弱点を突かなければならん。",
  ui_story_5053_50531301_115_dialog_content = "ドラゴンの弱点は…",
  ui_story_5053_50531301_116_dialog_content = "当然知っている。",
  ui_story_5053_50531301_117_dialog_content = "無駄です。あのドラゴンは「不死性」を持ってるんです。\n傷口もすぐに回復します。",
  ui_story_5053_50531301_118_dialog_content = "なに？",
  ui_story_5053_50531301_119_dialog_content = "城主様、ご報告いたします！暴動が始まりました！",
  ui_story_5053_50531301_120_dialog_content = "計画通りに馬と人を動かし、反逆者どもを包囲せよ。",
  ui_story_5053_50531301_121_dialog_content = "広場のドラゴンは余が引き受ける。\nその他の者たちは民の避難を誘導するのだ。",
  ui_story_5053_50531301_122_dialog_content = "ですが…反乱軍だけでなく、周囲の民衆、\nさらには兵士たちまで暴動に参加し始めています！",
  ui_story_5053_50531301_123_dialog_content = "何だと…！？",
  ui_story_5053_50531301_124_dialog_content = "暴動に加わった者たちの様子もおかしく、理性を失い、\n敵味方に関係なく、生きている者を見境なく攻撃しています。",
  ui_story_5053_50531301_125_dialog_content = "何よりもおかしなことは、そうした者たちに攻撃された者が\n次々と暴動に加わっているのです。まるで…",
  ui_story_5053_50531301_126_dialog_content = "何かに感染したかのようなんですよね？",
  ui_story_5053_50531301_127_dialog_content = "はい。",
  ui_story_5053_50531301_128_dialog_content = "どうやらお主は何か知っているようだな。",
  ui_story_5053_50531301_129_dialog_content = "時間がない。いったいどういうことかすべて話してもらおう。",
  ui_story_5053_50531301_130_dialog_content = "それは…",
  ui_story_5053_50531301_131_dialog_content = "（この世界のソルラドさんもじっとこっちを見てる…）",
  ui_story_5053_50531301_132_dialog_content = "（納得のいく話じゃなければ、きっとそう簡単には許してくれないだろうな）",
  ui_story_5053_50531301_133_dialog_content = "（でも本当のことを言ったら、不信を招くだけだし、\n何とかうまくごまかさないと…うう…）",
  ui_story_5053_50531301_134_dialog_content = "余の前では真実を申せぬというわけか？",
  ui_story_5053_50531301_135_dialog_content = "もしくは、すべての根源はお主らの中にいるとでも？\nたとえば――",
  ui_story_5053_50531301_136_dialog_content = "その頭に翼の生えた怪物だ。",
  ui_story_5053_50531301_137_dialog_content = "そんな風に言わないでください！\n彼女は怪物じゃありません！彼女は…",
  ui_story_5053_50531301_138_dialog_content = "待て。空から、ドラゴンの次の攻撃がまもなく降ってくる。",
  ui_story_5053_50531301_139_dialog_content = "地上では、理性を失った者たちが満ちる潮のようにこの壇を取り囲んでいる。",
  ui_story_5053_50531301_140_dialog_content = "今最もなすべきことは何か分かるはずだ。",
  ui_story_5053_50531301_141_dialog_content = "…もちろん分かっておる。",
  ui_story_5053_50531301_142_dialog_content = "護衛兵、ラションとオットーに伝えよ。\n広場にいる兵士の指揮権を預ける。",
  ui_story_5053_50531301_143_dialog_content = "壇を中心にして防御を固め、民の避難場所とせよ。\nドラゴンは余が引き止める。",
  ui_story_5053_50531301_144_dialog_content = "はっ！仰せのままに！",
  ui_story_5053_50531301_145_dialog_content = "（ソルラドさんが助け舟を出してくれてよかった…\n言えないことがあるって察してくれたんだな）",
  ui_story_5053_50531301_146_dialog_content = "（苦労して時間を稼いだんだ、ムダにしちゃいけない。\n急いでソルラドさんの宮殿に戻らなきゃ！）",
  ui_story_5053_50531301_147_dialog_content = "お姉様、この怪物、どうして私の名前を呼んだの？",
  ui_story_5053_50531301_148_dialog_content = "カレン、近づいてはダメよ。",
  ui_story_5053_50531301_149_dialog_content = "ヴェロニカ…カレン…ケガは…ない…？",
  ui_story_5053_50531301_150_dialog_content = "痛い所は…ない…？",
  ui_story_5053_50531301_151_dialog_content = "痛かったら…お母様が…抱っこして…お歌を歌ってあげるわ…",
  ui_story_5053_50531301_152_dialog_content = "え？わ、私は大丈夫よ。\nカレンも今見てみたけど、ケガしてないわ。",
  ui_story_5053_50531301_153_dialog_content = "あなた…話ができたのね…あなたも、お母様の一部なの？\nそうでしょう？",
  ui_story_5053_50531301_154_dialog_content = "お母様…お母様よ…",
  ui_story_5053_50531301_155_dialog_content = "だったら、もうお父様も含めて、\n私たちを攻撃しないでくれる？",
  ui_story_5053_50531301_156_dialog_content = "ヴェロニカ…お父様…ダニエル…ダニエル…！！！",
  ui_story_5053_50531301_157_dialog_content = "お、お母様は私たちの前でお父様とケンカしたがらなかったはずよ！",
  ui_story_5053_50531301_158_dialog_content = "そうでしょう？",
  ui_story_5053_50531301_159_dialog_content = "……",
  ui_story_5053_50531301_160_dialog_content = "ケンカしないわ…子どもたちが…怖がるから…\nケンカしない…",
  ui_story_5053_50531301_161_dialog_content = "ヴェロニカ…怖がらないで…お母様…ケンカしないわ…",
  ui_story_5053_50531301_162_dialog_content = "うん、ありがとう、お母様。",
  ui_story_5053_50531301_163_dialog_content = "（「黒の天使」はシードによって生まれたもので、\n理性がないってお母様は言ってたけど…）",
  ui_story_5053_50531301_164_dialog_content = "（でも、こうしてきちんと話ができる。\nそれに何だか…優しい感じがする）",
  ui_story_5053_50531301_165_dialog_content = "（宮殿にいたお母様の方が冷たい感じがしたわ。\nどういうことなのかしら…）",
  ui_story_5053_50531301_166_dialog_content = "<size=30>おーい！ミヤ、こっちだよ！</size>",
  ui_story_5053_50531301_167_dialog_content = "PlayerName、お父様！ご無事でしたか！？",
  ui_story_5053_50531301_168_dialog_content = "シーッ、大きな声出しちゃダメだよ。",
  ui_story_5053_50531301_169_dialog_content = "この世界のソルラドさんがドラゴンの相手をしてる間に、\n「黒の天使」と一緒にここを離れよう。",
  ui_story_5053_50531301_170_dialog_content = "「黒の天使」と一緒に…？どこへ行くの？",
  ui_story_5053_50531301_171_dialog_content = "ソルラドさんの宮殿だよ。\nカレブさんとジャキーニが危ないんだ。",
  ui_story_5053_50531301_172_dialog_content = "え？ちょっと待って。いったい何がどうなってるの…？",
  ui_story_5053_50531301_173_dialog_content = "PlayerNameが道すがらすべてを説明してくれるそうだ。\n今はひとまずついていくとしよう。",
  ui_story_5053_50531301_174_dialog_content = "あ、はい…分かりました。",
  ui_story_5053_50531301_175_dialog_content = "ダニエル…",
  ui_story_5053_50531301_176_dialog_content = "PlayerName、この者が余を攻撃しないと確信できるのか？",
  ui_story_5053_50531301_177_dialog_content = "はい、そのはずです…",
  ui_story_5053_50531301_178_dialog_content = "攻撃しません。お母様は私に約束してくれました。\nそうですよね、お母様？",
  ui_story_5053_50531301_179_dialog_content = "約束…したわ…",
  ui_story_5053_50531301_180_dialog_content = "…よかろう。",
  ui_story_5053_50531301_181_dialog_content = "壇の裏側を通って行くとしよう。\nあそこであれば民衆がいない。衛兵が防御を固め終える前に急ぐぞ。",
  ui_story_5053_50531301_182_dialog_content = "お姉様、どこへいらっしゃるの？",
  ui_story_5053_50531301_183_dialog_content = "お父様がこの後Ms.ロトが迎えに来てくれるから、\n2人で大人しく待ってるようにとおっしゃってたわ。",
  ui_story_5053_50531301_184_dialog_content = "カレン、私はちょっと用事があるから、一緒にいられないの。",
  ui_story_5053_50531301_185_dialog_content = "カレンは勇敢ないい子よね。\n1人でMs.ロトを待っていられるわね？",
  ui_story_5053_50531301_186_dialog_content = "カレンは大丈夫よ。ただお姉様のことが心配なの。",
  ui_story_5053_50531301_187_dialog_content = "だって、カレン知ってるもの。\nお姉様はよく一人でこっそり泣いてらっしゃる…",
  ui_story_5053_50531301_188_dialog_content = "でも心配しないで。カレン強くなったの。\nカレンがお姉様を守ってあげる！",
  ui_story_5053_50531301_189_dialog_content = "ふふ、さすが物分かりのいいカレンね。",
  ui_story_5053_50531301_190_dialog_content = "安心して。お姉様はもう以前のような弱いお姉様じゃないわ。",
  ui_story_5053_50531301_191_dialog_content = "だから、私のことばかり心配しなくていいのよ。",
  ui_story_5053_50531301_192_dialog_content = "今まで私はずっとカレンに後れをとってばかりで、\nいつもみんなに迷惑を掛けていたけど…",
  ui_story_5053_50531301_193_dialog_content = "これからは頼りがいのあるお姉様になって、\nカレンの背負う重責も一緒に背負えるように頑張るわ。",
  ui_story_5053_50531301_194_dialog_content = "お姉様…？",
  ui_story_5053_50531301_195_dialog_content = "だから、信じてちょうだい。",
  ui_story_5053_50531301_196_dialog_content = "うん、信じる。",
  ui_story_5053_50531301_197_dialog_content = "ふふ、ありがとう。",
  ui_story_5053_50531301_198_dialog_content = "それじゃあ、さようなら。私の可愛いカレン。",
  ui_story_5053_50531302_1_dialog_content = "…以上が中央広場の状況です。",
  ui_story_5053_50531302_2_dialog_content = "現在広場に通じる検問所はすべて封鎖されています。",
  ui_story_5053_50531302_3_dialog_content = "城主様のご指揮のもと、暴動はすでにほぼ制圧されております。\nどうかご安心ください。",
  ui_story_5053_50531302_4_dialog_content = "…分かったわ。下がっていいわ。",
  ui_story_5053_50531302_5_dialog_content = "わかりました。",
  ui_story_5053_50531302_6_dialog_content = "そうそう、ジャキーニさん。\n部屋のドアを閉めてもらえるかしら？",
  ui_story_5053_50531302_7_dialog_content = "あ、そうですね！鍵を掛けた方が安心ですもんね。\n了解です。",
  ui_story_5053_50531302_8_dialog_content = "カレブ、一つ聞きたいことがあるの。\nなぜわたくしを助けたいの？",
  ui_story_5053_50531302_9_dialog_content = "えっ？",
  ui_story_5053_50531302_10_dialog_content = "え？あなたは僕の姉さんです。\n姉さんを助けるのは当然のことではありませんか。",
  ui_story_5053_50531302_11_dialog_content = "<color=#e8d9bb>トントントン――</color>",
  ui_story_5053_50531302_12_dialog_content = "城主夫人、私です。お迎えに上がりました。\n中に入ってもよろしいでしょうか？",
  ui_story_5053_50531302_13_dialog_content = "は～い、大丈夫ですよ！入ってきてください！",
  ui_story_5053_50531302_14_dialog_content = "ジャキーニさん、あなたは客人ですよ？\nなぜ姉さんより先に答えるのです？",
  ui_story_5053_50531302_15_dialog_content = "…",
  ui_story_5053_50531302_16_dialog_content = "では、失礼致します…",
  ui_story_5053_50531302_17_dialog_content = "Ms.ロト、何か用？",
  ui_story_5053_50531302_18_dialog_content = "今日はご気分がすぐれないとのことでしたので、\n城主様より宮殿に残り、夫人の安全を確保するよう申し付かっております。",
  ui_story_5053_50531302_19_dialog_content = "現在緊急事態が発生しております。\nどうか安全な所へご避難ください。",
  ui_story_5053_50531302_20_dialog_content = "その後広場へ向かい、カレン殿下をお迎えに上がります。\nどうかご安心ください。",
  ui_story_5053_50531302_21_dialog_content = "そうだったの。ありがとう。",
  ui_story_5053_50531302_22_dialog_content = "けれど、わたくしもお客様もここにいれば安全だわ。\nわたくしには構わず、カレンを迎えに行ってちょうだい。",
  ui_story_5053_50531302_23_dialog_content = "それはいけません。",
  ui_story_5053_50531302_24_dialog_content = "それとも…私がここにいては、\nお若い客人お二人を殺せないということですか？",
  ui_story_5053_50531302_25_dialog_content = "こ、殺すですって！？",
  ui_story_5053_50531302_26_dialog_content = "Ms.ロト、何を言うのですか！？姉さんがそんなこと…",
  ui_story_5053_50531302_27_dialog_content = "姉さん…？",
  ui_story_5053_50531302_28_dialog_content = "そうよ、わたくしがそんなことするはずないでしょう？",
  ui_story_5053_50531302_29_dialog_content = "Ms.ロト、あなたいったい何を言っているのかしら？",
  ui_story_5053_50531302_30_dialog_content = "お芝居はもう結構です。",
  ui_story_5053_50531302_31_dialog_content = "武器はスカートの中に隠していますね？\n実に典型的な暗殺です。",
  ui_story_5053_50531302_32_dialog_content = "武器を隠す技は非常に巧妙です。\nしかし、今か今かと待ちきれず武器に手を伸ばす動作がすべてを物語っています。",
  ui_story_5053_50531302_33_dialog_content = "…",
  ui_story_5053_50531302_34_dialog_content = "あなたは腕のいい刺客ですね。",
  ui_story_5053_50531302_35_dialog_content = "私の先生によく似た、けれど似ても似つかないニセモノです。",
  ui_story_5053_50531302_36_dialog_content = "ニセモノですと？ですが…声も容貌も姉さんそのものです。\n僕が間違えるはずありません…！",
  ui_story_5053_50531302_37_dialog_content = "そうですよ。\nしかも記憶の鏡晶が夫人は本物の生きた光霊だって確認してますもん！",
  ui_story_5053_50531302_38_dialog_content = "まさか、他にも生きた光霊が入ってきて、\nヨシュア夫人になりすましてるんですか？",
  ui_story_5053_50531302_39_dialog_content = "お二人がこの刺客とどのような関係かは存じあげませんが、\nお命の安全のためにも、近づいてはなりません。",
  ui_story_5053_50531302_40_dialog_content = "私が思うに、あなたは「あの組織」の残党ではありませんか？\n彼らが育てあげた、もう一人の刺客でしょう？",
  ui_story_5053_50531302_41_dialog_content = "何しろあなたは昔の先生にそっくりですから。",
  ui_story_5053_50531302_42_dialog_content = "けれど、そのためにかえってあなたは今の先生を真似ることが出来ていないのです。\n妻として、母として、姉として生きるヨシュア夫人を。",
  ui_story_5053_50531302_43_dialog_content = "どうです？図星ではありませんか？",
  ui_story_5053_50531302_44_dialog_content = "…",
  ui_story_5053_50531302_45_dialog_content = "ヨ、ヨシュア夫人が武器を握ってます！\nいったいどこから出したんです…？",
  ui_story_5053_50531302_46_dialog_content = "もうっ、でも今はそんなこと構ってられません！\n水晶玉！",
  ui_story_5053_50531302_47_dialog_content = "そんな…あり得ません。姉さんです、どう見ても姉さんではないですか…",
  ui_story_5053_50531302_48_dialog_content = "カレブさん、ぼうっとしてないで、\n戦う気がないなら、どっか行ってください！",
  ui_story_5053_50531302_49_dialog_content = "<size=45>ああああ――！</size>",
  ui_story_5053_50531302_50_dialog_content = "あ、あなたは――！",
  ui_story_5053_50531302_51_dialog_content = "「黒の天使」じゃないですか！",
  ui_story_5053_50531302_52_dialog_content = "「黒の天使」…？",
  ui_story_5053_50531302_53_dialog_content = "カレブ…から…離れて…",
  ui_story_5053_50531302_54_dialog_content = "<size=45>カレブ…から…離れなさい…！！</size>",
  ui_story_5053_50531302_55_dialog_content = "なぜここにいるの！？",
  ui_story_5053_50531302_56_dialog_content = "こないで！気色悪いわ、汚らわしい！",
  ui_story_5053_50531302_57_dialog_content = "逃がしません！",
  ui_story_5053_50531302_58_dialog_content = "ヨシュア夫人が私たちを殺そうとして…\n「黒の天使」がヨシュア夫人を追い出して…",
  ui_story_5053_50531302_59_dialog_content = "な、なななな、何がどうなってるんです！？\n誰か説明してくださいよ！",
  ui_story_5053_50531302_60_dialog_content = "と、止まって！ヒポカ、止まって…！！",
  ui_story_5053_50531302_61_dialog_content = "うわぁ！？今度は窓から大きなクモが入ってきましたよ！？",
  ui_story_5053_50531302_62_dialog_content = "…PlayerName？それからミヤと城主様も一緒じゃないですか！",
  ui_story_5053_50531302_63_dialog_content = "ミヤ、よくやった。\nどうやらお前には光力で召喚物を操る才能があるようだ。",
  ui_story_5053_50531302_64_dialog_content = "はぁ…はぁ…こんな使い方があるなんて初めて知ったんです…",
  ui_story_5053_50531302_65_dialog_content = "うう…クモに乗って建物を伝って移動なんて…\nうっ…吐きそう…",
  ui_story_5053_50531302_66_dialog_content = "いったいどうしたというのです…？",
  ui_story_5053_50531302_67_dialog_content = "カレブさんもジャキーニも無事みたいだね…",
  ui_story_5053_50531302_68_dialog_content = "よかった、間に合って…オエッ…！",
  ui_story_5053_50531401_1_dialog_content = "つまり…私たちは「白の悪魔」にだまされてたってことですか。",
  ui_story_5053_50531401_2_dialog_content = "「黒の天使」も「白の悪魔」もヨシュア夫人の一部分、\nでも和解は難しい…",
  ui_story_5053_50531401_3_dialog_content = "だから私たちを殺して光力を吸収し、\n自由になろうとしたってことですか…",
  ui_story_5053_50531401_4_dialog_content = "不可解かもしれないけど、私には理解できるわ。",
  ui_story_5053_50531401_5_dialog_content = "あの頭が割れるような苦痛ともう一人の自分に対する恐怖…",
  ui_story_5053_50531401_6_dialog_content = "でも、私とバーバ・ヤーガがそうであるように、\nどちらも「私」の一部分なの。",
  ui_story_5053_50531401_7_dialog_content = "私たちはお互いを受け入れることが出来た。\nだから、お母様もきっと…",
  ui_story_5053_50531401_8_dialog_content = "PlayerName、私たちに「白の悪魔」を説得できると思いますか？",
  ui_story_5053_50531401_9_dialog_content = "うーん…それはおそらくヨシュア夫人本人じゃないと分からないよ。",
  ui_story_5053_50531401_10_dialog_content = "僕が分かってるのは、記憶の鏡晶の光力がもうすぐ尽きるってことだけだよ。",
  ui_story_5053_50531401_11_dialog_content = "これが最後のチャンスだ。あれこれ考えてるヒマもない。",
  ui_story_5053_50531401_12_dialog_content = "誠に申し訳ございません。\nもう一人の夫人を捕らえることができませんでした。",
  ui_story_5053_50531401_13_dialog_content = "先程衛兵から報告が入りました。\n広場の方はすでに状況は落ち着き、防御を続けているとのことです。",
  ui_story_5053_50531401_14_dialog_content = "ただドラゴンの疲れを知らぬ攻撃を前に、\n防御があとどれ程持つか分かりません。",
  ui_story_5053_50531401_15_dialog_content = "ご苦労であった。この後の事は我々に任せるがよい。\nMs.ロト、お主は休んでよいぞ。",
  ui_story_5053_50531401_16_dialog_content = "そうは参りません。",
  ui_story_5053_50531401_17_dialog_content = "私の責務は白夜城とソルラド家を守ることです。",
  ui_story_5053_50531401_18_dialog_content = "たとえ幻の世界の幻影にすぎないとしても、\n私が「Ms.ロト」である限り、それは変わりません。",
  ui_story_5053_50531401_19_dialog_content = "己が幻影にすぎぬという事実を即座に受け入れるとは、\nお主の冷静沈着さには実に頭が下がる。",
  ui_story_5053_50531401_20_dialog_content = "いいえ、事実を知ってから、むしろすべてが釈然としました。",
  ui_story_5053_50531401_21_dialog_content = "未来を持たない幻影は、未来を持つ方のように\n常に不安や心配にかられることもなく気楽な気がいたします。",
  ui_story_5053_50531401_22_dialog_content = "真相を知って辛いのは、私よりもカレブ様でしょう。",
  ui_story_5053_50531401_23_dialog_content = "ヨシュアは…過去を誰にも知られたくなかったのだ。",
  ui_story_5053_50531401_24_dialog_content = "彼女の過去は当然多くの批判や咎めを浴びよう。",
  ui_story_5053_50531401_25_dialog_content = "だがそれだけでなく、この事実を弟に知らせる勇気がなかったのやもしれぬ。",
  ui_story_5053_50531401_26_dialog_content = "長い時を経て、ヨシュアもだいぶ明るくなった。\nだがそれは同時に弱さも生むこととなった。",
  ui_story_5053_50531401_27_dialog_content = "夫人の感情が以前よりも豊かになったことは\n喜ばしいことです。",
  ui_story_5053_50531401_28_dialog_content = "けれど時として正直に勇敢に向き合ってこそ、\n問題を解決できるとおっしゃりたいのですね。",
  ui_story_5053_50531401_29_dialog_content = "夫人が現実世界に戻り、目を覚ました時、\nそのことを城主様がぜひ夫人にお伝えくださるよう願っています。",
  ui_story_5053_50531401_30_dialog_content = "そうでなければ、夫人は目覚めた途端、\n城主様への怒りで卒倒してしまうでしょうから。",
  ui_story_5053_50531401_31_dialog_content = "…覚えておこう。",
  ui_story_5053_50531401_32_dialog_content = "ソルラドさん、Ms.ロトとの話は終わりましたか？\n今後の対策を相談しましょう。",
  ui_story_5053_50531401_33_dialog_content = "分かった。",
  ui_story_5053_50531401_34_dialog_content = "…カレブさんは？少しは落ち着きましたか？",
  ui_story_5053_50531401_35_dialog_content = "少しひとりにしておいてやろう。",
  ui_story_5053_50531401_36_dialog_content = "…",
  ui_story_5053_50531401_37_dialog_content = "姉さん…姉さんなのですね…？",
  ui_story_5053_50531401_38_dialog_content = "――！",
  ui_story_5053_50531401_39_dialog_content = "なぜ避けるのですか？",
  ui_story_5053_50531401_40_dialog_content = "まさか…もう一人の姉さんの言っていたように、\n僕を家族と思ったことなど一度もないのですか？",
  ui_story_5053_50531401_41_dialog_content = "…いいえ…",
  ui_story_5053_50531401_42_dialog_content = "怖い…わたくしは…怖いの…",
  ui_story_5053_50531401_43_dialog_content = "怖い？",
  ui_story_5053_50531401_44_dialog_content = "カレブは…姉さんのこと好きだから…姉さんを信じているから…",
  ui_story_5053_50531401_45_dialog_content = "胸が苦しい…頭が…痛い…重みで…息ができない…",
  ui_story_5053_50531401_46_dialog_content = "父さんは…憎しみを捨てて…わたくしたちを守るために…\n亡くなってしまった…わたくしのせいよ…",
  ui_story_5053_50531401_47_dialog_content = "どういうことです…？",
  ui_story_5053_50531401_48_dialog_content = "もう一人の姉さんは、復讐の火種を残すために\n父さんは自ら死を選んだのだと言っていました。",
  ui_story_5053_50531401_49_dialog_content = "それなのにあなたは…父さんは憎しみを捨てたと言う…\nいったい何が真相なのですか？僕にはもう分かりません。",
  ui_story_5053_50531401_50_dialog_content = "ソルラドの父親を暗殺するために、\nあなたはずっと僕の姉を演じていた…",
  ui_story_5053_50531401_51_dialog_content = "実の姉のように…いいえ、実の母のように、\n優しく細やかな心で僕の面倒を見てくれました。",
  ui_story_5053_50531401_52_dialog_content = "僕は姉さんにべったりでしたから、\nきっとストレスになっていたでしょうね。",
  ui_story_5053_50531401_53_dialog_content = "…でも、そんなことはいいのです。\n姉さん、僕にとって姉さんの幸せこそが一番大切なことです。",
  ui_story_5053_50531401_54_dialog_content = "僕のことが嫌いなら、この世界を出た後はもう姉さんにはつきまといません。\n姉さんの望む暮らしを自由に楽しんでください。",
  ui_story_5053_50531401_55_dialog_content = "いいえ…ダメよ…わたくしのそばから…離れないで…",
  ui_story_5053_50531401_56_dialog_content = "わたくしはずっと…だましてきたの…\nわたくしの心は…醜い…だから…怖い…",
  ui_story_5053_50531401_57_dialog_content = "あなたが…わたくしを嫌うのではと…それが…怖い…",
  ui_story_5053_50531401_58_dialog_content = "…",
  ui_story_5053_50531401_59_dialog_content = "そんなことありません。",
  ui_story_5053_50531401_60_dialog_content = "姉さんはこの世界で一番美しく、優しい人です。",
  ui_story_5053_50531401_61_dialog_content = "嫌うわけがないでしょう？",
  ui_story_5053_50531401_62_dialog_content = "じゃあ今皆で話し合ったことをまとめます。",
  ui_story_5053_50531401_63_dialog_content = "現時点ですでに「白の悪魔」のすべての計画は阻止しました。",
  ui_story_5053_50531401_64_dialog_content = "窮地に陥った今、おそらく「白の悪魔」は自分が操れる人たちと\nドラゴンを使って最後の攻撃を仕掛けてくるはず。",
  ui_story_5053_50531401_65_dialog_content = "僕たちは全員そろったし、この世界のソルラドさんが\n白夜城を挙げて攻撃を抑えてくれてはいるけど…",
  ui_story_5053_50531401_66_dialog_content = "記憶の鏡晶の残りの光力では、ドラゴンとは戦えないでしょう。",
  ui_story_5053_50531401_67_dialog_content = "時間も一日の終わりまであと数時間になってしまいました。",
  ui_story_5053_50531401_68_dialog_content = "ということで、まず初めにやるべきことは、簡単かつ有効な方法で、\n短時間で一気に白の悪魔の駒を片付ける――",
  ui_story_5053_50531401_69_dialog_content = "そうして初めて「白の悪魔」を生け捕るチャンスが生まれます。",
  ui_story_5053_50531401_70_dialog_content = "ジャキーニの「記憶の鏡晶」には何か他の機能はないのかしら？\n「白の悪魔」と同じように幻影を操れるとか…",
  ui_story_5053_50531401_71_dialog_content = "うーん…ムリですね！今「記憶の鏡晶」内に残ってる光力じゃ、\nたくさんの機能を使うのはムリです。",
  ui_story_5053_50531401_72_dialog_content = "それにこの「記憶の鏡晶」は緊急危険回避装置にすぎませんから。",
  ui_story_5053_50531401_73_dialog_content = "普通ならこんなに頻繁に使うものじゃないんです…\nすでにとんでもないことをたくさんやらせちゃってるんです。",
  ui_story_5053_50531401_74_dialog_content = "どうしてもっていうなら、\n呪文を作って試してみましょう…！",
  ui_story_5053_50531401_75_dialog_content = "いや、それにはおよばぬ。今は緊急事態だ。\n不確定要素をこれ以上増やすのは避けねばならぬ。",
  ui_story_5053_50531401_76_dialog_content = "アハハ…そうですよね。",
  ui_story_5053_50531401_77_dialog_content = "簡単なことです。",
  ui_story_5053_50531401_78_dialog_content = "奴らを互いに戦わせればいいのです。",
  ui_story_5053_50531401_79_dialog_content = "あれ～？カレブさん、泣き終わったんですか？",
  ui_story_5053_50531401_80_dialog_content = "泣いてなどいません！子ども扱いしないでください！",
  ui_story_5053_50531401_81_dialog_content = "お互いに戦わせる？でも、全員「白の悪魔」に操られてるんだよ？\nどうやったら味方同士で戦わせられるの？",
  ui_story_5053_50531401_82_dialog_content = "ごく簡単なことです。",
  ui_story_5053_50531401_83_dialog_content = "体内の光力のバランスを崩してしまえば、\n奴らはその苦痛で自身の身体の制御能力を失います。",
  ui_story_5053_50531401_84_dialog_content = "光力のバランス？そんなこと初めて聞きました。",
  ui_story_5053_50531401_85_dialog_content = "フッ、光霊には分からないでしょうが、\nそちらの空の末裔には分かるのではありませんか？",
  ui_story_5053_50531401_86_dialog_content = "僕？うーん…確かに僕には光のわずかな違いは分かるけど…",
  ui_story_5053_50531401_87_dialog_content = "どっちつかずの何ともあいまいな答えですね…\nがっかりです。",
  ui_story_5053_50531401_88_dialog_content = "<size=30>PlayerName、私前からカレブさんってどんどん失礼なしゃべり方になってる気がしてたんですけど…\nまさかカレブさんって実はすごく性格悪いんじゃありません？</size>",
  ui_story_5053_50531401_89_dialog_content = "<size=30>アハハハ…ど、どうかな…</size>",
  ui_story_5053_50531401_90_dialog_content = "そこの2人！授業中の私語は厳禁です！",
  ui_story_5053_50531401_91_dialog_content = "カレブ、単刀直入に頼む。\nお主の計画とはどのようなものだ？",
  ui_story_5053_50531401_92_dialog_content = "光力のバランスを崩す薬を作るのです。\n「光力に特化した毒薬」とでも考えてくだされば結構です。",
  ui_story_5053_50531401_93_dialog_content = "「記憶の鏡晶」の中の人物や事物はすべて、\n光力と鏡湖の水の相互作用によって生まれた幻影です。",
  ui_story_5053_50531401_94_dialog_content = "薬はきっと効くはずです。",
  ui_story_5053_50531401_95_dialog_content = "ただし、手持ちの材料は多くないので、\nドラゴンに対して使おうと思います。",
  ui_story_5053_50531401_96_dialog_content = "他の操り人形となった人々は大した存在ではありません。\n苦痛を与えて広場で勝手に騒ぎ出せば――",
  ui_story_5053_50531401_97_dialog_content = "姉さんのもう一つの駒も完全に使えなくなるでしょう。",
  ui_story_5053_50531401_98_dialog_content = "うーん…つまり、ドラゴンに下剤を飲ませて、\n痛みでのたうち回らせればいいってことですね！",
  ui_story_5053_50531401_99_dialog_content = "…まぁ、そんなところでしょうか。",
  ui_story_5053_50531401_100_dialog_content = "実にカレブらしい計画だな。\n何しろお主は幼い頃から、こうした簡単ながら陰湿な手段に長けていた。",
  ui_story_5053_50531401_101_dialog_content = "おや、殿下はまだ覚えてらしたのですか？\nあの紅茶がそんなにも忘れられませんか？",
  ui_story_5053_50531401_102_dialog_content = "（え？それって…カレブさんは昔ソルラドさんに\n下剤を飲ませたことがあるってこと！？）",
  ui_story_5053_50531401_103_dialog_content = "<size=30>ほらやっぱり！カレブさんって性格悪いんですよ！</size>",
  ui_story_5053_50531401_104_dialog_content = "ぷっ…ふふっふふ…",
  ui_story_5053_50531401_105_dialog_content = "ミヤ、何を笑っているのですか？",
  ui_story_5053_50531401_106_dialog_content = "ご、ごめんなさい。どうしてもこらえきれなくて…\nあ、いえ…そういう意味ではないんです…",
  ui_story_5053_50531401_107_dialog_content = "薬は1瓶しかありませんから、チャンスは1回のみです。\nですから、強力な戦士に協力してもらい、ドラゴンの注意を引いてもらわなければいけません。",
  ui_story_5053_50531401_108_dialog_content = "え？強力な戦士って…私ですか！？",
  ui_story_5053_50531401_109_dialog_content = "そうです。急ぎましょう。",
  ui_story_5053_50531401_110_dialog_content = "あ！ちょっと待ってください…",
  ui_story_5053_50531401_111_dialog_content = "カレブさんったらまた勝手にどっか行っちゃいましたよ！\nどうします？追いかけますか？",
  ui_story_5053_50531401_112_dialog_content = "ドラゴンはカレブに任せよう。\nカレブなら必ずやり遂げる。ミヤもいるのだ。",
  ui_story_5053_50531401_113_dialog_content = "ソルラドさん…",
  ui_story_5053_50531401_114_dialog_content = "お主の話では、余は毎回「白の悪魔」の陰謀に遭っても、\n最後まで生き残っていた。だが結末を変えられてはいない。",
  ui_story_5053_50531401_115_dialog_content = "一方お主たち若者の活躍はいつも大きな転機を生み出しておる。",
  ui_story_5053_50531401_116_dialog_content = "これまで余は己のこの手で一切を守らねばならぬと考えてきたが…\nそのような傲慢もそろそろ捨てる時が来たのやもしれぬ。",
  ui_story_5053_50531401_117_dialog_content = "じゃあ私たちはここで待機ですか？",
  ui_story_5053_50531401_118_dialog_content = "左様だ。我々はここで鋭気を養うこととしよう。",
  ui_story_5053_50531401_119_dialog_content = "余の知るヨシュアならば、カードを全て出し切った後、\n必ず自ら姿を現し、最後まで戦うだろう。",
  ui_story_5053_50531401_120_dialog_content = "ヨシュアはそう簡単にはあきらめぬ。",
  ui_story_5053_50531401_121_dialog_content = "それに…",
  ui_story_5053_50531401_122_dialog_content = "…",
  ui_story_5053_50531401_123_dialog_content = "何としても説得せねば。",
  ui_story_5053_50531401_125_dialog_content = "またここへ戻ってきたな。\n夜の食卓へ、余とお主の二人で。",
  ui_story_5053_50531401_126_dialog_content = "…",
  ui_story_5053_50531401_127_dialog_content = "最初にここへ来た時は若かりし頃の自分に姿を変え、\nあの時の気まずい結末を変えたいと思った。",
  ui_story_5053_50531401_128_dialog_content = "お主をこれ以上傷つけたくなかったと言ったところで、\nこの幻の世界の中では、ただの自己満足にすぎぬ。",
  ui_story_5053_50531401_129_dialog_content = "しかも皮肉なことに、お主は目の前でずっとそれを見ていたのだ。\n余の卑劣さをすべて目の当たりにしたのだ、怒りを覚えて当然だ。",
  ui_story_5053_50531401_130_dialog_content = "…ダニ…エル…",
  ui_story_5053_50531401_131_dialog_content = "すべては余がいけなかったのだ。\n余の首はいつでも持っていくがよい。ただ今ではない。",
  ui_story_5053_50531401_132_dialog_content = "あの子たちに罪はない。ここから出してやらねばならん。",
  ui_story_5053_50531401_133_dialog_content = "ゆえにどうか力を貸してくれ。もう一人のお主をとらえ、\n我々と共にこの世界を離れてくれぬか？",
  ui_story_5053_50531401_134_dialog_content = "子どもたちの…未来…あの子たちの未来を…守らないと…",
  ui_story_5053_50531401_135_dialog_content = "承知してくれるのだな。感謝する、ヨシュア…\nもう一度余を信じてくれたことにも…感謝するぞ。",
  ui_story_5053_50531401_136_dialog_content = "…",
  ui_story_5053_50531401_137_dialog_content = "カレブたちが出発してまだ間もない。\n我々はここでしばらく休んでいるとしよう。",
  ui_story_5053_50531401_138_dialog_content = "ヨシュア、お主はまだあの歌を覚えているそうだな？",
  ui_story_5053_50531401_139_dialog_content = "ダウンタウンの…歌よ…幸せな…暮らしを描いた…歌…",
  ui_story_5053_50531401_140_dialog_content = "ああ、その歌だ。実は12年前余はお主に贈り物を用意していたのだ。",
  ui_story_5053_50531401_141_dialog_content = "だが一時の感情で、渡す機会を逃してしまった。\n確か…そうだ、ここだ。",
  ui_story_5053_50531401_142_dialog_content = "レコー…ド？",
  ui_story_5053_50531401_143_dialog_content = "うむ、レコードだ。あの歌を舞曲に編曲させたのだ。気になるか？\nちょうど再生機もある。",
  ui_story_5053_50531401_144_dialog_content = "<color=#e8d9bb>♪～</color>",
  ui_story_5053_50531401_145_dialog_content = "…！",
  ui_story_5053_50531401_146_dialog_content = "気に入ってくれたようだな。よかった。",
  ui_story_5053_50531401_147_dialog_content = "舞曲に編曲したのだ。ただ座って聴いていては味気なかろう。",
  ui_story_5053_50531401_148_dialog_content = "では、美しいご婦人。一曲お願いできますかな？",
  ui_story_5053_50531401_149_dialog_content = "…",
  ui_story_5053_50531401_150_dialog_content = "…",
  ui_story_5053_50531401_151_dialog_content = "ダニ…エル…",
  ui_story_5053_50531401_152_dialog_content = "いかがしたのだ？",
  ui_story_5053_50531401_153_dialog_content = "みんな…元気に…暮らしているの…？",
  ui_story_5053_50531401_154_dialog_content = "…ああ、元気にしている。",
  ui_story_5053_50531401_155_dialog_content = "カレンは今、白夜城護衛隊の隊長だ。\n優秀な部下を持っているだけでなく、多くの友人にも恵まれておる。",
  ui_story_5053_50531401_156_dialog_content = "ミヤは今もイスタバンの世話になっている。\n病状がだいぶ良くなっていてな。昼間は街に出て遊ぶこともあるそうだ。",
  ui_story_5053_50531401_157_dialog_content = "カレブは…黎明学院でよくやっているそうだ。\nただお主のことを恋しがっている。その気持ちは我々の誰よりも強いであろう。",
  ui_story_5053_50531401_158_dialog_content = "あなた…は…？",
  ui_story_5053_50531401_159_dialog_content = "余か？",
  ui_story_5053_50531401_160_dialog_content = "もう余の時代は過ぎた。",
  ui_story_5053_50531401_161_dialog_content = "昔の余は無能で、多くの過ちを犯した。\nだが今は子どもたちが余を越えて、さらなる高みへ向かっておる。",
  ui_story_5053_50531401_162_dialog_content = "余に出来ることは、今の位置に立ち続け、\n子どもたちを下から支え、さらに遠くの未来へと羽ばたかせてやることだ。",
  ui_story_5053_50531401_163_dialog_content = "我々が思い描いた理想の世界が現実となるその日までな。",
  ui_story_5053_50531401_164_dialog_content = "戻ったら、カレブの家で休めるよう計らおう。",
  ui_story_5053_50531401_165_dialog_content = "ヴェロニカも呼び戻してお主と一緒に暮らせるようにしようではないか。\nカレンにも知らせてやれば、一家全員また一緒に過ごせよう。",
  ui_story_5053_50531401_166_dialog_content = "だが…ハハハ、余はもう老いてしまった。お主にはふさわしくなかろう。\nただもしよければ、時々会いに行ってもよいか？",
  ui_story_5053_50531401_167_dialog_content = "家に…帰り…たい…",
  ui_story_5053_50531401_168_dialog_content = "ヨシュア？",
  ui_story_5053_50531401_169_dialog_content = "家に…帰りたいわ…",
  ui_story_5053_50531401_170_dialog_content = "そうだな。共に帰ろう。",
  ui_story_5053_50531401_171_dialog_content = "…ヨシュア、後悔しているか？",
  ui_story_5053_50531401_172_dialog_content = "長い間ずっとこれ程までに苦しみ、怒りに身を焦がしてきたのだ。\nならば、あの時…余を選んだことを後悔しているか？",
  ui_story_5053_50531401_173_dialog_content = "幸せも…愛情も…みんなあなたが教えてくれた。",
  ui_story_5053_50531401_174_dialog_content = "憎しみは…その裏側にあるもの。",
  ui_story_5053_50531401_175_dialog_content = "憎むことは、苦しい…でも…それは深く愛しているから…\nだから…後悔などしていないわ。",
  ui_story_5053_50531401_176_dialog_content = "…",
  ui_story_5053_50531401_177_dialog_content = "そうか…",
  ui_story_5053_50531401_178_dialog_content = "左様であったか…",
  ui_story_5053_50531401_179_dialog_content = "ポイント5設置完了、ポイント6設置完了…",
  ui_story_5053_50531401_180_dialog_content = "よし、ドラゴンを引き付ける爆弾はすべて設置完了です。\n後は起爆装置だけですね。",
  ui_story_5053_50531401_181_dialog_content = "カレブ様、爆弾の設置は順調ですか？\n何かお手伝いすることはございますか？",
  ui_story_5053_50531401_182_dialog_content = "大丈夫です。すべて完了しました。",
  ui_story_5053_50531401_183_dialog_content = "このような短時間で完了させるとは、さすがでございますね。",
  ui_story_5053_50531401_184_dialog_content = "親戚間で他人行儀なお世辞はよしましょう。\nそれに真に賞賛に値するのはあなたです。",
  ui_story_5053_50531401_185_dialog_content = "あなたがいなければ、\n衛兵たちも道を開けてくれなかったでしょう。",
  ui_story_5053_50531401_186_dialog_content = "自身の務めを果たしたまでのことです。\nそれはそうと、お二人とも本当に助けは必要ありませんか？",
  ui_story_5053_50531401_187_dialog_content = "私は「記憶の鏡晶」の中の幻影ですから、\n敵を引き付けるという危険な任務はより適任かと思いますが。",
  ui_story_5053_50531401_188_dialog_content = "そんなこと言わないで、Ms.ロト…",
  ui_story_5053_50531401_189_dialog_content = "それにもっと大切なことを頼みたいの。",
  ui_story_5053_50531401_190_dialog_content = "喜んでお力になります、ヴェロニカ殿下。",
  ui_story_5053_50531401_191_dialog_content = "私の代わりにカレンのそばにいてくれる？\n今カレンは一人でいるはずだから、きっと不安がってるわ。",
  ui_story_5053_50531401_192_dialog_content = "お安い御用でございます。\nですが殿下、お聞きしてもよろしいですか…？",
  ui_story_5053_50531401_193_dialog_content = "私たちはただの幻影にすぎません。\nなぜそれほどまでお気に掛けてくださるのでしょう？",
  ui_story_5053_50531401_194_dialog_content = "だって…あなたたちは私の大切な人と\n同じ顔、同じ性格、同じ思い出をもっているのよ。",
  ui_story_5053_50531401_195_dialog_content = "命の在り方は違っているかもしれないけど、\n同じように感情を抱いて当然だわ。",
  ui_story_5053_50531401_196_dialog_content = "私にとって、みんなとの感情に「現実」も「幻」もないもの。",
  ui_story_5053_50531401_197_dialog_content = "それに…何が犠牲にしていいもので、\n何が重要じゃないかなんて、考えたくないの…",
  ui_story_5053_50531401_198_dialog_content = "そんなことばかり考えてたら、\n本当の自分の気持ちを見失ってしまうわ。",
  ui_story_5053_50531401_199_dialog_content = "ヴェロニカ殿下、以前から殿下はヨシュア夫人に\n似てらっしゃると思っておりましたが、今確信いたしました。",
  ui_story_5053_50531401_200_dialog_content = "そ、そうかしら…？",
  ui_story_5053_50531401_201_dialog_content = "準備は整いました。始めますよ、ミヤ！",
  ui_story_5053_50531401_202_dialog_content = "分かりました。今行きます！\nでは、カレンのこと宜しくお願いします！",
  ui_story_5053_50531401_203_dialog_content = "どうやら私の祈りなど必要ないようですね…\n光はすでにソルラド家の未来を照らしています。",
  ui_story_5053_50531401_204_dialog_content = "…すーっ…ふぅ…",
  ui_story_5053_50531401_205_dialog_content = "このボタンを押せば、爆弾が順番に爆発します。\nそうすれば20秒以内にドラゴンが僕たちの前にやってきます。",
  ui_story_5053_50531401_206_dialog_content = "ミヤ、準備はできましたか？",
  ui_story_5053_50531401_207_dialog_content = "た、だぶん…",
  ui_story_5053_50531401_208_dialog_content = "はぁ…ここまで来て、なぜそんなに自信なさげなんですか！",
  ui_story_5053_50531401_209_dialog_content = "気合入れてください！",
  ui_story_5053_50531401_210_dialog_content = "ごめんなさい…あの、叔父様…",
  ui_story_5053_50531401_211_dialog_content = "簡潔にお願いしますよ。",
  ui_story_5053_50531401_212_dialog_content = "どうして私をこの計画の助手に選んだんですか？",
  ui_story_5053_50531401_213_dialog_content = "強い戦士なら、お父様やMs.ロトのほうがふさわしいでしょう？",
  ui_story_5053_50531401_214_dialog_content = "おや？なぜそんな風に思うのです？",
  ui_story_5053_50531401_215_dialog_content = "こうして一緒に冒険してきたのですから、あなたの実力がどれ程かはよく分かっています。\nそれに召喚物も出せるのでしょう？",
  ui_story_5053_50531401_216_dialog_content = "つまりミヤは機動性において、抜きん出ているのです。\nあなたの他にこの計画にふさわしい人はいませんよ。",
  ui_story_5053_50531401_217_dialog_content = "しょ、召喚物ですか！？",
  ui_story_5053_50531401_218_dialog_content = "ヒポカを召喚した経験はそう多くないので、\nきちんと制御できるかわかりません…",
  ui_story_5053_50531401_219_dialog_content = "あまり召喚したことがないですと？\nめったにない才能に恵まれているというのに、なぜ使わないのです？",
  ui_story_5053_50531401_220_dialog_content = "それは…ヒポカは恐ろしい見た目で、みんなを怖がらせてしまうんです。\n不吉な物事の象徴だって言われましたし…",
  ui_story_5053_50531401_221_dialog_content = "でも、今はそんなふうに思っていません。\n私はもう他人に何か言われたからといって、軽々しく自分を疑ったりしません。",
  ui_story_5053_50531401_222_dialog_content = "ただ、ヒポカとは一緒に戦った経験が本当に数回しかないので、\nどうしても不安で…",
  ui_story_5053_50531401_223_dialog_content = "私たちが失敗したら、みんなの命は…",
  ui_story_5053_50531401_224_dialog_content = "フンッ、そういうことでしたか。\nソルラドのせいでしょう？",
  ui_story_5053_50531401_225_dialog_content = "…",
  ui_story_5053_50531401_226_dialog_content = "貴族たちの目や言葉を気にして、召喚物を使わせなかったのですよね？",
  ui_story_5053_50531401_227_dialog_content = "そうすれば、罵声はすべて召喚物に向き、\nミヤは批判を免れるとでも奴は思ったのでしょうか？",
  ui_story_5053_50531401_228_dialog_content = "え？お父様は私を守るために…？",
  ui_story_5053_50531401_229_dialog_content = "<size=45>くだらない！実にくだらないですね！！</size>",
  ui_story_5053_50531401_230_dialog_content = "え…！？",
  ui_story_5053_50531401_231_dialog_content = "いいですか、ミヤ。貴族たちが悪口を言うのは嫉妬しているからです。\n他人よりも抜きん出ている者を凡人どもは貶めようとするのです。",
  ui_story_5053_50531401_232_dialog_content = "ですから、ソルラドの言うことなど聞いてはいけません。\n誰かに何かを止められたら、むしろ意地でもやり通せばいいのです。それが天才の処世術ですよ！",
  ui_story_5053_50531401_233_dialog_content = "て、天才の処世術ですか？うう…私はやはり、\n周りの人の意見も聞くべきだと思うんですが…",
  ui_story_5053_50531401_234_dialog_content = "いいえ。ミヤは長い間他人にあれこれ言われる生活をしていたからそう思ってしまうのです。\nさあ、僕が教えてあげます。",
  ui_story_5053_50531401_235_dialog_content = "すべての力を解き放ち、その力で身体を支えるのです。\n自分のすべてを身体で感じるのです！",
  ui_story_5053_50531401_236_dialog_content = "あ…？？",
  ui_story_5053_50531401_237_dialog_content = "ミヤは大人しすぎるのです。劇薬が必要です。",
  ui_story_5053_50531401_238_dialog_content = "真に自身の力のすべてを知った時、\n本当の意味でそれを使いこなせるようになるでしょう。",
  ui_story_5053_50531401_239_dialog_content = "自身の力のすべてを知る…",
  ui_story_5053_50531401_240_dialog_content = "（人は未知なるものを恐れる。だから私も怖いんだわ）",
  ui_story_5053_50531401_241_dialog_content = "（叔父様の方法は少し型破りだけど…\n確かに私は自分の力を知る必要があるわ）",
  ui_story_5053_50531401_242_dialog_content = "安心してください。僕もついています。\nまさか僕のことをただの本の虫だとでも思っているのですか？",
  ui_story_5053_50531401_243_dialog_content = "そ、そんなふうに思ったことはありません！\nじゃ、じゃあ…叔父様の言う通り、全力を出してみます！",
  ui_story_5053_50531401_244_dialog_content = "そうこなくては！",
  ui_story_5053_50531401_245_dialog_content = "では、作戦開始です！",
  ui_story_5053_50531501_1_dialog_content = "<color=#e8d9bb>グオォン――</color>",
  ui_story_5053_50531501_2_dialog_content = "ものすごい叫び声だ…宮殿にいてもはっきり聞こえる。",
  ui_story_5053_50531501_3_dialog_content = "爆発が始まってから3分経った。\nその間ずっと色の違う2つの炎が空中でぶつかり合ってる。",
  ui_story_5053_50531501_4_dialog_content = "青はミヤ、赤はドラゴン…",
  ui_story_5053_50531501_5_dialog_content = "あ…！！赤の炎が落ちていく！\nカレブさんとミヤが見事にやり遂げた！",
  ui_story_5053_50531501_6_dialog_content = "どうやらちょうどよい時に来たようだな。",
  ui_story_5053_50531501_7_dialog_content = "はい！今知らせに行こうとしてたところです。",
  ui_story_5053_50531501_8_dialog_content = "話はうまくいきましたか？",
  ui_story_5053_50531501_9_dialog_content = "うむ。これで流れは一気に変わるであろう。",
  ui_story_5053_50531501_10_dialog_content = "白のクイーンよ、最後の一手はいったいどこに置くつもりか…",
  ui_story_5053_50531501_11_dialog_content = "…来たわ…",
  ui_story_5053_50531501_12_dialog_content = "え？何がですか？",
  ui_story_5053_50531501_13_dialog_content = "彼女が…来たわ…！",
  ui_story_5053_50531501_14_dialog_content = "え！？地震？この亀裂は…「白の悪魔」が来る！！",
  ui_story_5053_50531501_15_dialog_content = "PlayerName！",
  ui_story_5053_50531501_16_dialog_content = "クソッ、いったいどういうことです！？",
  ui_story_5053_50531501_17_dialog_content = "ミヤ、カレブさん…2人はドラゴンを倒したんじゃないの？\nどうしてこんなにすぐに戻ってきたの？",
  ui_story_5053_50531501_18_dialog_content = "違うの、私たちにもよく分からないのよ。",
  ui_story_5053_50531501_19_dialog_content = "ドラゴンが落ちた後、中央広場が突然歪み出して崩れたの。\n私と叔父様以外は…",
  ui_story_5053_50531501_20_dialog_content = "みんな白い光になって空へ飛んで行ってしまったわ。",
  ui_story_5053_50531501_21_dialog_content = "逃げている時、手当たり次第に民家のドアを開けたら、\n宮殿に戻っていたの。",
  ui_story_5053_50531501_22_dialog_content = "すぅ…",
  ui_story_5053_50531501_23_dialog_content = "ジャキーニさん、寝ている場合じゃありません！\n大変なことになりました！",
  ui_story_5053_50531501_24_dialog_content = "ん～？あ？誰です？\n私の「記憶の鏡晶」に触らないでください！",
  ui_story_5053_50531501_25_dialog_content = "…あっ…「記憶の鏡晶」が…なんでこんな姿に？",
  ui_story_5053_50531501_26_dialog_content = "ああ…なぜかしらね…",
  ui_story_5053_50531501_27_dialog_content = "なぜ汚らわしく、醜いものを選んだのかしら…？",
  ui_story_5053_50531501_28_dialog_content = "お母様…顔が…",
  ui_story_5053_50531501_29_dialog_content = "顔の割れた所から「黒の天使」と同じ色が見えてる…",
  ui_story_5053_50531501_30_dialog_content = "なぜわたくしを選ばないのかしら…？",
  ui_story_5053_50531501_31_dialog_content = "なぜ「理想」がいかに大切なものか分からないのかしら…？",
  ui_story_5053_50531501_32_dialog_content = "<size=45>なぜなの！！？</size>",
  ui_story_5053_50531501_33_dialog_content = "な、ななな、なんであなたまで「黒の天使」に！？",
  ui_story_5053_50531501_34_dialog_content = "ミヤの言った通りみたいですね。\n2人の本質は同じなんです…",
  ui_story_5053_50531501_35_dialog_content = "はぁ…残念です。大人しく付いてきてくれるように\n説得する時間はありません。水晶玉！",
  ui_story_5053_50531501_36_dialog_content = "ううっ…お母様…ごめんなさい！",
  ui_story_5053_50531501_37_dialog_content = "姉さん…",
  ui_story_5053_50531501_38_dialog_content = "カレブ、今になって何を迷っておる？",
  ui_story_5053_50531501_39_dialog_content = "お主の今の様子は余の気弱な長女にも及ばぬ。",
  ui_story_5053_50531501_40_dialog_content = "黙ってください！\nあなただけは姉さんのことをとやかく言う資格はありません！",
  ui_story_5053_50531501_41_dialog_content = "この世界から出たらケリを付けてやりますから、\n覚悟しておいてください！",
  ui_story_5053_50531501_42_dialog_content = "（こやつは何年たってもこの手に弱いな）",
  ui_story_5053_50531501_43_dialog_content = "…",
  ui_story_5053_50531502_1_dialog_content = "うう…！！",
  ui_story_5053_50531502_2_dialog_content = "ジャキーニ！",
  ui_story_5053_50531502_3_dialog_content = "了解です！！",
  ui_story_5053_50531502_4_dialog_content = "来ないで…",
  ui_story_5053_50531502_5_dialog_content = "あきらめてください、姉さん。",
  ui_story_5053_50531502_6_dialog_content = "来ないで…！",
  ui_story_5053_50531502_7_dialog_content = "これ以上抵抗しても辛くなるだけです。",
  ui_story_5053_50531502_8_dialog_content = "来ないで！！！",
  ui_story_5053_50531502_9_dialog_content = "ソルラドさん！",
  ui_story_5053_50531502_10_dialog_content = "<size=45>「支配者の刃」――</size>",
  ui_story_5053_50531502_11_dialog_content = "うぐっ！！",
  ui_story_5053_50531502_12_dialog_content = "全部…あなたのせい…",
  ui_story_5053_50531502_13_dialog_content = "…",
  ui_story_5053_50531502_14_dialog_content = "全部…あなたのせいで…弱くなったの…",
  ui_story_5053_50531502_15_dialog_content = "ヴェロニカも、カレンも、カレブも、Ms.ロトも…ダニエルも…",
  ui_story_5053_50531502_16_dialog_content = "みんな出来損ないよ、みんな裏切者なのよ！！",
  ui_story_5053_50531502_17_dialog_content = "それなのに、あなたはこの人たちのために「理想」を捨てるというの？\nあなたなんて、邪道な化け物なのに――",
  ui_story_5053_50531502_18_dialog_content = "ミヤ、僕と一緒に姉さんを制しましょう。\nこのまま自分を傷つけさせるわけにはいきません。",
  ui_story_5053_50531502_19_dialog_content = "はい…",
  ui_story_5053_50531502_20_dialog_content = "待て！近づくでない！",
  ui_story_5053_50531502_21_dialog_content = "だったら…わたくしも…大義のために…",
  ui_story_5053_50531502_22_dialog_content = "あなたたちを…消してあげる…",
  ui_story_5053_50531502_23_dialog_content = "…え？風ですか？",
  ui_story_5053_50531502_24_dialog_content = "「記憶の鏡晶」内の光力が白の悪魔に集まっていく！",
  ui_story_5053_50531502_25_dialog_content = "これは…僕たちを道連れにするつもりですか！？",
  ui_story_5053_50531502_26_dialog_content = "ジャキーニ、ここを出る準備だ！\nその他の者は一斉に白の悪魔を制圧せよ！",
  ui_story_5053_50531502_27_dialog_content = "え？今ですか！？",
  ui_story_5053_50531502_28_dialog_content = "姉さんをこのまま連れ出すつもりですか！？",
  ui_story_5053_50531502_29_dialog_content = "お主らを傷つけるのを放っておけば、\nヨシュアが傷つくだけであろう。",
  ui_story_5053_50531502_30_dialog_content = "理想を汚した裏切者はみな死んでしまえばいいのよ！！",
  ui_story_5053_50531502_31_dialog_content = "お母様、どうしてこんなことを！？\n心の底でお母様はずっと私たちをそんなに憎んでいたの？",
  ui_story_5053_50531502_32_dialog_content = "ロニー…悲しまないで…",
  ui_story_5053_50531502_33_dialog_content = "わたくしに任せて…",
  ui_story_5053_50531502_34_dialog_content = "お母様…？",
  ui_story_5053_50531502_35_dialog_content = "チッ、攻撃が効かない！\nミヤ、ぼんやりしていないで戦いに集中して…",
  ui_story_5053_50531502_36_dialog_content = "…姉さん？待ってください、何をするつもりですか？\n近づいてはいけません！",
  ui_story_5053_50531502_37_dialog_content = "…カレブ、ヨシュアを信じろ。",
  ui_story_5053_50531502_38_dialog_content = "ソルラド！放してください！放せ！姉さん！！",
  ui_story_5053_50531502_39_dialog_content = "風が強くて目も開けられません！\nこれじゃあ「記憶の鏡晶」を動かせませんよ！",
  ui_story_5053_50531502_40_dialog_content = "うわぁ！？わ、わわわわ、私、飛んでます…\nた、助けて――",
  ui_story_5053_50531502_41_dialog_content = "ジャキーニ！",
  ui_story_5053_50531502_42_dialog_content = "ふぅ…ありがとうございます、PlayerName…あれ？",
  ui_story_5053_50531502_43_dialog_content = "怖がらないで…もう大丈夫。",
  ui_story_5053_50531502_44_dialog_content = "今度こそしっかりみんなの手を握って、\n絶対に放しちゃダメよ。",
  ui_story_5053_50531502_45_dialog_content = "ね、姉さん…？",
  ui_story_5053_50531502_46_dialog_content = "お母様…お母様だわ…",
  ui_story_5053_50531502_47_dialog_content = "こ…来ないで…",
  ui_story_5053_50531502_48_dialog_content = "もうよしましょう。\nみんなを元の世界に帰すべきよ。",
  ui_story_5053_50531502_49_dialog_content = "こ、来ないで…！！",
  ui_story_5053_50531502_50_dialog_content = "<size=50>ヨシュア！！</size>",
  ui_story_5053_50531601_1_dialog_content = "ようやく見つけたわ。",
  ui_story_5053_50531601_2_dialog_content = "あなたは…？来ないで！！",
  ui_story_5053_50531601_3_dialog_content = "そんなにわたくしのことが嫌い？",
  ui_story_5053_50531601_4_dialog_content = "当り前よ。鏡を見てごらんなさい。\nそんな醜い顔、誰が好きになるというの？",
  ui_story_5053_50531601_5_dialog_content = "そう…実はわたくしもそう思っていたの。",
  ui_story_5053_50531601_6_dialog_content = "でも、家族も友だちもわたくしのこと好いてくれたわ。\nだから、わたくしも自分の姿が好きになったわ。",
  ui_story_5053_50531601_7_dialog_content = "気色悪いわ…",
  ui_story_5053_50531601_8_dialog_content = "自分の姿を見たことはある？",
  ui_story_5053_50531601_9_dialog_content = "もちろん見たことあるわ。表情の練習をするために、\n毎日3時間鏡を見て生きてきたのよ。とうの昔に見飽きているわ。",
  ui_story_5053_50531601_10_dialog_content = "ええ、あなたは勇敢な戦士よ。\n「理想」のためなら何も恐れず、何でもやり遂げる。",
  ui_story_5053_50531601_11_dialog_content = "でも、それは間違いよ。\nあなたにも必ず怖いものがあるはず。たとえば…",
  ui_story_5053_50531601_12_dialog_content = "父さんの死。",
  ui_story_5053_50531601_13_dialog_content = "！？",
  ui_story_5053_50531601_14_dialog_content = "子どもたちや弟が真相を知ること。",
  ui_story_5053_50531601_15_dialog_content = "バカなこと言わないで…",
  ui_story_5053_50531601_16_dialog_content = "夫とすれ違うこと。",
  ui_story_5053_50531601_17_dialog_content = "黙りなさい！！",
  ui_story_5053_50531601_18_dialog_content = "それは全部あなたの恐れることでしょう…わたくしではないわ！\nそんなくだらない感情、わたくしにはないのよ！",
  ui_story_5053_50531601_19_dialog_content = "そんなもの必要ないわ…理想のためにすべて捧げたの。\nそんなもの…必要ない！",
  ui_story_5053_50531601_20_dialog_content = "そうね。あなたはとても単純な生き方を選んだわ。\nそうすれば、幸せではないかもしれないけど、失う痛みは味わなくて済むもの。",
  ui_story_5053_50531601_21_dialog_content = "あなたはそうした痛みを知るのが怖いの。\nだからわたくしをその身体から追い出したのだわ。",
  ui_story_5053_50531601_22_dialog_content = "黙りなさい…それ以上聞きたくないわ。\n黙りなさい…",
  ui_story_5053_50531601_23_dialog_content = "誰も信じないわ。わたくしの言うことには耳を傾けない。\nきっとわたくしを裏切る…",
  ui_story_5053_50531601_24_dialog_content = "人は物ではないの。一人一人自分の考えを持っているわ。",
  ui_story_5053_50531601_25_dialog_content = "「お主を止めたあの日から、ずっと考えていた」",
  ui_story_5053_50531601_26_dialog_content = "「己の夢を他者に託すのは、間違った選択ではないのか」",
  ui_story_5053_50531601_27_dialog_content = "覚えているでしょう？\nダニエルが言った言葉よ。",
  ui_story_5053_50531601_28_dialog_content = "ダニエルはわたくしをだましたわ…",
  ui_story_5053_50531601_29_dialog_content = "わたくしたちがダニエルに頼りすぎていたのよ。\n自分たちの理想をすべて彼に押し付けてしまったわ。",
  ui_story_5053_50531601_30_dialog_content = "よく分かっていたはずよ。城主一家ともなれば、普通の幸せなど望めない。\nでも、その望みを捨てきれなかった。",
  ui_story_5053_50531601_31_dialog_content = "無情な刺客と完璧な城主夫人…",
  ui_story_5053_50531601_32_dialog_content = "2つの役柄の間で行ったり来たりしてきたけれど、いずれも誰かの付属品よ。\nどちらも本当のわたくしではないわ。",
  ui_story_5053_50531601_33_dialog_content = "本当のわたくしは、どこにいるの？",
  ui_story_5053_50531601_34_dialog_content = "…",
  ui_story_5053_50531601_35_dialog_content = "それでもこれだけは分かる。今わたくしは目の前の大切な人たちを失いたくない。\nこの気持ちはどんな感情よりも真実なのよ。",
  ui_story_5053_50531601_36_dialog_content = "だから、もうやめて、行きましょう。",
  ui_story_5053_50531601_37_dialog_content = "痛いわ！どういうことなの？あなたの手にはトゲでも生えているの？\n触られるとすごく痛いわ！",
  ui_story_5053_50531601_38_dialog_content = "でも、とても暖かい…この感覚は何なのかしら？",
  ui_story_5053_50531601_39_dialog_content = "ふふ、それが<color=#FFB400>愛</color>よ。",
  ui_story_5053_50531601_40_dialog_content = "お母様！お母様どこにいらっしゃるの！？\nゴホゴホッ、お母様！",
  ui_story_5053_50531601_41_dialog_content = "ミヤ！こっちだよ、僕の手をつかんで！",
  ui_story_5053_50531601_42_dialog_content = "PlayerName、みんな…お母様はどこ？",
  ui_story_5053_50531601_43_dialog_content = "夫人は…爆発の後…",
  ui_story_5053_50531601_44_dialog_content = "ジャキーニ、呪文を唱えよ。",
  ui_story_5053_50531601_45_dialog_content = "姉さんがいないのなら、僕もここを離れません！！\n放してください！",
  ui_story_5053_50531601_46_dialog_content = "地面が崩壊し始めておる、急げ！",
  ui_story_5053_50531601_47_dialog_content = "わ、分かりました！",
  ui_story_5053_50531601_48_dialog_content = "アド・プラエセンス！",
  ui_story_5053_50531601_49_dialog_content = "私たちを現実の世界へ帰してください！",
  ui_story_5053_50531601_50_dialog_content = "アブラカダブラ！",
  ui_story_5053_50531601_51_dialog_content = "姉さん！僕はここです！姉さん！",
  ui_story_5053_50531601_52_dialog_content = "まったく頑固な若僧だ…\nジャキーニ、ミヤをしっかりつかんでいてくれ！",
  ui_story_5053_50531601_53_dialog_content = "な、何ですか？風が強くてよく聞こえません！！",
  ui_story_5053_50531601_54_dialog_content = "これ以上つかんでられないわ！PlayerName！！",
  ui_story_5053_50531601_55_dialog_content = "あ！！",
  ui_story_5053_50531601_56_dialog_content = "しっかりつかまって。",
  ui_story_5053_50531601_57_dialog_content = "あなたは…？",
  ui_story_5053_50531601_58_dialog_content = "「…、お久しぶりです」",
  ui_story_5053_50531601_59_dialog_content = "「最近いかがですか？僕も皆も元気にしています」",
  ui_story_5053_50531601_60_dialog_content = "手紙書いてるんですか？誰に書いてるんです？",
  ui_story_5053_50531601_61_dialog_content = "わ！？ジャキーニか、ビックリした…",
  ui_story_5053_50531601_62_dialog_content = "えへ、ごめんなさい。",
  ui_story_5053_50531601_63_dialog_content = "PlayerName、こんにちは。",
  ui_story_5053_50531601_64_dialog_content = "こんにちは。2人とも早いね。\nジャキーニはまた遅刻するかと思ってたけど。",
  ui_story_5053_50531601_65_dialog_content = "私の持つ専門知識はなんといっても重要ですからね！\n毎日大勢の人が列を作って私に質問するんですから、忙しくってたまりませんよ～。",
  ui_story_5053_50531601_66_dialog_content = "分かった、分かった。「黎明学院臨時顧問」ジャキーニ先生。",
  ui_story_5053_50531601_67_dialog_content = "えへ、そんなふうにかしこまって呼ばれると、\nちょっと照れちゃいますね…",
  ui_story_5053_50531601_68_dialog_content = "ミヤ、君の方の用事はもう済んだの？",
  ui_story_5053_50531601_69_dialog_content = "ええ、済んだわ。",
  ui_story_5053_50531601_70_dialog_content = "でもカレンは忙しくて、お別れが言えなかったのが残念だわ…",
  ui_story_5053_50531601_71_dialog_content = "大丈夫だよ。次にカレンが巨像に遊びに来たら知らせるから。\n絶対に会わせてあげるよ。",
  ui_story_5053_50531601_72_dialog_content = "いいえ、その必要はないわ。\n何事も自然に任せましょう。",
  ui_story_5053_50531601_73_dialog_content = "そう…",
  ui_story_5053_50531601_74_dialog_content = "「あの後、こっちでも色々なことがありました。\n多くの人が思いもよらなかったような決断をしたんです」",
  ui_story_5053_50531601_75_dialog_content = "「いきさつをすべてお知らせすると約束したので、\n最初からお話しすることにします」",
  ui_story_5053_50531601_76_dialog_content = "「あの時、僕たちは<color=#FFB400>「記憶の鏡晶」</color>の世界から出ることに成功しました」",
  ui_story_5053_50531601_77_dialog_content = "「自分の状況を確めるのも忘れて、カレブさんは飛び出し、\n自宅へと帰って行きました」",
  ui_story_5053_50531601_78_dialog_content = "「僕たちもその後について行き…\nカレブさんが自宅にずっと隠していたヨシュア夫人に会うことができました」",
  ui_story_5053_50531601_79_dialog_content = "お母様の目がかすかに動いたわ…！",
  ui_story_5053_50531601_80_dialog_content = "急いで薬を！左側の棚の薬です！",
  ui_story_5053_50531601_81_dialog_content = "ちょっと待ってくださいよ。\nまだガーゼを探してるところですって！",
  ui_story_5053_50531601_82_dialog_content = "余が持ってくるとしよう。",
  ui_story_5053_50531601_83_dialog_content = "「救命処置のおかげで、ヨシュア夫人は命を取り留め、\n数日後に目を覚ましました」",
  ui_story_5053_50531601_84_dialog_content = "「でも…すべての記憶を失っていました」",
  ui_story_5053_50531601_85_dialog_content = "なぜです？長い間眠っていたからですか？\nそれともあの爆発のせいですか？",
  ui_story_5053_50531601_86_dialog_content = "ですが、姉さんの身体にはもう人格分裂の傾向はまったく見られません。\nこれはいったいどういう…",
  ui_story_5053_50531601_87_dialog_content = "ジャキーニさん、これも「記憶の鏡晶」と関係あるのでしょうか？",
  ui_story_5053_50531601_88_dialog_content = "うーん…その可能性は低いですね。",
  ui_story_5053_50531601_89_dialog_content = "「可能性が低い」とはどういうことです？\n真面目に答えてください。",
  ui_story_5053_50531601_90_dialog_content = "「ヨシュア夫人を助けるためと『記憶の鏡晶』を直すために」",
  ui_story_5053_50531601_91_dialog_content = "「ジャキーニは一時的に白夜城に残り、\nカレブさんと一緒に研究することになりました」",
  ui_story_5053_50531601_92_dialog_content = "「ジャキーニの機嫌を損ねないように、\nカレブさんは黎明学院の臨時顧問という肩書をジャキーニに与えたんです」",
  ui_story_5053_50531601_93_dialog_content = "「ただ、その肩書に実質的意義は何もないようで…\nジャキーニが気付かなければいいんですが…」",
  ui_story_5053_50531601_94_dialog_content = "今唯一分かってることは「白の悪魔」と「黒の天使」が\n何らかの理由で最後には互いを受け入れたってことです。",
  ui_story_5053_50531601_94X1_dialog_content = "それで二重人格の症状が消えて、\nヨシュア夫人の精神は正常に戻ったんです。",
  ui_story_5053_50531601_95_dialog_content = "「シード」については、まだ色々研究しなきゃいけないことがありますが、\nそれはカレブさんに頼るしかありません。",
  ui_story_5053_50531601_96_dialog_content = "ご苦労であった、北境の使者ジャキーニ。\n幾日も白夜城に留まり、カレブの研究を助けてくれたこと感謝する。",
  ui_story_5053_50531601_97_dialog_content = "当然のことをしたまでです。\n生きるか死ぬかの境地を何度もくぐった仲なんですから、もう仲間です！",
  ui_story_5053_50531601_98_dialog_content = "それに…「記憶の鏡晶」に鏡湖の水を注ぎに来たのに、\n「記憶の鏡晶」を壊したらお話になりませんから…",
  ui_story_5053_50531601_99_dialog_content = "あ、そういえば、「記憶の鏡晶」は直りましたよ！\n今はヨシュア夫人も戻ってきましたし、これで本当にいつでも使えますよ！",
  ui_story_5053_50531601_100_dialog_content = "感謝する。誤って何者かが中に入ってしまわぬよう、\nしかと保管しておこう。",
  ui_story_5053_50531601_101_dialog_content = "ハハハ…ただ、実は私、少しカレブさんが心配なんです。\nヨシュア夫人が目を覚ましてから、カレブさんったらずっと夫人に付き添ってるんです！",
  ui_story_5053_50531601_102_dialog_content = "しかも黎明学院の仕事を辞めて、夫人の世話をすると言い出してるとか…\nはぁ…大丈夫でしょうか。",
  ui_story_5053_50531601_103_dialog_content = "まったく…いつまでも子どもで困ったものだ…\nそれはそうとジャキーニ。「キシローナ」という騎士を探してると聞いたが真か？",
  ui_story_5053_50531601_104_dialog_content = "ええ、そうなんです。城主様はよくご存じですね！\nでしたら、紹介していただけませんか？",
  ui_story_5053_50531601_105_dialog_content = "すまぬ、ジャキーニ。キシローナはとうに白夜城を離れてしまったのだ。\n余にはお主の願いをかなえてやることはできぬ。",
  ui_story_5053_50531601_106_dialog_content = "え？でも、一番スゴイ騎士になるのが夢だったんじゃ…",
  ui_story_5053_50531601_107_dialog_content = "啓光に行くがよい。\nだが決してあやつの前で白夜城のことは口にするでないぞ。",
  ui_story_5053_50531601_108_dialog_content = "「記憶の鏡晶」の中で起こったことは現実ではない。\nたとえキシローナと深い縁を結んだとしても…",
  ui_story_5053_50531601_109_dialog_content = "それも長い夢にすぎぬのだ。\n12年の歳月が流れ、人はもう変わっている。",
  ui_story_5053_50531601_110_dialog_content = "そうですか…でも、構いません！\n私たちの初心さえ変わっていなければ、きっとまた友だちになれますから！",
  ui_story_5053_50531601_111_dialog_content = "「初心さえ変わらぬ」か。確かにその通りだな。",
  ui_story_5053_50531601_112_dialog_content = "「僕は最初ヨシュア夫人が記憶を失って、\n家族の皆はまた深い悲しみに沈むのかと思っていました」",
  ui_story_5053_50531601_113_dialog_content = "「でも実際は気を落とすことはありませんでした。\nほんの一瞬の悲しみの後、家族に会えたことの喜びに浸りました」",
  ui_story_5053_50531601_114_dialog_content = "「無事に健康でいてくれればそれで十分…\nこの一家の家族の愛情は本当に純粋で美しいものでした」",
  ui_story_5053_50531601_115_dialog_content = "「ただ<color=#FFB400>城主一家</color>という普通でない地位は、\n平凡な幸せを不可能にしています」",
  ui_story_5053_50531601_116_dialog_content = "<color=#e8d9bb>ナイト・マグヌス家邸宅――カレブ自宅</color>",
  ui_story_5053_50531601_117_dialog_content = "姉さん、ただ今帰りました！見てください、影ノ街で新しく発売になったフルーツ紅茶です！\nきっと姉さんのお口に合いますよ！",
  ui_story_5053_50531601_118_dialog_content = "叔父様、お帰りなさい。",
  ui_story_5053_50531601_119_dialog_content = "お帰りなさい…あら、でも今日は平日よね？\nカレブ、仕事に行かなくていいの？",
  ui_story_5053_50531601_120_dialog_content = "仕事よりも姉さんの方が大切です。\n黎明学院にはすでに辞表を出しました。これからは僕がずっとそばにいます。",
  ui_story_5053_50531601_121_dialog_content = "まあ、辞表ですって？まさかわたくしのために、\n自分の仕事と理想をあきらめるというの？",
  ui_story_5053_50531601_122_dialog_content = "姉さん、そんな風に言わないでください。\n一家で幸せに楽しく暮らすことよりも大事なことなどありません。",
  ui_story_5053_50531601_123_dialog_content = "ミヤもずっと白夜城に戻って家族で暮らしたいと\n思っているのですよ。そうでしょう？",
  ui_story_5053_50531601_124_dialog_content = "あの…実はそのことについてお母様にお話があるの。\n私…これからも影ノ街で暮らそうと思うの。",
  ui_story_5053_50531601_125_dialog_content = "何ですと…ミヤ、なぜ急にそんなことを？\nまさかソルラドにまたいじめられたのですか？",
  ui_story_5053_50531601_126_dialog_content = "いいえ、私自身の考えです。\nお父様も私の意志を応援してくれています。",
  ui_story_5053_50531601_127_dialog_content = "今までは弱くて無力で、お母様と引き離されてから\n辛い思いをしてきたけれど…",
  ui_story_5053_50531601_128_dialog_content = "同時にそのことがあったから、困難に向き合い、白夜城の外の世界を見て、\nそうして成長したのが今の私なんです。でもまだまだ足りません。",
  ui_story_5053_50531601_129_dialog_content = "叔父様もご存じでしょう？最近叔父様がしょっちゅう休暇を取り、\n私もベールをかぶって家を出入りするからアップタウンで噂が広まっているんです。",
  ui_story_5053_50531601_130_dialog_content = "お父様もそれが原因でお母様に会いに来られないんです…\nせっかくお母様を隠したのに。",
  ui_story_5053_50531601_131_dialog_content = "それは知っています！方法も考えていますし、\nいざとなれば白夜城を出て暮らせばいいでしょう！",
  ui_story_5053_50531601_132_dialog_content = "城主夫人が数年を経てよみがえったから何だというのです…",
  ui_story_5053_50531601_133_dialog_content = "ソルラド家を蹴落としたいのなら実力をもってすればいいのです！\nスキャンダルを利用するなど下衆のやることです！",
  ui_story_5053_50531601_134_dialog_content = "ええ、分かっています。私たち家族の過ちではありません。\nでも、私たち家族が背負わなければならないものでもあるんです。",
  ui_story_5053_50531601_135_dialog_content = "私にもようやくお父様の気持ちが分かってきました…\nだからもうお母様を恋しがってばかりはいられません。",
  ui_story_5053_50531601_136_dialog_content = "白夜城の光の下で生きられないのなら、\n私はみんなの「影」になります。",
  ui_story_5053_50531601_137_dialog_content = "影ノ街でイスタバンお父様にもっと多くのことを学んで、\n誰かに守られる弱者から強大な騎士になってみせます。",
  ui_story_5053_50531601_138_dialog_content = "そして私がみんなを守ってあげるんです…！",
  ui_story_5053_50531601_139_dialog_content = "なぜそんな風に思うのです？僕は叔父としてそんなに頼りないのですか？\n姉さん、姉さんからも言ってやってください。",
  ui_story_5053_50531601_140_dialog_content = "カレブ、わたくしには<color=#FFB400>記憶がないの</color>。\n過去がないのだもの、当然過去に未練はないわ。",
  ui_story_5053_50531601_141_dialog_content = "ミヤ、あなたが自分の夢を持ってくれて嬉しいわ。\n頑張るのよ。あなたにはきっと素晴らしい未来が待っている。信じているわ。",
  ui_story_5053_50531601_142_dialog_content = "お母様…ありがとう。",
  ui_story_5053_50531601_143_dialog_content = "それはそうと、ミヤの言葉で思い出したわ。\n外には素晴らしい世界が広がっているのよね。わたくしも見に行くことにしましょう。",
  ui_story_5053_50531601_144_dialog_content = "待ってください。姉さん、それはどういう意味ですか…？",
  ui_story_5053_50531601_145_dialog_content = "「今回の事を経験して、ミヤは別れを選びました」",
  ui_story_5053_50531601_146_dialog_content = "「それはミヤが大人になって初めて自ら下した結論です。\n僕も心から嬉しく思っています」",
  ui_story_5053_50531601_147_dialog_content = "「また、カレブさんの辞表は却下されました」",
  ui_story_5053_50531601_148_dialog_content = "「どうやら以前からよく色々な理由で辞表を出していたようで、\n学院の方も慣れてしまい、いつも通り却下したようです」",
  ui_story_5053_50531601_149_dialog_content = "「一方ヨシュア夫人も刺激を受けて、自分の考えを持つようになりました」",
  ui_story_5053_50531601_150_dialog_content = "「夫人は皆に内緒で白夜城を去り、一人旅に出たのです」",
  ui_story_5053_50531601_151_dialog_content = "PlayerName、ありがとう。巨像でこっそりわたくしを送ってくれて。",
  ui_story_5053_50531601_152_dialog_content = "大したことしていません。\nただ…どうして皆にお別れを言わなかったんですか？",
  ui_story_5053_50531601_153_dialog_content = "あら、そんなの決まっているでしょ。\nもし話したら、きっと簡単には行かせてくれないわ。",
  ui_story_5053_50531601_154_dialog_content = "けれど、わたくしはどうしても離れなければならないわ。\nみんなを守るためでもあり、母と姉としての最後の授業なの。",
  ui_story_5053_50531601_155_dialog_content = "…ヨシュア夫人、本当に記憶喪失なんですか？",
  ui_story_5053_50531601_156_dialog_content = "ふふ、もちろんよ。空の末裔の力を使って、\nこっそりレディの秘密をのぞいたりしてはダメよ。",
  ui_story_5053_50531601_157_dialog_content = "わ、分かりました。じゃあ戻ったら、夫人が白夜城を出たことを皆に知らせます…\nこんなことして君主をだました罪に問われたりしませんよね？",
  ui_story_5053_50531601_158_dialog_content = "ふふ、そうなるかもね。",
  ui_story_5053_50531601_159_dialog_content = "えっ！？",
  ui_story_5053_50531601_160_dialog_content = "冗談よ。ダニエルはとっくにわたくしの考えに気付いているはずよ。\nわたくしたちの間に多くの言葉はいらないの。",
  ui_story_5053_50531601_161_dialog_content = "カレンは…ダニエルにそっくり。あなたはカレンと仲がいいのでしょう？\nだったら分かるわよね？",
  ui_story_5053_50531601_162_dialog_content = "一見強くてよく出来るように見えるけれど、実はずっと無理をしているの。\nだからみんな申し合わせたように何も話さないのよ。",
  ui_story_5053_50531601_163_dialog_content = "カレンなら、自分の知りたい真相を自分の力で見つけることができるわ。\nもしそれが出来ないとしたら…",
  ui_story_5053_50531601_164_dialog_content = "きっとまだ真相を受け入れる準備ができていないのね。",
  ui_story_5053_50531601_165_dialog_content = "…ふふ、偉そうなこと言ったけれど、\n実はわたくしも心に大きな影を隠し持っているわ。",
  ui_story_5053_50531601_166_dialog_content = "「シード」を埋め込まれていなかったら、わたくしは一生自分の中にも\nひそかに抑えてきた恐ろしい一面があることには気づかなかったでしょう。",
  ui_story_5053_50531601_167_dialog_content = "ヨシュア夫人…",
  ui_story_5053_50531601_168_dialog_content = "暖かく包んであげるだけじゃなく、時には厳しくすることも、\n家族同士の思いやりの形ってことですね。",
  ui_story_5053_50531601_169_dialog_content = "その通りよ。暖かさは時として成長の足かせにもなるの。",
  ui_story_5053_50531601_170_dialog_content = "わたくしたちよりも、今のカレンの方がずっと\n信頼できる仲間と志を同じくする友だちが必要よ。",
  ui_story_5053_50531601_171_dialog_content = "だから、PlayerName。お願いしてもいいかしら？\nこれから先もずっとカレンと一緒に成長していって。",
  ui_story_5053_50531601_X171_option_content = "任せてください！",
  ui_story_5053_50531601_X172_option_content = "え、僕ですか…？",
  ui_story_5053_50531601_X173_dialog_content = "あなたは最後の空の末裔、光霊とはまったく異なる種族。\nわたくしはそんなあなたに未来の光を感じたの。",
  ui_story_5053_50531601_X174_dialog_content = "白夜城のような閉鎖的な社会では、\n永遠に見ることのできない宝物よ。",
  ui_story_5053_50531601_X175_dialog_content = "あなたならきっとカレンを…いいえ、もっとたくさんの人たちを\n素晴らしい明日へと導いてくれると信じているわ。",
  ui_story_5053_50531601_X176_dialog_content = "あなたの存在が、ミヤの勇気が、\nわたくしに外の世界には希望が眠っていると教えてくれたの。",
  ui_story_5053_50531601_X177_dialog_content = "もっと広い世界を見たら、わたくしも自分が本当に望むものを\n見つけられるかもしれないわ。",
  ui_story_5053_50531601_X178_dialog_content = "その時が来たら、その貴重な思いを胸に、\n愛する人の元へ戻ってくるでしょう…",
  ui_story_5053_50531601_X179_dialog_content = "「そうして、僕はあの日あなたと別れ、\n夫人が旅立ったという知らせを白夜城に伝えました」",
  ui_story_5053_50531601_X180_dialog_content = "「微笑んで、穏やかに夫人の旅立ちを祝福する人もいれば、\n驚きはしたものの、喜びと共に受け入れる人もいました」",
  ui_story_5053_50531601_X181_dialog_content = "「理解できずにその場を立ち去る人もいた一方で、\nとうにこうなることを予測していたような人もいました」",
  ui_story_5053_50531601_X182_dialog_content = "「でも紆余曲折はあったものの、皆この結末を受け入れ、\n記憶を失った夫人が新しい人生を歩み始めるのをもう止めないと心に決めたのです」",
  ui_story_5053_50531601_X183_dialog_content = "「こっそりと僕と手紙のやりとりを続けていることは、\n絶対に誰にも言いません」",
  ui_story_5053_50531601_X184_dialog_content = "「約束通り、今後あなたの家族の近況をお知らせします」",
  ui_story_5053_50531601_172_dialog_content = "「次に会う時には、旅人同士道中で見聞きした面白い出来事を\n分かち合いたいと思っています」",
  ui_story_5053_50531601_173_dialog_content = "PlayerName！いい加減書くの止めてください！",
  ui_story_5053_50531601_174_dialog_content = "わ！？もうっ…ジャキーニ、また君なの？",
  ui_story_5053_50531601_175_dialog_content = "今回は私を責められませんよ！あなたが手紙を書くのに夢中になってるのがいけないんです。\nミヤと一緒に北境まで送ってくれるって約束したじゃないですか！",
  ui_story_5053_50531601_176_dialog_content = "ちょ、ちょっと待ってて。クーリエに配達をお願いしてるんだ。\nもうすぐ来るはずだよ。",
  ui_story_5053_50531601_177_dialog_content = "ジャキーニが時間通り来るなんて思わなかったな…",
  ui_story_5053_50531601_178_dialog_content = "ちょっと！聞こえてますよ！",
  ui_story_5053_50531601_179_dialog_content = "ふふ、だったらもう少し待ってましょう。",
  ui_story_5053_50531601_180_dialog_content = "そうだ、PlayerName。ハガキは受け取った？",
  ui_story_5053_50531601_181_dialog_content = "ハガキ？",
  ui_story_5053_50531601_182_dialog_content = "あ、ヨシュア夫人からのハガキですね！\n受け取りましたよ！",
  ui_story_5053_50531601_183_dialog_content = "遠方の小さな村に着いたとかで、\nしかも言葉を話す小鳥に出会ったんですって！",
  ui_story_5053_50531601_184_dialog_content = "ええ…たぶん亜人系の光霊ね。その人とはとても気が合って、\n何でも話せる友だちになったと書いてあったわ。",
  ui_story_5053_50531601_185_dialog_content = "そうなの？僕だけ受け取ってないのかな…",
  ui_story_5053_50531601_186_dialog_content = "PlayerNameより私たちの方が待遇いいみたいですね？",
  ui_story_5053_50531601_187_dialog_content = "は、配達が遅れてるだけだよ！\nきっといつか届くはずだよ！",
  ui_story_5053_50531601_188_dialog_content = "こんにちは！クーリエのカラスです！",
  ui_story_5053_50531601_189_dialog_content = "わ、ウワサをすれば何とやらですね！",
  ui_story_5053_50531601_190_dialog_content = "今行くよ！これが手紙、お願いするね。",
  ui_story_5053_50531601_191_dialog_content = "はい、カラス確かに受け取りました。\nで、こっちがPlayerName宛ての手紙です。",
  ui_story_5053_50531601_192_dialog_content = "僕宛て？あ…これは！",
  ui_story_5053_50531601_193_dialog_content = "何か面白いものですか？",
  ui_story_5053_50531601_194_dialog_content = "どうしたの、PlayerName？",
  ui_story_5053_50531601_195_dialog_content = "PlayerName、一緒に見てもいい？",
  ui_story_5053_50531601_196_dialog_content = "あははは、ごめん。君たちには見せられないよ！",
  ui_story_5053_50531601_197_dialog_content = "「PlayerName、いかがお過ごしですか？」",
  ui_story_5053_50531601_198_dialog_content = "「わたくしは今、旅の途中で…」",
  ui_story_5053_50531601_199_dialog_content = "薔薇を一輪♪かわいいあの子に贈りましょう…♪",
  ui_story_5053_50531601_200_dialog_content = "そよ風が頬をなでる\nあなたの笑顔は世界に一つだけの宝物~♪",
  ui_story_5053_50531601_201_dialog_content = "薔薇を一輪♪大切なパパとママに贈りましょう♪",
  ui_story_5053_50531601_202_dialog_content = "どんな時も愛しい家族、私の宝物~♪"
}
